                ? payload.education
                : (payload.education ? [{ degree: typeof payload.education === 'string' ? payload.education : '', school: '', started: '', finished: '', description: sectionText(payload.education, 2000) }] : [])));

    // Calculate accurate, non-overlapping calendar experience
