                school: clamp(e?.school || e?.institution || e?.university, 200),
                started: clamp(e?.started || e?.startDate || e?.begin, 40),
                finished: clamp(e?.finished || e?.endDate || e?.end, 40),
                description: sectionText(e?.description || e?.notes, 2000),
