                            disabled={!aiReadiness.ok}
                            disabledReason={aiReadiness.reason}
                            onRun={runCertIdeas}
                            onAccept={handleCertAccept}
                            onDismiss={() => ai.reset()}
                        />
                    </div>
                </div>
            )}
        </StepShell>
    );
