                            </label>
                            <p className="text-xs text-slate-500">
                                Add notable coursework, awards, senior thesis, or academic highlights.
                            </p>
                        </div>
                        <div className="flex items-center gap-2">
                            {previousDescriptions[education.id] !== undefined && previousDescriptions[education.id] !== education.description && (
                                <button
                                    type="button"
                                    onClick={() => handleUndoEnhance(education.id)}
                                    className="text-xs font-semibold text-slate-500 hover:text-slate-800 transition-colors underline cursor-pointer"
                                >
                                    Undo
                                </button>
                            )}
                            <button
                                type="button"
                                onClick={() => handleToggleBullets(education)}
                                className="inline-flex items-center gap-1 text-xs font-medium text-slate-600 hover:text-slate-900 bg-white hover:bg-slate-100 border border-slate-200 px-2.5 py-1.5 rounded-lg transition-colors cursor-pointer shadow-2xs"
                                title="Toggle bullet point (•) before each line"
                            >
                                <MdFormatListBulleted className="w-3.5 h-3.5 text-slate-600" />
                                <span>Bullets</span>
                            </button>
                            <button
                                type="button"
                                onClick={() => handleEnhanceWithAi(education)}
                                disabled={enhancingId === education.id || (!education.school && !education.degree)}
                                className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold text-indigo-700 bg-indigo-50 hover:bg-indigo-100 hover:text-indigo-900 rounded-lg border border-indigo-200 transition-all shadow-2xs disabled:opacity-50 disabled:cursor-not-allowed cursor-pointer"
                                title={!education.school && !education.degree ? 'Fill in Institution or Degree first' : 'Enhance coursework and academic notes with AI bullet points'}
                            >
                                {enhancingId === education.id ? (
                                    <>
                                        <div className="w-3.5 h-3.5 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin" />
                                        <span>Enhancing...</span>
                                    </>
                                ) : (
                                    <>
                                        <MdAutoAwesome className="w-3.5 h-3.5 text-indigo-600" />
                                        <span>Enhance with AI</span>
                                    </>
                                )}
                            </button>
                        </div>
                    </div>

                    {feedbackMsg && feedbackMsg.id === education.id && (
                        <div className={`text-xs px-2.5 py-1 rounded-md font-medium ${
                            feedbackMsg.type === 'success' ? 'bg-emerald-50 text-emerald-700 border border-emerald-200' :
                            feedbackMsg.type === 'warn' ? 'bg-amber-50 text-amber-700 border border-amber-200' :
                            'bg-rose-50 text-rose-700 border border-rose-200'
                        }`}>
                            {feedbackMsg.text}
                        </div>
                    )}

                    <textarea
                        rows={3}
                        className="w-full text-xs rounded-xl border border-slate-300 p-3 text-slate-800 placeholder-slate-400 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 outline-none transition-colors leading-relaxed"
                        placeholder={`• Relevant Coursework: Distributed Systems, Machine Learning, Computer Networks
• Dean's Honor List across all semesters; 3.92 GPA
• Senior Capstone: Autonomous drone navigation system using ROS and C++`}
                        value={education.description || ''}
                        onChange={(e) => updateEducation(education.id, 'description', e.target.value)}
                        onKeyDown={(e) => handleTextareaKeyDown(e, education)}
                    />

                    {/* Quick starter chips when empty */}
                    {(!education.description || education.description.trim().length === 0) && (
                        <div className="flex items-center gap-1.5 flex-wrap pt-0.5">
                            <span className="text-[11px] text-slate-400 font-medium">Quick ideas:</span>
                            {[
                                "Dean's Honor List",
                                "Relevant Coursework",
                                "Senior Capstone Project",
                                "Magna Cum Laude",
                                "Undergraduate Research Assistant"
                            ].map((chip) => (
                                <button
                                    key={chip}
                                    type="button"
                                    onClick={() => {
                                        const bulletItem = `• ${chip}: `;
                                        const current = (education.description || '').trim();
                                        const updated = current ? `${current}\n${bulletItem}` : bulletItem;
                                        updateEducation(education.id, 'description', updated);
                                    }}
                                    className="text-[11px] font-medium text-slate-600 bg-slate-100 hover:bg-slate-200 hover:text-slate-900 px-2 py-0.5 rounded-md transition-colors cursor-pointer"
                                >
                                    + {chip}
                                </button>
                            ))}
                        </div>
                    )}
                </div>
            </div>
        );
    };

    const renderGuideContent = () => {
        if (!educations || educations.length === 0) return null;
        const targetEdu = educations.find(e => e.id === activeEducationId) || educations[0];
        if (!targetEdu) return null;

        return (
            <div className="mt-4 pt-3.5 border-t border-slate-100 space-y-2.5">
                {educations.length > 1 && (
                    <div className="flex items-center justify-between gap-1.5">
                        <span className="text-[10px] font-black uppercase tracking-wider text-slate-400">
                            Active Qualification
                        </span>
                        <div className="flex items-center gap-1 overflow-x-auto pb-0.5 scrollbar-none max-w-[190px]">
                            {educations.map((edu, idx) => (
                                <button
                                    key={edu.id}
                                    type="button"
                                    onClick={() => setActiveEducationId(edu.id)}
                                    className={`px-2 py-0.5 text-[10px] font-semibold rounded-md transition-all whitespace-nowrap cursor-pointer ${
                                        (targetEdu?.id === edu.id)
                                            ? 'bg-indigo-600 text-white shadow-2xs font-bold'
                                            : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                                    }`}
                                    title={edu.degree || edu.school || `Qualification #${idx + 1}`}
                                >
                                    #{idx + 1}
                                </button>
                            ))}
                        </div>
                    </div>
                )}

                <EducationHealthCard
                    education={targetEdu}
                    targetJd={resumeData.targetJobDescription || ''}
                />
            </div>
        );
    };

    return (
        <StepShell
            stepNumber={3}
            stepPath="education"
            title={t('EducationStep.title', 'Education & qualifications')}
            subtitle={t('EducationStep.subtitle', 'List the qualifications you have completed — exactly as they appear on your documents.')}
            isComplete={hasValidEducation}
            statusBadge={educations.length > 0 ? `${educations.length} ${educations.length === 1 ? 'qualification' : 'qualifications'}` : ''}
            resumeData={resumeData}
            targetJd={resumeData.targetJobDescription || ''}
            guideChildren={renderGuideContent()}
        >
            {educations.length === 0 ? (
                <EmptyState
                    title="Add your first qualification"
                    description="Your highest completed qualification first — the institution, the degree or diploma, and the years. Honors and coursework are optional."
                    primaryAction={{
                        label: 'Add a qualification',
                        icon: <MdAdd className="w-4 h-4" />,
                        onClick: addEducation,
                    }}
                />
            ) : (
                <div className="space-y-3">
                    <EntryList
                        entries={educations.map(education => ({
                            ...education,
                            onMoveUp: () => moveEducation(education.id, -1),
                            onMoveDown: () => moveEducation(education.id, 1),
                            onDuplicate: () => duplicateEducation(education.id),
                            onDelete: () => removeEducation(education.id),
                        }))}
                        renderEntryTitle={(education) => {
                            const health = getEducationHealth(education, resumeData.targetJobDescription || '');
                            return {
                                title: education.degree || 'Degree / Qualification',
                                subtitle: [education.school, education.city].filter(Boolean).join(' · ') || 'Institution',
                                meta: (education.started || education.current || education.finished)
                                    ? `${education.started || '…'} – ${education.current ? 'Present' : (education.finished || '…')}`
                                    : '',
                                badge: health.score >= 85 ? 'ATS Ready' : health.score >= 70 ? 'Strong' : undefined,
                            };
                        }}
                        renderEntry={renderEntryBody}
                    />

                    <button
                        type="button"
                        onClick={addEducation}
                        className="w-full h-11 rounded-xl border border-dashed border-slate-300 hover:border-indigo-400 hover:bg-indigo-50/40 text-sm font-semibold text-slate-700 hover:text-indigo-700 flex items-center justify-center gap-2 transition-colors"
                    >
                        <MdAdd className="w-4 h-4" />
                        Add another qualification
                    </button>
                </div>
            )}
        </StepShell>
    );
};

export default EducationStep;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { MdExpandMore, MdExpandLess, MdAutoAwesome, MdCheck, MdClose } from 'react-icons/md';
import StepShell from '../components/StepShell.jsx';
import Field from '../components/Field.jsx';
import AutocompleteInputField from './components/AutocompleteInputField';
import PhotoUpload from './components/PhotoUpload';
import ConfirmRegenerateModal from './components/ConfirmRegenerateModal';
import { getCandidateContext, extractTargetRoleFromJd } from '../../../utils/candidateContext';
import { extractJdKeywords } from '../../../utils/atsScore';
import { generateUserAiContent, getAiCacheScope } from '../../../services/aiService';
import { matchUniversalDirectory } from '../../../utils/autocompleteDirectories.js';

const aiRoleCache = {};

function getOrganicRoleProgressions(baseRole) {
    const role = String(baseRole || '').trim();
    if (!role || role.length < 2) return [];
    const clean = role.replace(/^(?:Senior|Lead|Principal|Junior|Staff|Chief|Head of|Associate)\s+/i, '').trim();
    return [
        `Senior ${clean}`,
        `Lead ${clean}`,
        `Principal ${clean}`,
        `${clean} Manager`,
        `Director of ${clean}`,
        `${clean} Specialist`,
    ];
}

/**
 * Heading — one form card: name, contact, target title, location.
 * Optional links/extra fields live behind a quiet "Add more details"
 * disclosure. No AI in this step. Gap list lives in the Guide rail.
 */
const HeadingStep = ({ resumeData, updateResumeData, onNavigate }) => {
    const { t } = useTranslation('common');
    const [formData, setFormData] = useState({
        firstname: resumeData?.firstname || '',
        lastname: resumeData?.lastname || '',
        email: resumeData?.email || '',
        phone: resumeData?.phone || '',
        country: resumeData?.country || '',
        city: resumeData?.city || '',
        address: resumeData?.address || '',
        postalcode: resumeData?.postalcode || '',
        occupation: resumeData?.occupation || '',
        photo: resumeData?.photo || null,
        showPhoto: resumeData?.showPhoto !== undefined ? resumeData.showPhoto : true,
        website: resumeData?.website || '',
        linkedin: resumeData?.linkedin || '',
        github: resumeData?.github || '',
    });
    const [targetJd, setTargetJd] = useState(resumeData?.targetJobDescription || '');
    const [targetRole, setTargetRole] = useState(resumeData?.targetRole || '');
    const [errors, setErrors] = useState({});
    const [touched, setTouched] = useState({});
    const [moreOpen, setMoreOpen] = useState(
        Boolean(resumeData?.website || resumeData?.linkedin || resumeData?.github || resumeData?.address || resumeData?.postalcode),
    );

    const [isGeneratingJd, setIsGeneratingJd] = useState(false);
    const [jdAutofillMessage, setJdAutofillMessage] = useState('');
    const [showConfirmModal, setShowConfirmModal] = useState(false);
    const [roleDropdownOpen, setRoleDropdownOpen] = useState(false);
    const [aiRoleSuggestions, setAiRoleSuggestions] = useState([]);
    const [isFetchingAiRoles, setIsFetchingAiRoles] = useState(false);
    const [highlightedIndex, setHighlightedIndex] = useState(-1);
    const roleInputContainerRef = useRef(null);

    const candidateContext = getCandidateContext({ ...resumeData, targetRole }, targetJd || resumeData?.targetJobDescription || '');

    // Keep formData in sync if parent resumeData updates externally
    useEffect(() => {
        if (!resumeData) return;
        setFormData((prev) => ({
            ...prev,
            firstname: resumeData.firstname || '',
            lastname: resumeData.lastname || '',
            email: resumeData.email || '',
            phone: resumeData.phone || '',
            country: resumeData.country || '',
            city: resumeData.city || '',
            address: resumeData.address || '',
            postalcode: resumeData.postalcode || '',
            occupation: resumeData.occupation || '',
            photo: resumeData.photo || null,
            showPhoto: resumeData.showPhoto !== undefined ? resumeData.showPhoto : true,
            website: resumeData.website || '',
            linkedin: resumeData.linkedin || '',
            github: resumeData.github || '',
        }));
        if (resumeData.targetJobDescription !== undefined) {
            setTargetJd(resumeData.targetJobDescription || '');
        }
        if (resumeData.targetRole !== undefined) {
            setTargetRole(resumeData.targetRole || '');
        }
    }, [resumeData]);

    const requiredFields = ['firstname', 'lastname', 'email', 'phone', 'occupation'];

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setFormData((prev) => ({ ...prev, [name]: value }));
        if (errors[name]) validateField(name, value);
    };

    const handleInputBlur = (e) => {
        const { name, value } = e.target;
        setTouched((prev) => ({ ...prev, [name]: true }));
        validateField(name, value);
    };

    const validateField = (name, value) => {
        let error = '';
        if (requiredFields.includes(name) && (!value || String(value).trim() === '')) {
            error = t('HeadingStep.errors.required', { field: name.charAt(0).toUpperCase() + name.slice(1) });
        } else if (name === 'email' && value && !/\S+@\S+\.\S+/.test(String(value))) {
            error = t('HeadingStep.errors.invalidEmail', 'That does not look like a valid email address.');
        } else if (name === 'phone' && value && !/^\+?[1-9][\d]{0,15}$/.test(String(value).replace(/[\s\-()]/g, ''))) {
            error = t('HeadingStep.errors.invalidPhone', 'That does not look like a valid phone number.');
        }
        setErrors((prev) => ({ ...prev, [name]: error }));
        return error === '';
    };

    const handlePhotoChange = (photo) => {
        setFormData((prev) => ({ ...prev, photo }));
    };

    const handleSave = () => {
        let allValid = true;
        requiredFields.forEach((field) => {
            if (!validateField(field, formData[field])) allValid = false;
        });

        const isComplete = requiredFields.every((field) => String(formData[field] || '').trim() !== '') && allValid;
        const completedSteps = [...(resumeData?.completedSteps || [])];
        let updatedCompletedSteps = null;

        if (isComplete && !completedSteps.includes(1)) {
            updatedCompletedSteps = [...completedSteps, 1];
        } else if (!isComplete && completedSteps.includes(1)) {
            updatedCompletedSteps = completedSteps.filter((step) => step !== 1);
        }

        updateResumeData({
            ...formData,
            targetRole,
            targetJobDescription: targetJd,
            ...(updatedCompletedSteps ? { completedSteps: updatedCompletedSteps } : {}),
        });
    };

    // Auto-save on change
    useEffect(() => {
        const timeoutId = setTimeout(() => {
            handleSave();
        }, 500);
        return () => clearTimeout(timeoutId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [formData, targetRole, targetJd]);

    // Unmount flush: synchronously commit form data on step exit
    const formDataRef = useRef(formData);
    const targetRoleRef = useRef(targetRole);
    const targetJdRef = useRef(targetJd);
    const updateResumeDataRef = useRef(updateResumeData);
    const completedStepsRef = useRef(resumeData?.completedSteps || []);
    useEffect(() => { formDataRef.current = formData; }, [formData]);
    useEffect(() => { targetRoleRef.current = targetRole; }, [targetRole]);
    useEffect(() => { targetJdRef.current = targetJd; }, [targetJd]);
    useEffect(() => { updateResumeDataRef.current = updateResumeData; }, [updateResumeData]);
    useEffect(() => { completedStepsRef.current = resumeData?.completedSteps || []; }, [resumeData?.completedSteps]);
    useEffect(() => () => {
        const data = formDataRef.current;
        const complete = requiredFields.every((field) => String(data[field] || '').trim() !== '');
        const completedSteps = [...(completedStepsRef.current || [])];
        let updatedCompletedSteps = null;
        if (complete && !completedSteps.includes(1)) {
            updatedCompletedSteps = [...completedSteps, 1];
        } else if (!complete && completedSteps.includes(1)) {
            updatedCompletedSteps = completedSteps.filter((step) => step !== 1);
        }
        updateResumeDataRef.current({
            ...data,
            targetRole: targetRoleRef.current,
            targetJobDescription: targetJdRef.current,
            ...(updatedCompletedSteps ? { completedSteps: updatedCompletedSteps } : {}),
        });
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const candidateContextRef = useRef(candidateContext);
    useEffect(() => { candidateContextRef.current = candidateContext; }, [candidateContext]);

    // Automatic AI role suggestion fetcher (debounced, with cache)
    useEffect(() => {
        if (!roleDropdownOpen) return;
        const query = String(targetRole || '').trim();
        if (!query || query.length < 2) return;

        let cancelled = false;
        const timer = setTimeout(async () => {
            // Suggestions are personalised by candidate facts: scope the cache to uid|tenant.
            const cacheKey = `${await getAiCacheScope()}_role_${query.toLowerCase()}`;
            if (cancelled) return;
            if (aiRoleCache[cacheKey]) {
                setAiRoleSuggestions(aiRoleCache[cacheKey]);
                return;
            }
            setIsFetchingAiRoles(true);
            try {
                const res = await generateUserAiContent('autocomplete', {
                    type: 'jobTitle',
                    query,
                    context: {
                        facts: candidateContextRef.current?.facts || {},
                        target: { role: query },
                    },
                });
                if (Array.isArray(res?.suggestions) && res.suggestions.length) {
                    aiRoleCache[cacheKey] = res.suggestions;
                    setAiRoleSuggestions(res.suggestions);
                }
            } catch (err) {
                console.warn('[HeadingStep] AI role autocomplete failed:', err);
            } finally {
                setIsFetchingAiRoles(false);
            }
        }, 150);

        return () => { cancelled = true; clearTimeout(timer); };
    }, [roleDropdownOpen, targetRole]);

    const suggestedRoles = useMemo(() => {
        const query = String(targetRole || '').trim().toLowerCase();
        const occ = String(formData.occupation || '').trim();

        // 1. Dynamic seniority progression derived from candidate's actual occupation
        const organicProgressions = occ ? getOrganicRoleProgressions(occ) : [];

        // 2. Candidate's own past role titles from resumeData
        const pastRoles = (resumeData?.employments || [])
            .map((e) => String(e.jobTitle || '').trim())
            .filter((title) => title && title.toLowerCase() !== occ.toLowerCase());

        // 3. Dynamic AI-generated suggestions
        const aiList = aiRoleSuggestions || [];

        // If user is actively typing, prioritize pure AI suggestions
        if (query) {
            const qTokens = query.split(/\s+/).filter((t) => t.length >= 3);
            const matchedAi = aiList.filter((r) => {
                const rLower = String(r || '').toLowerCase();
                return rLower.includes(query) || (qTokens.length > 0 && qTokens.some((tok) => rLower.includes(tok)));
            });

            // Pure AI suggestions take top priority
            if (matchedAi.length > 0) {
                return [...new Set(matchedAi)].slice(0, 8);
            }

            // If AI is currently fetching, keep list clean or show candidate's past roles
            if (isFetchingAiRoles) {
                return [];
            }

            const matchedProg = organicProgressions.filter((r) => r.toLowerCase().includes(query));
            const matchedPast = pastRoles.filter((r) => r.toLowerCase().includes(query));
            const matchedDirectory = matchUniversalDirectory('jobTitle', query, 8);

            const combined = [...matchedProg, ...matchedPast, ...matchedDirectory];
            const seen = new Set();
            const unique = [];
            for (const item of combined) {
                const norm = String(item || '').trim().toLowerCase();
                if (norm && !seen.has(norm)) {
                    seen.add(norm);
                    unique.push(String(item).trim());
                }
            }
            return unique.slice(0, 8);
        }

        // When query is empty (focused or cleared):
        // Dynamically derive recommendations from candidate context or diverse modern careers
        let initialSources = [...organicProgressions, ...pastRoles];

        if (initialSources.length === 0 && resumeData?.educations?.length) {
            const eduField = resumeData.educations[0]?.degree || resumeData.educations[0]?.fieldOfStudy || '';
            if (eduField) {
                const eduMatches = matchUniversalDirectory('jobTitle', eduField.split(/\s+/)[0] || '', 6);
                initialSources = [...initialSources, ...eduMatches];
            }
        }

        if (initialSources.length === 0) {
            // Balanced, cross-industry modern careers across Healthcare, Finance, Engineering, Management, Creative, and Tech
            initialSources = [
                'Registered Nurse (RN)',
                'Senior Financial Analyst',
                'Software Engineer',
                'Product Manager',
                'Civil Project Engineer',
                'UI/UX Product Designer',
                'Operations Manager',
                'Cybersecurity Specialist',
            ];
        }

        const seen = new Set();
        const unique = [];
        for (const item of initialSources) {
            const norm = String(item || '').trim().toLowerCase();
            if (norm && !seen.has(norm)) {
                seen.add(norm);
                unique.push(String(item).trim());
            }
        }
        return unique.slice(0, 8);
    }, [targetRole, formData.occupation, aiRoleSuggestions, resumeData?.employments, resumeData?.educations]);

    useEffect(() => {
        const handleClickOutside = (event) => {
            if (roleInputContainerRef.current && !roleInputContainerRef.current.contains(event.target)) {
                setRoleDropdownOpen(false);
                setHighlightedIndex(-1);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const handleSelectTargetRole = (selectedRole) => {
        setTargetRole(selectedRole);
        targetRoleRef.current = selectedRole;
        setRoleDropdownOpen(false);
        setHighlightedIndex(-1);
        handleSave();
    };

    const handleFetchAiRoleSuggestions = async () => {
        const query = String(targetRole || formData.occupation || '').trim();
        if (!query || isFetchingAiRoles) return;
        setIsFetchingAiRoles(true);
        try {
            const res = await generateUserAiContent('autocomplete', {
                type: 'jobTitle',
                query,
            });
            if (Array.isArray(res?.suggestions) && res.suggestions.length) {
                setAiRoleSuggestions(res.suggestions);
                setRoleDropdownOpen(true);
            }
        } catch (err) {
            console.warn('[HeadingStep] AI role autocomplete failed:', err);
        } finally {
            setIsFetchingAiRoles(false);
        }
    };

    const handleRoleKeyDown = (e) => {
        if (!roleDropdownOpen) {
            if (e.key === 'ArrowDown' || e.key === 'Enter') {
                setRoleDropdownOpen(true);
            }
            return;
        }
        if (e.key === 'ArrowDown') {
            e.preventDefault();
            setHighlightedIndex((prev) => (prev < suggestedRoles.length - 1 ? prev + 1 : 0));
        } else if (e.key === 'ArrowUp') {
            e.preventDefault();
            setHighlightedIndex((prev) => (prev > 0 ? prev - 1 : suggestedRoles.length - 1));
        } else if (e.key === 'Enter') {
            e.preventDefault();
            if (highlightedIndex >= 0 && highlightedIndex < suggestedRoles.length) {
                handleSelectTargetRole(suggestedRoles[highlightedIndex]);
            } else {
                setRoleDropdownOpen(false);
            }
        } else if (e.key === 'Escape') {
            setRoleDropdownOpen(false);
            setHighlightedIndex(-1);
        }
    };

    const executeAutofillJd = async () => {
        const effectiveRole = String(targetRole || formData.occupation || '').trim();
        if (!effectiveRole) return;

        setShowConfirmModal(false);
        setIsGeneratingJd(true);
        setJdAutofillMessage('');
        try {
            const res = await generateUserAiContent('generate-job-description', {
                targetRole: effectiveRole,
                occupation: formData.occupation || '',
            });

            const generatedText = typeof res?.jobDescription === 'string'
                ? res.jobDescription
                : (typeof res?.text === 'string' ? res.text : '');

            if (generatedText) {
                setTargetJd(generatedText);
                targetJdRef.current = generatedText;
                updateResumeData({
                    ...formData,
                    targetRole,
                    targetJobDescription: generatedText,
                });
                setJdAutofillMessage(`✨ Requirements generated and autofilled for ${effectiveRole}!`);
                setTimeout(() => setJdAutofillMessage(''), 5000);
            }
        } catch (err) {
            console.error('[HeadingStep] Failed to generate job description:', err);
            setJdAutofillMessage('Failed to generate requirements. Please try again.');
            setTimeout(() => setJdAutofillMessage(''), 4000);
        } finally {
            setIsGeneratingJd(false);
        }
    };

    const handleAutofillJd = () => {
        const effectiveRole = String(targetRole || formData.occupation || '').trim();
        if (!effectiveRole) {
            setJdAutofillMessage('Please enter or select a Target Job Title first.');
            setTimeout(() => setJdAutofillMessage(''), 4000);
            return;
        }

        if (targetJd && targetJd.trim().length >= 30) {
            setShowConfirmModal(true);
            return;
        }

        executeAutofillJd();
    };

    const completedRequiredFields = requiredFields.filter((field) => String(formData[field] || '').trim() !== '').length;
    const isStepComplete = completedRequiredFields === requiredFields.length;

    return (
        <StepShell
            stepNumber={1}
            stepPath="heading"
            title={t('HeadingStep.title', 'Your details')}
            subtitle={t('HeadingStep.subtitle', 'How recruiters reach you, and the role you are targeting.')}
            isComplete={isStepComplete}
            statusBadge={`${completedRequiredFields}/${requiredFields.length} required fields`}
            resumeData={resumeData}
            targetJd={resumeData?.targetJobDescription || ''}
        >
            <form onSubmit={(e) => e.preventDefault()} className="rounded-xl border border-slate-200 bg-white p-4 sm:p-5 shadow-2xs space-y-5">
                {/* Identity */}
                <div className="space-y-3">
                    <div className="flex flex-col sm:flex-row gap-4 sm:gap-5 items-start">
                        <div className="shrink-0 pt-0.5">
                            <PhotoUpload
                                label=""
                                value={formData.photo}
                                onChange={handlePhotoChange}
                                showPhoto={formData.showPhoto !== false}
                                onToggleShowPhoto={(show) => setFormData(prev => ({ ...prev, showPhoto: show }))}
                                compact
                                hint=""
                            />
                        </div>
                        <div className="flex-1 min-w-0 w-full space-y-3">
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                                <Field
                                    label={t('HeadingStep.fields.firstName.label', 'First name')}
                                    name="firstname"
                                    placeholder={t('HeadingStep.fields.firstName.placeholder', 'Your first name')}
                                    value={formData.firstname}
                                    onChange={handleInputChange}
                                    onBlur={handleInputBlur}
                                    required
                                    error={touched.firstname ? errors.firstname : ''}
                                />
                                <Field
                                    label={t('HeadingStep.fields.lastName.label', 'Last name')}
                                    name="lastname"
                                    placeholder={t('HeadingStep.fields.lastName.placeholder', 'Your last name')}
                                    value={formData.lastname}
                                    onChange={handleInputChange}
                                    onBlur={handleInputBlur}
                                    required
                                    error={touched.lastname ? errors.lastname : ''}
                                />
                            </div>
                            <AutocompleteInputField
                                label={t('HeadingStep.fields.jobTitle.label', 'Target job title')}
                                name="occupation"
                                placeholder={t('HeadingStep.fields.jobTitle.placeholder', 'Enter the job title you are applying for')}
                                value={formData.occupation}
                                onChange={handleInputChange}
                                onBlur={handleInputBlur}
                                required
                                suggestionType="jobTitle"
                                context={candidateContext}
                                error={touched.occupation ? errors.occupation : ''}
                            />
                        </div>
                    </div>
                </div>

                {/* Contact & location */}
                <div className="space-y-3 border-t border-slate-100 pt-4">
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                        <Field
                            label={t('HeadingStep.fields.email.label', 'Email')}
                            name="email"
                            type="email"
                            placeholder={t('HeadingStep.fields.email.placeholder', 'you@example.com')}
                            value={formData.email}
                            onChange={handleInputChange}
                            onBlur={handleInputBlur}
                            required
                            error={touched.email ? errors.email : ''}
                        />
                        <Field
                            label={t('HeadingStep.fields.phone.label', 'Phone')}
                            name="phone"
                            type="tel"
                            inputMode="tel"
                            placeholder={t('HeadingStep.fields.phone.placeholder', 'With country code, e.g. +91 98765 43210')}
                            value={formData.phone}
                            onChange={handleInputChange}
                            onBlur={handleInputBlur}
                            required
                            error={touched.phone ? errors.phone : ''}
                        />
                    </div>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                        <Field
                            label={t('HeadingStep.fields.city.label', 'City')}
                            name="city"
                            placeholder={t('HeadingStep.fields.city.placeholder', 'Enter your city')}
                            value={formData.city}
                            onChange={handleInputChange}
                        />
                        <Field
                            label={t('HeadingStep.fields.country.label', 'Country')}
                            name="country"
                            placeholder={t('HeadingStep.fields.country.placeholder', 'Enter your country')}
                            value={formData.country}
                            onChange={handleInputChange}
                        />
                    </div>
                </div>

                {/* Optional extras */}
                <div className="border-t border-slate-100 pt-3">
                    <button
                        type="button"
                        onClick={() => setMoreOpen(prev => !prev)}
                        aria-expanded={moreOpen}
                        className="flex items-center gap-1.5 text-xs font-semibold text-slate-500 hover:text-slate-800 transition-colors"
                    >
                        {moreOpen ? <MdExpandLess className="w-4 h-4" /> : <MdExpandMore className="w-4 h-4" />}
                        More details (optional)
                    </button>
                    {moreOpen && (
                        <div className="mt-3 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
                            <Field
                                label={t('HeadingStep.fields.address.label', 'Address')}
                                name="address"
                                placeholder={t('HeadingStep.fields.address.placeholder', 'Street address')}
                                value={formData.address}
                                onChange={handleInputChange}
                            />
                            <Field
                                label={t('HeadingStep.fields.postalCode.label', 'Postal code')}
                                name="postalcode"
                                placeholder={t('HeadingStep.fields.postalCode.placeholder', 'PIN / postal code')}
                                value={formData.postalcode}
                                onChange={handleInputChange}
                            />
                            <Field
                                label={t('HeadingStep.fields.linkedin.label', 'LinkedIn')}
                                name="linkedin"
                                placeholder="linkedin.com/in/yourname"
                                value={formData.linkedin}
                                onChange={handleInputChange}
                            />
                            <Field
                                label={t('HeadingStep.fields.website.label', 'Portfolio / website')}
                                name="website"
                                type="url"
                                placeholder="https://yourportfolio.com"
                                value={formData.website}
                                onChange={handleInputChange}
                            />
                            <Field
                                label={t('HeadingStep.fields.github.label', 'Professional profile / repository')}
                                name="github"
                                placeholder="github.com/yourname"
                                value={formData.github}
                                onChange={handleInputChange}
                                className="sm:col-span-2"
                            />
                        </div>
                    )}
                </div>

                {/* Optional Target Job Description Tailoring */}
                <div className="border-t border-slate-100 pt-3">
                    <div className="rounded-xl border border-indigo-100 bg-indigo-50/40 p-3.5 space-y-3">
                        <div className="flex items-center justify-between">
                            <span className="text-xs font-bold text-indigo-950 flex items-center gap-1.5">
                                <span>🎯 Target Role & Job Description (Optional)</span>
                            </span>
                            {(targetJd && targetJd.trim().length > 0) || (targetRole && targetRole.trim().length > 0) ? (
                                <span className="text-[10px] font-bold text-emerald-700 bg-emerald-50 border border-emerald-200 px-1.5 py-0.5 rounded">
                                    Tailored ✓
                                </span>
                            ) : null}
                        </div>
                        <p className="text-[11px] leading-relaxed text-slate-500">
                            Specifying your target role and pasting the job description allows the AI copilot and ATS engine to highlight missing keywords, tailor summaries, and suggest relevant skills across all subsequent steps.
                        </p>
                        {/* Target Role with Auto AI Dropdown */}
                        <div ref={roleInputContainerRef} className="relative">
                            <div className="flex items-center justify-between mb-1">
                                <label className="block text-[11px] font-semibold text-slate-700">
                                    Target Job Title (Optional)
                                </label>
                                <span className="text-[10px] text-slate-400">
                                    Select or type your destination role
                                </span>
                            </div>
                            <div className="relative">
                                <input
                                    type="text"
                                    value={targetRole}
                                    onChange={(e) => {
                                        setTargetRole(e.target.value);
                                        setRoleDropdownOpen(true);
                                    }}
                                    onFocus={() => setRoleDropdownOpen(true)}
                                    onKeyDown={handleRoleKeyDown}
                                    placeholder="e.g. Senior Data Analyst (if transitioning or targeting a different role)"
                                    className="w-full rounded-lg border border-slate-200 bg-white pl-3 pr-16 py-1.5 text-xs text-slate-900 shadow-2xs placeholder:text-slate-400 focus:border-indigo-400 focus:outline-none focus:ring-2 focus:ring-indigo-500/20"
                                />
                                <div className="absolute right-1.5 top-1/2 -translate-y-1/2 flex items-center gap-1">
                                    {targetRole && (
                                        <button
                                            type="button"
                                            onClick={() => {
                                                setTargetRole('');
                                                targetRoleRef.current = '';
                                                handleSave();
                                            }}
                                            className="p-1 text-slate-400 hover:text-slate-600 rounded-md hover:bg-slate-100"
                                            title="Clear target role"
                                        >
                                            <MdClose className="w-3 h-3" />
                                        </button>
                                    )}
                                    <button
                                        type="button"
                                        onClick={() => setRoleDropdownOpen((prev) => !prev)}
                                        className="p-1 text-indigo-600 hover:text-indigo-800 rounded-md hover:bg-indigo-50"
                                        title="Toggle role suggestions"
                                    >
                                        {roleDropdownOpen ? <MdExpandLess className="w-4 h-4" /> : <MdExpandMore className="w-4 h-4" />}
                                    </button>
                                </div>
                            </div>

                            {/* Intelligent Auto AI Dropdown */}
                            {roleDropdownOpen && (
                                <div className="absolute z-30 mt-1 w-full rounded-xl border border-indigo-200/90 bg-white shadow-xl overflow-hidden text-xs">
                                    <div className="flex items-center justify-between px-3 py-1.5 bg-indigo-50/70 border-b border-indigo-100 text-[10px] font-semibold text-indigo-950">
                                        <span className="flex items-center gap-1">
                                            <MdAutoAwesome className="w-3 h-3 text-indigo-600" />
                                            <span>AI Role Suggestions</span>
                                            {isFetchingAiRoles && (
                                                <span className="inline-block w-2.5 h-2.5 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin ml-1"></span>
                                            )}
                                        </span>
                                        <span className="text-slate-400 font-normal">
                                            {suggestedRoles.length} suggestions
                                        </span>
                                    </div>
                                    {suggestedRoles.length === 0 && isFetchingAiRoles && (
                                        <div className="p-4 text-center text-slate-500 text-xs flex items-center justify-center gap-2">
                                            <span className="inline-block w-3 h-3 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin"></span>
                                            <span>Consulting AI for role suggestions…</span>
                                        </div>
                                    )}
                                    <ul className="max-h-56 overflow-y-auto divide-y divide-slate-100 py-1">
                                        {suggestedRoles.map((roleItem, index) => {
                                            const isSelected = targetRole && targetRole.toLowerCase() === roleItem.toLowerCase();
                                            const isHighlighted = index === highlightedIndex;
                                            return (
                                                <li key={roleItem}>
                                                    <button
                                                        type="button"
                                                        onClick={() => handleSelectTargetRole(roleItem)}
                                                        className={`w-full text-left px-3 py-2 flex items-center justify-between transition-colors ${
                                                            isHighlighted || isSelected
                                                                ? 'bg-indigo-50/90 text-indigo-950 font-semibold'
                                                                : 'text-slate-700 hover:bg-slate-50'
                                                        }`}
                                                    >
                                                        <span className="flex items-center gap-1.5">
                                                            <span className="text-indigo-500 font-bold">•</span>
                                                            <span>{roleItem}</span>
                                                        </span>
                                                        {isSelected && (
                                                            <span className="text-[10px] text-emerald-600 font-bold flex items-center gap-0.5">
                                                                <MdCheck className="w-3 h-3" />
                                                                <span>Selected</span>
                                                            </span>
                                                        )}
                                                    </button>
                                                </li>
                                            );
                                        })}
                                        {targetRole && targetRole.trim().length >= 2 && (
                                            <li className="p-1 bg-slate-50/60">
                                                <button
                                                    type="button"
                                                    onClick={handleFetchAiRoleSuggestions}
                                                    disabled={isFetchingAiRoles}
                                                    className="w-full flex items-center justify-center gap-1.5 px-3 py-1.5 text-[11px] font-semibold text-indigo-700 hover:text-indigo-900 bg-white hover:bg-indigo-50/60 border border-indigo-200/70 rounded-lg transition-all shadow-2xs cursor-pointer disabled:opacity-50"
                                                >
                                                    {isFetchingAiRoles ? (
                                                        <>
                                                            <span className="inline-block w-2.5 h-2.5 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin"></span>
                                                            <span>Consulting AI autocomplete…</span>
                                                        </>
                                                    ) : (
                                                        <>
                                                            <MdAutoAwesome className="w-3 h-3 text-indigo-600" />
                                                            <span>More AI suggestions for &ldquo;{targetRole}&rdquo;</span>
                                                        </>
                                                    )}
                                                </button>
                                            </li>
                                        )}
                                    </ul>
                                    <div className="px-3 py-1 bg-slate-50 border-t border-slate-100 text-[10px] text-slate-400 flex items-center justify-between">
                                        <span>Use ↑↓ to navigate, Enter to select</span>
                                        <button
                                            type="button"
                                            onClick={() => setRoleDropdownOpen(false)}
                                            className="text-slate-500 hover:text-slate-800 font-medium"
                                        >
                                            Close
                                        </button>
                                    </div>
                                </div>
                            )}
                        </div>

                        {/* Target Job Description with Manual Autofill Button */}
                        <div>
                            <div className="flex items-center justify-between gap-2 flex-wrap mb-1">
                                <label className="block text-[11px] font-semibold text-slate-700">
                                    Target Job Description / Key Requirements (Optional)
                                </label>
                                <button
                                    type="button"
                                    onClick={handleAutofillJd}
                                    disabled={isGeneratingJd}
                                    className="inline-flex items-center gap-1.5 text-[11px] font-semibold text-indigo-700 hover:text-indigo-900 bg-indigo-50/90 hover:bg-indigo-100 border border-indigo-200/80 rounded-lg px-2.5 py-1 transition-all shadow-2xs disabled:opacity-50 cursor-pointer active:scale-95"
                                    title="Auto-fill realistic requirements using AI for this target role"
                                >
                                    {isGeneratingJd ? (
                                        <>
                                            <span className="inline-block w-3 h-3 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin"></span>
                                            <span>Generating requirements…</span>
                                        </>
                                    ) : (
                                        <>
                                            <MdAutoAwesome className="w-3.5 h-3.5 text-indigo-600" />
                                            <span>Autofill Requirements</span>
                                        </>
                                    )}
                                </button>
                            </div>

                            {jdAutofillMessage && (
                                <div className={`text-[11px] px-2.5 py-1.5 rounded-lg mb-1.5 flex items-center justify-between font-medium ${
                                    jdAutofillMessage.startsWith('✨')
                                        ? 'bg-emerald-50 text-emerald-800 border border-emerald-200'
                                        : 'bg-amber-50 text-amber-800 border border-amber-200'
                                }`}>
                                    <span>{jdAutofillMessage}</span>
                                    <button
                                        type="button"
                                        onClick={() => setJdAutofillMessage('')}
                                        className="text-slate-400 hover:text-slate-600 ml-2"
                                    >
                                        <MdClose className="w-3 h-3" />
                                    </button>
                                </div>
                            )}

                            <textarea
                                rows={3}
                                value={targetJd}
                                onChange={(e) => setTargetJd(e.target.value)}
                                placeholder="Paste the target job description or click 'Autofill Requirements' above to generate realistic expectations for this role…"
                                className="w-full rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs text-slate-900 shadow-2xs placeholder:text-slate-400 focus:border-indigo-400 focus:outline-none focus:ring-2 focus:ring-indigo-500/20"
                            />
                        </div>

                        {(() => {
                            if (!targetJd || targetJd.trim().length < 20) return null;
                            const detectedRole = extractTargetRoleFromJd(targetJd);
                            const extractedKeywords = extractJdKeywords(targetJd, { limit: 6 });
                            return (
                                <div className="mt-2.5 pt-2.5 border-t border-indigo-100/80 space-y-1.5">
                                    <div className="flex items-center justify-between text-[11px] flex-wrap gap-1">
                                        <span className="font-bold text-indigo-950 flex items-center gap-1.5 flex-wrap">
                                            <span>✨ Detected Requirements:</span>
                                            {detectedRole && (
                                                <span className="font-semibold text-indigo-700 bg-indigo-100/70 border border-indigo-200/60 px-1.5 py-0.5 rounded text-[10px]">
                                                    Role: {detectedRole}
                                                </span>
                                            )}
                                        </span>
                                        <span className="text-[10px] text-slate-500">
                                            {extractedKeywords.length} key domains parsed
                                        </span>
                                    </div>
                                    {extractedKeywords.length > 0 && (
                                        <div className="flex flex-wrap gap-1">
                                            {extractedKeywords.map((kw, i) => (
                                                <span key={`kw-${i}`} className="inline-flex items-center px-2 py-0.5 rounded bg-white border border-indigo-200/80 text-[10px] font-medium text-slate-700 shadow-2xs">
                                                    {kw.term}
                                                </span>
                                            ))}
                                        </div>
                                    )}
                                </div>
                            );
                        })()}
                    </div>
                </div>
            </form>
            <ConfirmRegenerateModal
                isOpen={showConfirmModal}
                onClose={() => setShowConfirmModal(false)}
                onConfirm={executeAutofillJd}
                targetRole={String(targetRole || formData.occupation || '').trim()}
                existingTextSnippet={targetJd}
                isGenerating={isGeneratingJd}
            />
        </StepShell>
    );
};

export default HeadingStep;

import React, { useState, useEffect, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { MdAdd, MdClose } from 'react-icons/md';
import StepShell from '../components/StepShell.jsx';
import Field from '../components/Field.jsx';
import AutocompleteInputField from './components/AutocompleteInputField';
import { duplicateResumeItem, moveResumeItem } from '../../../utils/resumeData';
import { getCandidateContext } from '../../../utils/candidateContext';

const PROFICIENCY_LEVELS = [
    'Native / Bilingual',
    'Full Professional (Fluent)',
    'Professional Working (Advanced)',
    'Limited Working (Intermediate)',
    'Elementary (Basic)',
];

/**
 * Languages — minimal list + level select. Interests are a plain chip list.
 * No AI, no regional "recommended" language lists, no hobby suggestions —
 * the candidate's own words only.
 */
const LanguagesStep = ({ resumeData, updateResumeData, onNavigate }) => {
    const { t } = useTranslation('common');
    const [languages, setLanguages] = useState(resumeData.languages || []);
    const [hobbies, setHobbies] = useState(Array.isArray(resumeData.hobbies) ? resumeData.hobbies : (resumeData.hobbies ? [resumeData.hobbies] : []));
    const [hobbyInput, setHobbyInput] = useState('');
    const idCounter = useRef(0);
    const candidateContext = getCandidateContext(resumeData, resumeData.targetJobDescription || '');

    useEffect(() => {
        if (resumeData.languages && Array.isArray(resumeData.languages)) {
            setLanguages(resumeData.languages);
        }
        if (resumeData.hobbies) {
            setHobbies(Array.isArray(resumeData.hobbies) ? resumeData.hobbies : [resumeData.hobbies]);
        }
    }, [resumeData.languages, resumeData.hobbies]);

    const createNewLanguage = (name = '', level = 'Full Professional (Fluent)') => {
        idCounter.current += 1;
        return {
            id: `lang_${Date.now()}_${idCounter.current}`,
            name,
            level,
            date: languages.length + 1,
        };
    };

    const addLanguage = (name = '', level = 'Full Professional (Fluent)') => {
        const newLang = createNewLanguage(name, level);
        setLanguages(prev => [...prev, newLang]);
    };

    const removeLanguage = (id) => {
        setLanguages(prev => prev.filter(lang => lang.id !== id && lang.date !== id));
    };

    const moveLanguage = (id, direction) => setLanguages(current => moveResumeItem(current, id, direction));

    const duplicateLanguage = (id) => setLanguages(current => {
        const source = current.find(item => item.id === id || item.date === id);
        return duplicateResumeItem(current, id, { name: `${source?.name || source?.language || 'Language'} (Copy)` });
    });

    const updateLanguage = (id, field, value) => {
        setLanguages(prev =>
            prev.map(lang => (lang.id === id || lang.date === id ? { ...lang, [field]: value } : lang))
        );
    };

    const addHobby = (hobbyName) => {
        const trimmed = String(hobbyName || hobbyInput || '').trim();
        if (!trimmed) return;
        const exists = hobbies.some(h => {
            const val = typeof h === 'string' ? h : (h?.name || h?.hobby || '');
            return val.toLowerCase() === trimmed.toLowerCase();
        });
        if (!exists) {
            setHobbies(prev => [...prev, trimmed]);
            setHobbyInput('');
        }
    };

    const removeHobby = (index) => {
        setHobbies(prev => prev.filter((_, i) => i !== index));
    };

    const handleSave = () => {
        const hasValid = languages.some(l => String(l?.name || l?.language || l || '').trim() !== '');
        const completedSteps = [...(resumeData.completedSteps || [])];
        let updatedCompletedSteps = null;

        if (hasValid && !completedSteps.includes(7)) {
            updatedCompletedSteps = [...completedSteps, 7];
        } else if (!hasValid && completedSteps.includes(7)) {
            updatedCompletedSteps = completedSteps.filter(step => step !== 7);
        }

        updateResumeData({
            languages,
            hobbies,
            ...(updatedCompletedSteps ? { completedSteps: updatedCompletedSteps } : {}),
        });
    };

    useEffect(() => {
        const timeoutId = setTimeout(() => {
            handleSave();
        }, 500);
        return () => clearTimeout(timeoutId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [languages, hobbies]);

    // Unmount flush: synchronously commit state on step exit
    const languagesRef = useRef(languages);
    const hobbiesRef = useRef(hobbies);
    const updateResumeDataRef = useRef(updateResumeData);
    const completedStepsRef = useRef(resumeData?.completedSteps || []);
    useEffect(() => { languagesRef.current = languages; }, [languages]);
    useEffect(() => { hobbiesRef.current = hobbies; }, [hobbies]);
    useEffect(() => { updateResumeDataRef.current = updateResumeData; }, [updateResumeData]);
    useEffect(() => { completedStepsRef.current = resumeData?.completedSteps || []; }, [resumeData?.completedSteps]);
    useEffect(() => () => {
        const langs = languagesRef.current;
        const hobs = hobbiesRef.current;
        const hasValid = langs.some(l => String(l?.name || l?.language || l || '').trim() !== '');
        const completedSteps = [...(completedStepsRef.current || [])];
        let updatedCompletedSteps = null;
        if (hasValid && !completedSteps.includes(7)) {
            updatedCompletedSteps = [...completedSteps, 7];
        } else if (!hasValid && completedSteps.includes(7)) {
            updatedCompletedSteps = completedSteps.filter(step => step !== 7);
        }
        updateResumeDataRef.current({
            languages: langs,
            hobbies: hobs,
            ...(updatedCompletedSteps ? { completedSteps: updatedCompletedSteps } : {}),
        });
    }, []);

    const hasLanguages = languages.some(l => String(l?.name || l?.language || l || '').trim() !== '');

    return (
        <StepShell
            stepNumber={7}
            stepPath="languages"
            title={t('BuildResume.steps.languages', 'Languages')}
            subtitle={t('BuildResume.languages.subtitle', 'The languages you speak, at the level you are comfortable stating.')}
            isComplete={hasLanguages}
            statusBadge={languages.length > 0 ? `${languages.length} ${languages.length === 1 ? 'language' : 'languages'}` : ''}
            resumeData={resumeData}
            targetJd={resumeData.targetJobDescription || ''}
        >
            <div className="space-y-4">
                {/* Languages */}
                <div className="rounded-xl border border-slate-200 bg-white p-4 sm:p-5 shadow-2xs space-y-3">
                    <h2 className="text-sm font-bold text-slate-900">Languages you speak</h2>

                    {languages.length === 0 && (
                        <p className="text-sm text-slate-400">No languages yet — add the first one below.</p>
                    )}

                    {languages.map((lang, index) => {
                        const itemKey = lang.id || lang.date || `lang-${index}`;
                        const langName = lang.name || lang.language || '';
                        const langLevel = lang.level || 'Full Professional (Fluent)';
                        return (
                            <div key={itemKey} className="grid grid-cols-1 sm:grid-cols-[1fr_1fr_auto] gap-2 items-center">
                                <AutocompleteInputField
                                    label={index === 0 ? 'Language' : undefined}
                                    hideLabel={index !== 0}
                                    placeholder="e.g. English, Spanish, German, Hindi"
                                    value={langName}
                                    onChange={(e) => updateLanguage(itemKey, 'name', e.target.value)}
                                    name={`lang-name-${itemKey}`}
                                    suggestionType="language"
                                    context={candidateContext}
                                />
                                <div>
                                    <label htmlFor={`lang-level-${itemKey}`} className={index === 0 ? 'mb-1.5 block text-[13px] font-semibold text-slate-700' : 'sr-only'}>
                                        Level
                                    </label>
                                    <select
                                        id={`lang-level-${itemKey}`}
                                        value={langLevel}
                                        onChange={(e) => updateLanguage(itemKey, 'level', e.target.value)}
                                        className="w-full rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm text-slate-900 shadow-2xs focus:border-indigo-400 focus:outline-none focus:ring-2 focus:ring-indigo-500/25"
                                    >
                                        {PROFICIENCY_LEVELS.map(level => (
                                            <option key={level} value={level}>{level}</option>
                                        ))}
                                    </select>
                                </div>
                                <div className="flex items-center gap-1 justify-self-end">
                                    <button
                                        type="button"
                                        onClick={() => moveLanguage(itemKey, -1)}
                                        disabled={index === 0}
                                        aria-label="Move language up"
                                        className="p-1.5 rounded text-slate-400 hover:text-slate-700 disabled:opacity-30"
                                        title="Move up"
                                    >↑</button>
                                    <button
                                        type="button"
                                        onClick={() => moveLanguage(itemKey, 1)}
                                        disabled={index === languages.length - 1}
                                        aria-label="Move language down"
                                        className="p-1.5 rounded text-slate-400 hover:text-slate-700 disabled:opacity-30"
                                        title="Move down"
                                    >↓</button>
                                    <button
                                        type="button"
                                        onClick={() => removeLanguage(itemKey)}
                                        aria-label="Remove language"
                                        className="p-1.5 rounded text-slate-400 hover:text-rose-600 hover:bg-rose-50"
                                        title="Remove"
                                    >
                                        <MdClose className="w-4 h-4" />
                                    </button>
                                </div>
                            </div>
                        );
                    })}

                    <button
                        type="button"
                        onClick={() => addLanguage()}
                        className="inline-flex items-center gap-1.5 rounded-lg border border-dashed border-slate-300 hover:border-indigo-400 px-3 py-1.5 text-xs font-semibold text-slate-600 hover:text-indigo-700 transition-colors"
                    >
                        <MdAdd className="w-3.5 h-3.5" />
                        Add a language
                    </button>
                </div>

                {/* Interests */}
                <div className="rounded-xl border border-slate-200 bg-white p-4 sm:p-5 shadow-2xs space-y-3">
                    <h2 className="text-sm font-bold text-slate-900">Interests & activities</h2>
                    <p className="text-xs text-slate-500">Optional. Only ones you would happily discuss in an interview.</p>

                    <div className="flex gap-2">
                        <div className="flex-1">
                            <AutocompleteInputField
                                hideLabel
                                name="hobbyInput"
                                placeholder="Type an activity and press Enter"
                                value={hobbyInput}
                                onChange={(e) => setHobbyInput(e.target.value)}
                                onSelect={(val) => { addHobby(val); setHobbyInput(''); }}
                                onKeyDown={(e) => {
                                    if (e.key === 'Enter') {
                                        e.preventDefault();
                                        addHobby();
                                    }
                                }}
                                suggestionType="hobby"
                                context={candidateContext}
                            />
                        </div>
                        <button
                            type="button"
                            onClick={() => addHobby()}
                            disabled={!String(hobbyInput || '').trim()}
                            className="h-10 px-4 rounded-lg bg-slate-900 hover:bg-slate-800 disabled:opacity-40 text-white text-xs font-semibold flex items-center justify-center gap-1.5 transition-colors shrink-0"
                        >
                            <MdAdd className="w-4 h-4" />
                            Add
                        </button>
                    </div>

                    {hobbies.length > 0 && (
                        <div className="flex flex-wrap gap-1.5 pt-1">
                            {hobbies.map((h, idx) => {
                                const name = typeof h === 'string' ? h : (h.name || h.hobby || '');
                                return (
                                    <span
                                        key={`${name}-${idx}`}
                                        className="inline-flex items-center gap-1.5 rounded-lg border border-slate-200 bg-slate-50 pl-3 pr-2 py-1 text-xs font-semibold text-slate-800"
                                    >
                                        <span>{name}</span>
                                        <button
                                            type="button"
                                            onClick={() => removeHobby(idx)}
                                            className="text-slate-400 hover:text-rose-600 transition-colors"
                                            title="Remove"
                                            aria-label={`Remove ${name}`}
                                        >
                                            <MdClose className="w-3.5 h-3.5" />
                                        </button>
                                    </span>
                                );
                            })}
                        </div>
                    )}
                </div>
            </div>
        </StepShell>
    );
};

export default LanguagesStep;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import {
    MdAdd,
    MdLaunch,
    MdSearch,
    MdClose,
    MdAutoAwesome,
    MdCheckCircle,
    MdContentCopy,
    MdDeleteOutline,
} from 'react-icons/md';
import {
    FaRocket,
    FaBuilding,
    FaCode,
    FaGraduationCap,
} from 'react-icons/fa';
import StepShell from '../components/StepShell.jsx';
import EmptyState from '../components/EmptyState.jsx';
// Architecture: Dedicated elevated Cards view (replaces legacy EntryList accordion)
import Field from '../components/Field.jsx';
import AiRecommendationModal from '../../Form/AiRecommendationModal.jsx';
import { duplicateResumeItem, moveResumeItem } from '../../../utils/resumeData';
import { getCandidateContext } from '../../../utils/candidateContext';
import { getDynamicPlaceholder } from '../../../utils/dynamicPlaceholders';
import { generateUserAiContent } from '../../../services/aiService';

export const PROJECT_TYPES = [
    { id: 'personal', label: 'Personal Build', icon: FaRocket, badgeClass: 'bg-indigo-50 text-indigo-700 border-indigo-200' },
    { id: 'enterprise', label: 'Work / Enterprise', icon: FaBuilding, badgeClass: 'bg-emerald-50 text-emerald-700 border-emerald-200' },
    { id: 'opensource', label: 'Open Source', icon: FaCode, badgeClass: 'bg-purple-50 text-purple-700 border-purple-200' },
    { id: 'academic', label: 'Academic / Research', icon: FaGraduationCap, badgeClass: 'bg-amber-50 text-amber-700 border-amber-200' },
];

// Role-template project ideas were removed in Phase 3:
// recommendations come only from AI for this candidate; on outage the UI says so.

/**
 * 10/10 Projects Step — World-Class Resume Builder Experience:
 * - 2-Tier Header Toolbar: Title, Count Badge, AI Auto-Recommend Projects Modal & Add Project primary action.
 * - Live Search Filter across project titles, roles, technologies, and URLs.
 * - Project Type Segmented Selector (🚀 Personal | 🏢 Enterprise | 💻 Open Source | 🎓 Academic).
 * - Full Profile Consideration: AI recommendations read candidate target role, employments, skills, and JD.
 * - Streamlined 5-Field Project Architecture: Project Name, Role, Technologies, Portfolio URL, and Category.
 * - Interactive AI Recommendation Review Modal with Core vs Recommended separation & multi-select.
 * - Zero-Data Loss Autosaving & Synchronous Step Flush on Unmount.
 * - Zero-Fabrication Safety: Initialized with empty description, strictly preserving invariants.
 */
const ProjectsStep = ({ resumeData, updateResumeData, onNavigate }) => {
    const { t } = useTranslation('common');
    const [projects, setProjects] = useState(resumeData.projects || []);
    const candidateContext = getCandidateContext(resumeData, resumeData.targetJobDescription || '');
    const targetJd = resumeData.targetJobDescription || '';

    // Search and Filter States
    const [searchQuery, setSearchQuery] = useState('');
    const [selectedTypeFilter, setSelectedTypeFilter] = useState('all');

    // AI Modal and Feedback States
    const [isAiGenerating, setIsAiGenerating] = useState(false);
    const [toastState, setToastState] = useState(null);
    const [aiModalState, setAiModalState] = useState({
        isOpen: false,
        title: '',
        items: [],
        onApply: null,
    });

    useEffect(() => {
        if (resumeData.projects && Array.isArray(resumeData.projects)) {
            setProjects(resumeData.projects);
        }
    }, [resumeData.projects]);

    const triggerToast = (msg, type = 'success') => {
        setToastState({ msg, type });
        setTimeout(() => setToastState(null), 3500);
    };

    const createNewProject = (title = '', role = '', technologies = '', projectType = 'personal') => ({
        id: Date.now() + Math.floor(Math.random() * 1000),
        title: title || '',
        role: role || '',
        technologies: technologies || '',
        url: '',
        description: '',
        projectType: projectType || 'personal',
    });

    const addProject = () => {
        const newProject = createNewProject();
        setProjects(prev => [...prev, newProject]);
        triggerToast('Added new project entry. Fill in the details below!');
    };

    const removeProject = (id) => {
        setProjects(prev => prev.filter(p => p.id !== id));
        triggerToast('Project removed.', 'info');
    };

    const moveProject = (id, direction) => setProjects(current => moveResumeItem(current, id, direction));

    const duplicateProject = (id) => setProjects(current => {
        const source = current.find(p => p.id === id);
        triggerToast(`Duplicated "${source?.title || 'Project'}"`);
        return duplicateResumeItem(current, id, { title: `${source?.title || 'Project'} (Copy)` });
    });

    const updateProject = (id, field, value) => {
        setProjects(prev => prev.map(p => (p.id === id ? { ...p, [field]: value } : p)));
    };

    // Auto-save on change
    useEffect(() => {
        const timer = setTimeout(() => {
            const validProjects = projects.filter(p => String(p?.title || p?.name || '').trim() !== '');

            const completedSteps = [...(resumeData.completedSteps || [])];
            let updatedCompletedSteps = null;
            if (validProjects.length > 0 && !completedSteps.includes(5)) {
                updatedCompletedSteps = [...completedSteps, 5];
            } else if (validProjects.length === 0 && completedSteps.includes(5)) {
                updatedCompletedSteps = completedSteps.filter(step => step !== 5);
            }

            updateResumeData({
                projects,
                ...(updatedCompletedSteps ? { completedSteps: updatedCompletedSteps } : {}),
            });
        }, 500);
        return () => clearTimeout(timer);
    }, [projects]); // eslint-disable-line react-hooks/exhaustive-deps

    // Unmount flush: synchronously commit state on step exit
    const projectsRef = useRef(projects);
    const updateResumeDataRef = useRef(updateResumeData);
    const completedStepsRef = useRef(resumeData?.completedSteps || []);
    useEffect(() => { projectsRef.current = projects; }, [projects]);
    useEffect(() => { updateResumeDataRef.current = updateResumeData; }, [updateResumeData]);
    useEffect(() => { completedStepsRef.current = resumeData?.completedSteps || []; }, [resumeData?.completedSteps]);
    useEffect(() => () => {
        const projs = projectsRef.current;
        const validProjects = projs.filter(p => String(p?.title || p?.name || '').trim() !== '');
        const completedSteps = [...(completedStepsRef.current || [])];
        let updatedCompletedSteps = null;
        if (validProjects.length > 0 && !completedSteps.includes(5)) {
            updatedCompletedSteps = [...completedSteps, 5];
        } else if (validProjects.length === 0 && completedSteps.includes(5)) {
            updatedCompletedSteps = completedSteps.filter(step => step !== 5);
        }
        updateResumeDataRef.current({
            projects: projs,
            ...(updatedCompletedSteps ? { completedSteps: updatedCompletedSteps } : {}),
        });
    }, []);

    // Filter projects according to search query and selected type tab
    const filteredProjects = useMemo(() => {
        return projects.filter(p => {
            const query = searchQuery.trim().toLowerCase();
            const matchesSearch = !query || [
                p.title,
                p.role,
                p.technologies,
                p.url,
            ].some(val => String(val || '').toLowerCase().includes(query));

            const matchesType = selectedTypeFilter === 'all' || (p.projectType || 'personal') === selectedTypeFilter;
            return matchesSearch && matchesType;
        });
    }, [projects, searchQuery, selectedTypeFilter]);

    // Handle AI Project Recommendations with Full Candidate Profile Consideration
    const handleRecommendAiProjects = async () => {
        const effectiveRole = String(
            candidateContext?.target?.role ||
            resumeData.targetRole ||
            resumeData.occupation ||
            resumeData.title ||
            resumeData.targetJobTitle ||
            (resumeData.employments?.[0]?.jobTitle || resumeData.workExperience?.[0]?.jobTitle || resumeData.workExperiences?.[0]?.jobTitle) ||
            (resumeData.educations?.[0]?.degree || resumeData.education?.[0]?.degree) ||
            ''
        ).trim();

        const candidateSkills = (resumeData.skills || []).map(s => typeof s === 'object' ? (s.skillName || s.name) : s).filter(Boolean);
        const candidateEmployments = (resumeData.employments || resumeData.workExperience || resumeData.workExperiences || []).map(e => ({
            title: e.jobTitle || e.title,
            employer: e.employer || e.company,
            description: e.description,
        }));

        setIsAiGenerating(true);
        try {
            const existingTitles = new Set(projects.map(p => String(p.title || '').trim().toLowerCase()).filter(Boolean));
            // Only AI results for this request are offered; no role-template ideas.
            let curatedList = [];
            let aiUnavailable = false;

            // Attempt AI enhancement using the registered 'generate-projects' operation
            try {
                const aiResult = await generateUserAiContent('generate-projects', {
                    targetRole: effectiveRole || 'Professional',
                    occupation: effectiveRole || 'Professional',
                    candidateFacts: {
                        roles: candidateEmployments,
                        skills: candidateSkills,
                        education: resumeData.educations || resumeData.education || [],
                        summary: resumeData.summary || '',
                    },
                    context: candidateContext,
                    existingTitles: Array.from(existingTitles),
                    language: resumeData.language || 'en',
                    targetJobDescription: resumeData.targetJobDescription || '',
                });

                if (aiResult?.aiUnavailable) aiUnavailable = true;
                const candidateProjects = Array.isArray(aiResult?.projects)
                    ? aiResult.projects
                    : (Array.isArray(aiResult?.items) ? aiResult.items : (Array.isArray(aiResult) ? aiResult : null));

                if (candidateProjects && candidateProjects.length > 0) {
                    curatedList = candidateProjects.map(cp => ({
                        name: cp.name || cp.title,
                        role: cp.role || '',
                        issuer: cp.technologies ? (cp.technologies.startsWith('Stack: ') || cp.technologies.startsWith('Tools: ') ? cp.technologies : `Tools: ${cp.technologies}`) : (cp.issuer || ''),
                        category: cp.category === 'mandatory' ? 'mandatory' : 'recommended',
                        projectType: cp.projectType || 'enterprise',
                    })).filter(p => Boolean(p.name));
                }
            } catch {
                aiUnavailable = true;
            }

            if (!curatedList.length) {
                triggerToast(aiUnavailable
                    ? 'AI project recommendations are unavailable right now. Please try again in a moment.'
                    : 'AI could not suggest projects from your current details. Add more about your work or skills, then try again.', 'info');
                return;
            }

            // Exclude already added projects
            const unadded = curatedList.filter(item => !existingTitles.has(String(item.name || item.title || '').trim().toLowerCase()));

            if (!unadded.length) {
                triggerToast('All recommended project ideas for this role are already in your resume!', 'info');
                return;
            }

            setAiModalState({
                isOpen: true,
                title: `Review AI Recommended Projects for ${effectiveRole || 'Your Target Role'}`,
                items: unadded,
                onApply: (approvedItems) => {
                    const toAdd = approvedItems.map(item => {
                        const rawIssuer = String(item.issuer || item.technologies || '');
                        const stack = rawIssuer.startsWith('Stack: ') || rawIssuer.startsWith('Tools: ')
                            ? rawIssuer.replace(/^(?:Stack|Tools):\s*/, '')
                            : rawIssuer;

                        return createNewProject(
                            item.name || item.title,
                            item.role || '',
                            stack,
                            item.projectType || 'enterprise'
                        );
                    });

                    setProjects(prev => [...prev, ...toAdd]);
                    triggerToast(`Added ${toAdd.length} project(s) to your resume! Check them out below.`);
                }
            });
        } catch (err) {
            triggerToast('Unable to fetch project ideas. Please try again.', 'error');
        } finally {
            setIsAiGenerating(false);
        }
    };

    const hasProjects = projects.some(p => String(p?.title || p?.name || '').trim() !== '');

    const renderEntryBody = (project) => {
        return (
            <div className="space-y-4 pt-1">
                {/* Row 1: Title & Role */}
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3.5">
                    <Field
                        label={t('ProjectsStep.fields.title.label', 'Project Name')}
                        name={`project-title-${project.id}`}
                        placeholder={getDynamicPlaceholder('projects', 'title', candidateContext) || 'e.g. Distributed E-Commerce Backend, Real-Time Chat App'}
                        value={project.title}
                        onChange={(e) => updateProject(project.id, 'title', e.target.value)}
                        required
                    />
                    <Field
                        label="Your Role in Project"
                        name={`project-role-${project.id}`}
                        placeholder="e.g. Lead Architect, Full Stack Developer, Creator"
                        value={project.role || ''}
                        onChange={(e) => updateProject(project.id, 'role', e.target.value)}
                        optional
                    />
                </div>

                {/* Row 2: Technologies & URL */}
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3.5">
                    <Field
                        label="Technologies / Tools Used"
                        name={`project-technologies-${project.id}`}
                        placeholder="e.g. React, Node.js, PostgreSQL, Docker, AWS, TailwindCSS"
                        value={project.technologies || ''}
                        onChange={(e) => updateProject(project.id, 'technologies', e.target.value)}
                        optional
                    />
                    <div>
                        <Field
                            label={t('ProjectsStep.fields.url.label', 'Project / Portfolio URL')}
                            name={`project-url-${project.id}`}
                            type="url"
                            placeholder="https://github.com/... or https://..."
                            value={project.url || ''}
                            onChange={(e) => updateProject(project.id, 'url', e.target.value)}
                            optional
                        />
                        {project.url && /^https?:\/\//i.test(String(project.url)) && (
                            <div className="mt-1.5 flex items-center justify-end">
                                <a
                                    href={project.url}
                                    target="_blank"
                                    rel="noreferrer"
                                    className="inline-flex items-center gap-1.5 text-xs font-semibold text-indigo-600 hover:text-indigo-800 transition-colors"
                                >
                                    <span>Test live URL</span>
                                    <MdLaunch className="w-3.5 h-3.5" />
                                </a>
                            </div>
                        )}
                    </div>
                </div>

                {/* Row 3: Project Type Selector */}
                <div className="space-y-1.5">
                    <label className="block text-xs font-bold uppercase tracking-wider text-slate-600">
                        Project Type / Category
                    </label>
                    <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
                        {PROJECT_TYPES.map(type => {
                            const Icon = type.icon;
                            const isSelected = (project.projectType || 'personal') === type.id;
                            return (
                                <button
                                    key={type.id}
                                    type="button"
                                    onClick={() => updateProject(project.id, 'projectType', type.id)}
                                    className={`px-3 py-2 rounded-xl text-xs font-bold border transition-all flex items-center justify-center gap-2 ${
                                        isSelected
                                            ? `${type.badgeClass} ring-2 ring-indigo-500/20 shadow-xs`
                                            : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'
                                    }`}
                                >
                                    <Icon className="w-3.5 h-3.5" />
                                    <span>{type.label}</span>
                                </button>
                            );
                        })}
                    </div>
                </div>
            </div>
        );
    };

    const renderGuideContent = () => {
        return (
            <div className="space-y-4">
                <div className="bg-indigo-50/70 border border-indigo-100 rounded-xl p-3.5 space-y-2.5">
                    <h3 className="text-xs font-bold text-indigo-950 flex items-center gap-1.5">
                        <MdAutoAwesome className="w-4 h-4 text-indigo-600" />
                        <span>Project Tips & Best Practices</span>
                    </h3>
                    <ul className="space-y-2 text-[11px] text-slate-600">
                        <li className="flex items-start gap-1.5">
                            <span className="text-indigo-600 font-bold">•</span>
                            <span><strong>Select 2–4 Top Projects:</strong> Focus on projects that showcase your core capabilities and directly align with your target role.</span>
                        </li>
                        <li className="flex items-start gap-1.5">
                            <span className="text-indigo-600 font-bold">•</span>
                            <span><strong>Specify Tools & Technologies:</strong> List concrete tools, frameworks, and methodologies so recruiters immediately spot your proficiencies.</span>
                        </li>
                        <li className="flex items-start gap-1.5">
                            <span className="text-indigo-600 font-bold">•</span>
                            <span><strong>Include Live URLs:</strong> Provide a direct link to a live site, GitHub repo, publication, or case study.</span>
                        </li>
                        <li className="flex items-start gap-1.5">
                            <span className="text-indigo-600 font-bold">•</span>
                            <span><strong>Categorize Accurately:</strong> Tag each entry as Personal Build, Work / Enterprise, Open Source, or Academic research.</span>
                        </li>
                    </ul>
                </div>
            </div>
        );
    };

    return (
        <StepShell
            stepNumber={5}
            stepPath="projects"
            title={t('ProjectsStep.title', 'Projects & Key Initiatives')}
            subtitle={t('ProjectsStep.subtitle', 'Work that showcases your skills — personal builds, enterprise deployments, open-source work, and academic research.')}
            isComplete={hasProjects}
            statusBadge={projects.length > 0 ? `${projects.length} ${projects.length === 1 ? 'Project' : 'Projects'}` : ''}
            resumeData={resumeData}
            targetJd={resumeData.targetJobDescription || ''}
            guideContent={renderGuideContent()}
        >
            {/* Lightweight Toast Feedback */}
            {toastState && (
                <div className={`fixed bottom-5 right-5 z-50 px-4 py-2.5 rounded-xl shadow-lg border text-xs font-bold animate-slideUp flex items-center gap-2 ${
                    toastState.type === 'error'
                        ? 'bg-rose-900 text-white border-rose-700'
                        : toastState.type === 'info'
                            ? 'bg-slate-900 text-white border-slate-700'
                            : 'bg-emerald-900 text-white border-emerald-700'
                }`}>
                    <MdCheckCircle className="w-4 h-4 text-emerald-400" />
                    <span>{toastState.msg}</span>
                </div>
            )}

            {/* AI Recommendations Review Modal */}
            <AiRecommendationModal
                isOpen={aiModalState.isOpen}
                onClose={() => setAiModalState(prev => ({ ...prev, isOpen: false }))}
                title={aiModalState.title}
                items={aiModalState.items}
                onApply={aiModalState.onApply}
            />

            {projects.length === 0 ? (
                <EmptyState
                    title="Showcase your strongest projects"
                    description="Projects are concrete proof of what you can build. Add personal creations, enterprise milestones, open-source contributions, or university research."
                    primaryAction={{
                        label: 'Add First Project',
                        icon: <MdAdd className="w-4 h-4" />,
                        onClick: addProject,
                    }}
                    secondaryAction={{
                        label: isAiGenerating ? 'Generating Ideas...' : '🪄 Auto-Recommend Project Ideas (AI)',
                        icon: <MdAutoAwesome className="w-4 h-4 text-indigo-500" />,
                        onClick: handleRecommendAiProjects,
