                            </h1>
                            <span className={`px-2.5 py-0.5 rounded-full text-[11px] font-bold ${overallTheme.badge}`}>
                                {atsResult.qualityScore}/100 ATS Score
                            </span>
                        </div>
                        <p className="text-slate-500 text-xs leading-relaxed">
