                            </p>
                        </div>

                        <div className="divide-y divide-slate-100">
                            {atsResult.sections.map((sec) => {
                                const secPct = sec.maxScore > 0 ? Math.round((sec.score / sec.maxScore) * 100) : 0;
                                const secTheme = getScoreTheme(secPct);

                                return (
                                    <div
                                        key={sec.id}
                                        className="py-3.5 first:pt-0 last:pb-0 flex flex-col sm:flex-row sm:items-center justify-between gap-3 group"
                                    >
                                        <div className="flex items-start gap-3 min-w-0 flex-1">
                                            <div className={`w-8 h-8 rounded-lg flex items-center justify-center text-xs font-bold shrink-0 ${secTheme.bg} ${secTheme.text} border ${secTheme.border}`}>
                                                {sec.score}
                                            </div>
                                            <div className="min-w-0 flex-1">
                                                <div className="flex items-center gap-2">
                                                    <h3 className="text-xs font-bold text-slate-900">
                                                        {sec.name}
                                                    </h3>
                                                    <span className={`text-[10px] font-bold px-1.5 py-0.2 rounded-md ${secTheme.badge}`}>
                                                        {secPct}%
                                                    </span>
                                                </div>
                                                <p className="text-xs text-slate-600 mt-0.5 leading-relaxed">
                                                    {sec.action || sec.reason || 'Section content reviewed.'}
                                                </p>
                                            </div>
                                        </div>

                                        <div className="flex items-center gap-2 shrink-0 self-end sm:self-center">
                                            <button
                                                type="button"
                                                onClick={() => onNavigate(sec.navigateTo || 'heading')}
                                                className="inline-flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-semibold text-indigo-700 bg-indigo-50 hover:bg-indigo-100 hover:text-indigo-900 border border-indigo-200/70 transition-colors"
                                            >
                                                <span>Edit</span>
                                                <MdArrowForward className="w-3.5 h-3.5" />
                                            </button>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>

                    {/* Strengths & Improvements — engine findings only */}
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        <div className="bg-emerald-50/60 border border-emerald-200/80 rounded-2xl p-4 shadow-2xs space-y-2">
                            <h3 className="text-xs font-bold uppercase tracking-wider text-emerald-900 flex items-center gap-1.5">
                                <MdCheckCircle className="w-4 h-4 text-emerald-600" />
                                What is working
                            </h3>
                            <ul className="space-y-1.5">
                                {atsResult.strengths?.length > 0 ? (
                                    atsResult.strengths.map((str, idx) => (
                                        <li key={idx} className="text-xs text-emerald-950 flex items-start gap-1.5 leading-relaxed">
                                            <span className="text-emerald-600 font-bold shrink-0">✓</span>
                                            <span>{str}</span>
                                        </li>
                                    ))
                                ) : (
                                    <li className="text-xs text-slate-500">
                                        Add detailed roles and skills to see what is working.
                                    </li>
                                )}
                            </ul>
                        </div>

                        <div className="bg-amber-50/60 border border-amber-200/80 rounded-2xl p-4 shadow-2xs space-y-2">
                            <h3 className="text-xs font-bold uppercase tracking-wider text-amber-900 flex items-center gap-1.5">
                                <MdWarning className="w-4 h-4 text-amber-600" />
                                What to fix first
                            </h3>
                            <ul className="space-y-1.5">
                                {atsResult.improvements?.length > 0 ? (
                                    atsResult.improvements.slice(0, 4).map((imp, idx) => (
                                        <li key={idx} className="text-xs text-amber-950 flex items-start justify-between gap-2 leading-relaxed">
                                            <span className="flex items-start gap-1.5">
                                                <span className="text-amber-600 font-bold shrink-0">•</span>
                                                <span>{typeof imp === 'string' ? imp : imp.text}</span>
                                            </span>
                                            {typeof imp === 'object' && imp.navigateTo && (
                                                <button
                                                    type="button"
                                                    onClick={() => onNavigate(imp.navigateTo)}
                                                    className="text-[10px] font-bold text-amber-800 underline hover:text-amber-950 shrink-0"
                                                >
                                                    Fix
                                                </button>
                                            )}
                                        </li>
                                    ))
                                ) : (
                                    <li className="text-xs text-emerald-800 font-semibold">
                                        No critical gaps found.
                                    </li>
                                )}
                            </ul>
                        </div>
                    </div>
                </main>

                {/* Right: Template, Preview & Export */}
                <aside className="lg:col-span-4 sticky top-[125px] self-start space-y-4" aria-label="Template and export actions">
                    <div className="bg-white rounded-2xl border border-slate-200/90 p-5 shadow-2xs space-y-4">
                        <div>
                            <span className="text-[10px] font-bold uppercase tracking-wider text-slate-400">
                                Active presentation
                            </span>
                            <h2 className="text-base font-bold text-slate-900 mt-0.5">
                                {templateName || 'Modern Template'}
                            </h2>
                            <p className="text-xs text-slate-500 mt-0.5">
                                Text-first layout, readable by ATS parsers.
                            </p>
                        </div>

                        <div className="space-y-2 pt-2 border-t border-slate-100">
                            <button
                                type="button"
                                onClick={onChooseTemplate}
                                className="w-full flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg border border-slate-200 hover:border-indigo-300 hover:bg-indigo-50 text-slate-800 text-xs font-semibold transition-all"
                            >
                                <span>Change template</span>
                            </button>
                            <button
                                type="button"
                                onClick={onPreview}
                                className="w-full flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg border border-indigo-200 bg-indigo-50 hover:bg-indigo-100 text-indigo-800 text-xs font-semibold transition-all"
                            >
                                <MdVisibility className="w-4 h-4 text-indigo-600" />
                                <span>Open preview</span>
                            </button>
                        </div>
                    </div>

                    <div className="bg-slate-900 rounded-2xl p-5 text-white shadow-md space-y-3">
                        <div className="flex items-center gap-2">
                            <MdFileDownload className="w-5 h-5 text-indigo-300" />
                            <h3 className="text-sm font-bold text-white">
                                Download
                            </h3>
                        </div>
                        <p className="text-xs text-slate-300 leading-relaxed">
                            Export a PDF with the selected template.
                        </p>

                        <button
                            type="button"
                            onClick={requiredReady ? onDownload : () => onNavigate?.('heading')}
                            disabled={isDownloading}
                            aria-describedby={!requiredReady ? 'export-requirement' : undefined}
                            className="w-full flex items-center justify-center gap-2 px-4 py-3 rounded-xl bg-emerald-500 hover:bg-emerald-600 text-white text-xs font-bold shadow-md disabled:opacity-50 disabled:cursor-not-allowed transition-all cursor-pointer"
                        >
                            <MdFileDownload className="w-4 h-4" />
                            <span>{isDownloading ? 'Preparing export…' : requiredReady ? 'Download Resume (PDF)' : 'Complete Name to Download (Step 1)'}</span>
                        </button>

                        {!requiredReady && (
                            <p id="export-requirement" className="text-[11px] text-amber-300 bg-amber-950/40 p-2.5 rounded-lg border border-amber-800/60 leading-snug">
                                Add your name in Step 1 before downloading.
                            </p>
                        )}
                    </div>
                </aside>
            </div>
            <ConfirmRegenerateModal
                isOpen={showConfirmModal}
                onClose={() => setShowConfirmModal(false)}
                onConfirm={executeAutofillJd}
                targetRole={String(resumeData.targetRole || resumeData.occupation || '').trim()}
                existingTextSnippet={targetJd}
                isGenerating={isGeneratingJd}
            />
        </div>
    );
}

import React, { useState, useEffect, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import {
    FaMagic,
    FaPlus,
    FaThLarge,
    FaTags,
    FaTimes,
    FaSearch,
    FaBolt,
    FaChevronDown,
    FaChevronUp,
    FaTrash,
} from 'react-icons/fa';
import { MdCheckCircle } from 'react-icons/md';
import StepShell from '../components/StepShell.jsx';
import AutocompleteInputField from './components/AutocompleteInputField';
import AiRecommendationModal from '../../Form/AiRecommendationModal.jsx';
import { generateUserAiContent, cleanSkillName } from '../../../services/aiService.js';
import { buildAssistPayload } from '../ai/aiContract.js';
import { calculateAtsScore } from '../../../utils/atsScore.js';
import { getCandidateContext } from '../../../utils/candidateContext.js';

const PROFICIENCY_LEVELS = [
    { label: 'Beginner', value: 25 },
    { label: 'Intermediate', value: 50 },
    { label: 'Advanced', value: 75 },
    { label: 'Expert', value: 100 },
];

const ratingToLevel = (rating) => {
    const num = Number(rating) || 75;
    if (num >= 100) return 'Expert';
    if (num >= 75) return 'Advanced';
    if (num >= 50) return 'Intermediate';
    return 'Beginner';
};

const levelToRating = (level) => {
    switch (String(level || '').toLowerCase()) {
        case 'expert': return 100;
        case 'advanced': return 75;
        case 'intermediate': return 50;
        case 'beginner': return 25;
        default: return 75;
    }
};

const LEVEL_COLOR_CLASSES = {
    expert: 'bg-indigo-100 text-indigo-800 border-indigo-200',
    advanced: 'bg-emerald-100 text-emerald-800 border-emerald-200',
    intermediate: 'bg-sky-100 text-sky-800 border-sky-200',
    beginner: 'bg-slate-200 text-slate-700 border-slate-300',
};

/**
 * 10/10 Skills Step — World-Class Resume Builder Experience:
 * - 2-Tier Header Toolbar: Title, Count Badge, AI Auto-Recommend Modal & Add Skill actions.
 * - Live Search Filter across all skills and proficiency levels.
 * - Collapsible Bulk Ingestion Drawer with multi-delimiter support (comma, semicolon, newline).
 * - Dual View Modes: Spacious 2-Column Responsive Cards Grid vs High-Density Compact Tags Matrix.
 * - 4-Tier Segmented Proficiency Controls (Beginner, Intermediate, Advanced, Expert) with colored indicator.
 * - Micro-Action Pods (▲ Move Up, ▼ Move Down, 🗑 Delete).
 * - Interactive AI Recommendation Review Modal with Core vs Recommended separation & multi-select.
 * - ATS JD Alignment Engine (Matched / Partial / Missing) & Real-time Duplicate Detection.
 * - Zero-Data Loss Autosaving & Synchronous Step Flush on Unmount.
 */
const SkillsStep = ({ resumeData, updateResumeData, onNavigate }) => {
    const { t } = useTranslation('common');
    const [skills, setSkills] = useState(resumeData.skills || []);
    const candidateContext = getCandidateContext(resumeData, resumeData.targetJobDescription || '');
    const targetJd = resumeData.targetJobDescription || '';

    // View & Search States
    const [skillsViewMode, setSkillsViewMode] = useState('grid'); // 'grid' | 'compact'
    const [skillsSearchQuery, setSkillsSearchQuery] = useState('');
    const [showBulkSkills, setShowBulkSkills] = useState(false);
    const [bulkSkillsInput, setBulkSkillsInput] = useState('');

    // AI & Notification States
    const [isAiGenerating, setIsAiGenerating] = useState(false);
    const [toastState, setToastState] = useState(null);
    const [aiModalState, setAiModalState] = useState({
        isOpen: false,
        title: '',
        type: 'skills',
        items: [],
        onApply: null,
    });

    const idCounter = useRef(0);

    useEffect(() => {
        if (resumeData.skills && Array.isArray(resumeData.skills)) {
            setSkills(resumeData.skills);
        }
    }, [resumeData.skills]);

    const triggerNotification = (msg, type = 'success') => {
        setToastState({ msg, type });
        setTimeout(() => setToastState(null), 4500);
    };

    const createNewSkill = (name = '', rating = 75) => {
        idCounter.current += 1;
        const cleaned = cleanSkillName(name) || name;
        return {
            id: `skill_${Date.now()}_${idCounter.current}_${Math.random().toString(36).substr(2, 4)}`,
            skillName: cleaned,
            name: cleaned,
            rating: Number.isFinite(rating) ? rating : 75,
        };
    };

    const normalizeSkillName = value => String(value || '').trim().toLowerCase();

    const addSkill = (name = '', rating = 75) => {
        const newSkill = createNewSkill(name, rating);
        setSkills(prev => [...prev, newSkill]);
    };

    const updateSkill = (id, field, value) => {
        setSkills(prev => prev.map(s => {
            if (s.id !== id) return s;
            if (field === 'rating') {
                return { ...s, rating: Number(value) };
            }
            if (field === 'level') {
                return { ...s, rating: levelToRating(value) };
            }
            if (field === 'name' || field === 'skillName') {
                return { ...s, skillName: value, name: value };
            }
            return { ...s, [field]: value };
        }));
    };

    const removeSkill = (id) => setSkills(prev => prev.filter(skill => skill.id !== id));

    const moveSkill = (index, direction) => {
        setSkills(prev => {
            const nextIndex = index + direction;
            if (nextIndex < 0 || nextIndex >= prev.length) return prev;
            const updated = [...prev];
            const temp = updated[index];
            updated[index] = updated[nextIndex];
            updated[nextIndex] = temp;
            return updated;
        });
    };

    const cycleSkillRating = (id) => {
        setSkills(prev => prev.map(s => {
            if (s.id !== id) return s;
            const r = Number(s.rating) || 75;
            let nextR = 75;
            if (r <= 25) nextR = 50;
            else if (r <= 50) nextR = 75;
            else if (r <= 75) nextR = 100;
            else nextR = 25;
            return { ...s, rating: nextR };
        }));
    };

    // Bulk ingestion parser supporting commas, semicolons, and newlines
    const handleBulkSkillAdd = () => {
        if (!bulkSkillsInput.trim()) return;
        const tokens = bulkSkillsInput.split(/[,;\n]+/).map(t => cleanSkillName(t)).filter(Boolean);
        if (!tokens.length) return;

        setSkills(prev => {
            const existingNames = new Set(prev.map(s => normalizeSkillName(s?.skillName || s?.name)));
            const toAdd = [];
            for (const token of tokens) {
                const norm = normalizeSkillName(token);
                if (norm && !existingNames.has(norm)) {
                    existingNames.add(norm);
                    toAdd.push(createNewSkill(token, 75));
                }
            }
            if (toAdd.length > 0) {
                triggerNotification(`Added ${toAdd.length} skill(s) to your resume!`);
                return [...prev, ...toAdd];
            } else {
                triggerNotification('All entered skills already exist in your resume.', 'info');
                return prev;
            }
        });
        setBulkSkillsInput('');
        setShowBulkSkills(false);
    };

    // AI Contextual Recommendation Modal Trigger
    const handleRecommendAiSkills = async () => {
        const effectiveRole = String(
            candidateContext?.target?.role ||
            resumeData.targetRole ||
            resumeData.occupation ||
            (resumeData.workExperience?.[0]?.jobTitle || resumeData.workExperiences?.[0]?.jobTitle) ||
            ''
        ).trim();

        setIsAiGenerating(true);
        try {
            const existing = skills.map(s => String(s?.skillName || s?.name || '').trim().toLowerCase()).filter(Boolean);
            let prepared;
            try {
                prepared = buildAssistPayload('generate-skills', {
                    resumeData,
                    targetJd,
                });
            } catch {
                prepared = { payload: { targetRole: effectiveRole, occupation: effectiveRole, existingSkills: existing } };
            }

            const data = await generateUserAiContent('generate-skills', {
                ...prepared.payload,
                targetRole: effectiveRole || prepared.payload?.targetRole || 'Professional',
                existingSkills: existing,
            });

            const rawSkills = Array.isArray(data?.skills)
                ? data.skills
                : (Array.isArray(data?.data?.skills)
                    ? data.data.skills
                    : (Array.isArray(data?.suggestions)
                        ? data.suggestions
                        : (Array.isArray(data) ? data : [])));

            if (!rawSkills.length) {
                const note = data?.note || 'AI skill suggestions are currently unavailable. Please verify your target role and try again.';
                triggerNotification(note, 'info');
                return;
            }

            const unadded = rawSkills.filter(s => {
                const name = typeof s === 'string' ? s : s?.name || s?.skill || s?.title;
                return name && !existing.some(e => e.toLowerCase() === name.trim().toLowerCase());
            });

            const itemsToReview = unadded.map((s, idx) => {
                const raw = typeof s === 'string' ? s : s?.name || s?.skill || s?.title;
                const cleaned = cleanSkillName(raw);
                const category = (typeof s === 'object' && s?.category && ['mandatory', 'recommended'].includes(s.category))
                    ? s.category
                    : (idx < 5 ? 'mandatory' : 'recommended');
                return { name: cleaned, category };
            }).filter(s => s.name);

            if (!itemsToReview.length) {
                triggerNotification('All recommended skills for this role are already in your resume!', 'info');
                return;
            }

            setAiModalState({
                isOpen: true,
                title: `Review AI Recommended Skills for ${effectiveRole || 'Your Target Role'}`,
                type: 'skills',
                items: itemsToReview,
                onApply: (approvedItems) => {
                    const toAdd = approvedItems.map(item => createNewSkill(item.name, 100));
                    setSkills(prev => {
                        const existingNames = new Set(prev.map(s => normalizeSkillName(s?.skillName || s?.name)));
                        const fresh = toAdd.filter(s => !existingNames.has(normalizeSkillName(s.skillName)));
                        return [...prev, ...fresh];
                    });
                    triggerNotification(`Added ${approvedItems.length} approved ATS skills to your resume!`);
                },
            });
        } catch (err) {
            if (err?.name === 'AbortError') return;
            console.error('AI skill recommendation error:', err);
            const msg = (err?.code === 'AI_DAILY_QUOTA_EXCEEDED' || err?.status === 429)
                ? 'Daily AI limit reached. Please upgrade your plan or try again later.'
                : (err?.message || 'Unable to generate skills recommendations.');
            triggerNotification(msg, 'error');
        } finally {
            setIsAiGenerating(false);
        }
    };

    // Autosave synchronization
    const handleSave = () => {
        const hasValidSkill = skills.some(s => String(s?.skillName || s?.name || '').trim() !== '');
        const completedSteps = [...(resumeData.completedSteps || [])];
        let updatedCompletedSteps = null;

        if (hasValidSkill && !completedSteps.includes(4)) {
            updatedCompletedSteps = [...completedSteps, 4];
        } else if (!hasValidSkill && completedSteps.includes(4)) {
            updatedCompletedSteps = completedSteps.filter(step => step !== 4);
        }

        updateResumeData({
            skills,
            ...(updatedCompletedSteps ? { completedSteps: updatedCompletedSteps } : {}),
        });
    };

    useEffect(() => {
        const timeoutId = setTimeout(() => {
            handleSave();
        }, 500);
        return () => clearTimeout(timeoutId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [skills]);

    // Unmount flush: synchronously commit state on step exit
    const skillsRef = useRef(skills);
    const updateResumeDataRef = useRef(updateResumeData);
    const completedStepsRef = useRef(resumeData?.completedSteps || []);
    useEffect(() => { skillsRef.current = skills; }, [skills]);
    useEffect(() => { updateResumeDataRef.current = updateResumeData; }, [updateResumeData]);
    useEffect(() => { completedStepsRef.current = resumeData?.completedSteps || []; }, [resumeData?.completedSteps]);
    useEffect(() => () => {
        const sks = skillsRef.current;
        const hasValidSkill = sks.some(s => String(s?.skillName || s?.name || '').trim() !== '');
        const completedSteps = [...(completedStepsRef.current || [])];
        let updatedCompletedSteps = null;
        if (hasValidSkill && !completedSteps.includes(4)) {
            updatedCompletedSteps = [...completedSteps, 4];
        } else if (!hasValidSkill && completedSteps.includes(4)) {
            updatedCompletedSteps = completedSteps.filter(step => step !== 4);
        }
        updateResumeDataRef.current({
            skills: sks,
            ...(updatedCompletedSteps ? { completedSteps: updatedCompletedSteps } : {}),
        });
    }, []);

    // Deterministic duplicate detection
    const nameCounts = new Map();
    skills.forEach(s => {
        const key = normalizeSkillName(s?.skillName || s?.name);
        if (key) nameCounts.set(key, (nameCounts.get(key) || 0) + 1);
    });
    const duplicates = skills
        .map((s, index) => ({ skill: s, index, key: normalizeSkillName(s?.skillName || s?.name) }))
        .filter(item => item.key && (nameCounts.get(item.key) || 0) > 1);

    const hasSkills = skills.some(s => String(s?.skillName || s?.name || '').trim() !== '');

    // JD alignment — real engine output (MATCHED / PARTIAL / MISSING)
    const atsResult = calculateAtsScore(resumeData, { jobDescription: targetJd });
    const jdMatch = atsResult?.jdMatch;

    // Filtered skills based on live search
    const filteredSkills = skills
        .map((skill, originalIndex) => ({ ...skill, originalIndex }))
        .filter(skill => {
            if (!skillsSearchQuery.trim()) return true;
            const q = skillsSearchQuery.toLowerCase().trim();
            const name = (skill.skillName || skill.name || '').toLowerCase();
            const level = ratingToLevel(skill.rating).toLowerCase();
            return name.includes(q) || level.includes(q);
        });

    return (
        <StepShell
            stepNumber={4}
            stepPath="skills"
            title={t('SkillsStep.title', 'Skills')}
            subtitle={t('SkillsStep.subtitle', 'The skills you actually used in your work — list them as they appear on your CVs, certificates, or project documentation.')}
            isComplete={hasSkills}
            statusBadge={skills.length > 0 ? `${skills.length} ${skills.length === 1 ? 'skill' : 'skills'}` : ''}
            resumeData={resumeData}
            targetJd={targetJd}
        >
            <div className="space-y-4">
                {/* 10/10 Header & Actions Toolbar */}
                <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/90 shadow-2xs space-y-3.5">
                    {/* Row 1: Title, Counter Badge & Primary Creation Actions */}
                    <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 pb-3 border-b border-slate-100">
                        <div className="min-w-0">
                            <div className="flex items-center gap-2.5 flex-wrap">
                                <h3 className="text-sm font-bold text-slate-900 tracking-tight whitespace-nowrap">
                                    Skills & Technical Competencies
                                </h3>
                                <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-[11px] font-bold bg-indigo-50 text-indigo-700 border border-indigo-100/80 whitespace-nowrap shrink-0">
                                    {skills.length} {skills.length === 1 ? 'Skill' : 'Skills'}
                                </span>
                            </div>
                            <p className="text-xs text-slate-500 mt-1">
                                Save core technical competencies and soft skills parsed by ATS screening engines.
                            </p>
                        </div>
                        <div className="flex items-center gap-2 shrink-0 self-start sm:self-center">
                            {/* Auto-Recommend Skills (AI) */}
                            <button
                                type="button"
                                onClick={handleRecommendAiSkills}
                                disabled={isAiGenerating}
                                className="whitespace-nowrap px-3.5 py-2 bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-700 hover:to-indigo-700 text-white rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-1.5 shadow-sm cursor-pointer shrink-0 disabled:opacity-50">
                                <FaMagic className={`w-3.5 h-3.5 ${isAiGenerating ? 'animate-spin' : ''}`} />
                                <span>Auto-Recommend (AI)</span>
                            </button>

                            {/* Add Single Skill */}
                            <button
                                type="button"
                                onClick={() => addSkill()}
                                className="whitespace-nowrap px-3.5 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-1.5 shadow-xs cursor-pointer shrink-0">
                                <FaPlus className="w-3 h-3" /> Add Skill
                            </button>
                        </div>
                    </div>

                    {/* Row 2: Search Filter + View & Utility Controls */}
                    <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2.5">
                        {/* Search / Filter Input */}
                        <div className="relative flex-1 max-w-md">
                            <FaSearch className="w-3.5 h-3.5 text-slate-400 absolute left-3.5 top-1/2 -translate-y-1/2 pointer-events-none" />
                            <input
                                type="text"
                                value={skillsSearchQuery}
                                onChange={(e) => setSkillsSearchQuery(e.target.value)}
                                placeholder={skills.length > 0 ? `Search across ${skills.length} skills...` : "Filter skills..."}
                                className="w-full text-xs pl-9 pr-8 py-2 bg-slate-50/80 hover:bg-white focus:bg-white border border-slate-200/90 rounded-xl text-slate-900 placeholder:text-slate-400 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100 outline-none transition-all"
                            />
                            {skillsSearchQuery && (
                                <button
                                    type="button"
                                    onClick={() => setSkillsSearchQuery('')}
                                    className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 p-0.5 cursor-pointer"
                                    title="Clear search">
                                    <FaTimes className="w-3 h-3" />
                                </button>
                            )}
                        </div>

                        {/* View & Utility Controls */}
                        <div className="flex items-center gap-2 shrink-0 self-end sm:self-auto">
                            {/* Quick Bulk Paste Toggle */}
                            <button
                                type="button"
                                onClick={() => setShowBulkSkills(prev => !prev)}
                                className={`px-3 py-1.5 rounded-xl text-xs font-semibold transition-all flex items-center gap-1.5 border cursor-pointer ${
                                    showBulkSkills || bulkSkillsInput.trim()
                                        ? 'bg-indigo-50 border-indigo-200 text-indigo-700 shadow-2xs font-bold'
                                        : 'bg-white border-slate-200 hover:border-slate-300 text-slate-700 hover:bg-slate-50'
                                }`}
                                title="Toggle quick bulk paste ingestion">
                                <FaBolt className={`w-3 h-3 ${showBulkSkills || bulkSkillsInput.trim() ? 'text-indigo-600' : 'text-amber-500'}`} />
                                <span>Bulk Paste</span>
                                {showBulkSkills ? <FaChevronUp className="w-2.5 h-2.5 opacity-60" /> : <FaChevronDown className="w-2.5 h-2.5 opacity-60" />}
                            </button>

                            {/* View Mode Switcher */}
                            <div className="flex items-center bg-slate-100 p-0.5 rounded-xl border border-slate-200/80">
                                <button
                                    type="button"
                                    onClick={() => setSkillsViewMode('grid')}
                                    className={`px-2.5 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1.5 transition-all cursor-pointer ${
                                        skillsViewMode === 'grid'
                                            ? 'bg-white text-indigo-700 shadow-2xs'
                                            : 'text-slate-600 hover:text-slate-900'
                                    }`}
                                    title="Cards View (Detailed view with proficiency controls)">
                                    <FaThLarge className="w-3 h-3" />
                                    <span>Cards</span>
                                </button>
                                <button
                                    type="button"
                                    onClick={() => setSkillsViewMode('compact')}
                                    className={`px-2.5 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1.5 transition-all cursor-pointer ${
                                        skillsViewMode === 'compact'
                                            ? 'bg-white text-indigo-700 shadow-2xs'
                                            : 'text-slate-600 hover:text-slate-900'
                                    }`}
                                    title="Compact Tags View (High-density overview of all skills)">
                                    <FaTags className="w-3 h-3" />
                                    <span>Tags</span>
                                </button>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Collapsible Bulk Skills Ingestion Drawer */}
                {(showBulkSkills || bulkSkillsInput.trim()) && (
                    <div className="p-4 bg-slate-50 border border-slate-200 rounded-2xl space-y-2.5 transition-all animate-fadeIn">
                        <div className="flex items-center justify-between">
                            <label className="block text-[11px] font-bold text-slate-700 uppercase tracking-wider flex items-center gap-1.5">
                                <span>⚡ Quick Bulk Paste Ingestion</span>
                                <span className="text-[10px] text-slate-500 font-normal lowercase">(comma, semicolon, or newline separated)</span>
                            </label>
                            <button
                                type="button"
                                onClick={() => setShowBulkSkills(false)}
                                className="text-[11px] font-semibold text-slate-400 hover:text-slate-600 cursor-pointer">
                                Hide
                            </button>
                        </div>
                        <div className="flex gap-2">
                            <textarea
                                value={bulkSkillsInput}
                                onChange={(e) => setBulkSkillsInput(e.target.value)}
                                onKeyDown={(e) => {
                                    if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
                                        e.preventDefault();
                                        handleBulkSkillAdd();
                                    }
                                }}
                                placeholder="Paste multiple skills at once (e.g. React.js, TypeScript, Node.js, Docker, Kubernetes, Clinical Leadership)..."
                                className="flex-1 text-xs p-2.5 bg-white border border-slate-300 rounded-xl text-slate-900 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100 outline-none resize-none h-14"
                            />
                            <button
                                type="button"
                                onClick={handleBulkSkillAdd}
                                disabled={!bulkSkillsInput.trim()}
                                className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 disabled:opacity-40 text-white rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-1.5 shadow-xs shrink-0 cursor-pointer h-14"
                            >
                                <FaPlus className="w-3.5 h-3.5" /> Add All
                            </button>
                        </div>
                    </div>
                )}

                {/* Duplicate warning banner */}
                {duplicates.length > 1 && (
                    <div className="rounded-xl border border-amber-200 bg-amber-50/80 p-3.5 text-xs text-amber-800 space-y-2">
                        <p className="font-semibold">
                            Duplicate skills detected ({[...new Set(duplicates.map(d => d.skill.skillName || d.skill.name))].join(', ')}).
                        </p>
                        <div className="flex flex-wrap gap-1.5">
                            {duplicates.slice(1).map(({ skill }) => (
                                <button
                                    key={`dup-${skill.id}`}
                                    type="button"
                                    onClick={() => removeSkill(skill.id)}
                                    className="rounded-lg border border-amber-300 bg-white px-2.5 py-1 font-semibold hover:bg-amber-100 transition-colors cursor-pointer shadow-2xs"
                                >
                                    Remove “{skill.skillName || skill.name}”
                                </button>
                            ))}
                        </div>
                    </div>
                )}

                {/* JD Alignment Panel — ATS Engine Output */}
                {jdMatch && jdMatch.score !== null && (
                    <div className="rounded-2xl border border-slate-200 bg-white p-4 sm:p-5 shadow-2xs space-y-3">
                        <div className="flex flex-wrap items-center justify-between gap-2">
                            <h2 className="text-sm font-bold text-slate-900">
                                Alignment with your target role
                                {candidateContext.target.role ? ` — ${candidateContext.target.role}` : ''}
                            </h2>
                            <span className="text-xs font-semibold text-slate-500">
                                {jdMatch.matched.length} matched · {jdMatch.partial?.length || 0} partial · {jdMatch.missing.length} missing
                            </span>
                        </div>
                        <p className="text-xs text-slate-500">
                            Matched means the term appears in your resume. Partial means part of a multi-word term appears —
                            consider whether the resume should use the full term, if it is true for you.
                        </p>
                        {jdMatch.matched.length > 0 && (
                            <div>
                                <h3 className="text-[11px] font-bold uppercase tracking-wider text-emerald-700 mb-1.5">Matched</h3>
                                <div className="flex flex-wrap gap-1.5">
                                    {jdMatch.matched.slice(0, 12).map(term => (
                                        <span key={`m-${term}`} className="inline-flex items-center gap-1 rounded-lg border border-emerald-200 bg-emerald-50 px-2.5 py-1 text-xs font-medium text-emerald-800">
                                            <MdCheckCircle className="w-3 h-3" />{term}
                                        </span>
                                    ))}
                                </div>
                            </div>
                        )}
                        {(jdMatch.partial?.length || 0) > 0 && (
                            <div>
                                <h3 className="text-[11px] font-bold uppercase tracking-wider text-amber-700 mb-1.5">Partial match</h3>
                                <div className="flex flex-wrap gap-1.5">
                                    {jdMatch.partial.slice(0, 12).map(term => (
                                        <span key={`p-${term}`} className="rounded-lg border border-amber-200 bg-amber-50 px-2.5 py-1 text-xs font-medium text-amber-800">
                                            {term}
                                        </span>
                                    ))}
                                </div>
                            </div>
                        )}
                        {jdMatch.missing.length > 0 && (
                            <div>
                                <h3 className="text-[11px] font-bold uppercase tracking-wider text-slate-400 mb-1.5">Not found in your resume</h3>
                                <div className="flex flex-wrap gap-1.5">
                                    {jdMatch.missing.slice(0, 12).map(term => (
                                        <span key={`x-${term}`} className="rounded-lg border border-slate-200 bg-slate-50 px-2.5 py-1 text-xs font-medium text-slate-500">
                                            {term}
                                        </span>
                                    ))}
                                </div>
                                <p className="mt-1.5 text-[11px] text-slate-400">
                                    Add terms only if they are true for you — never pad the list.
                                </p>
                            </div>
                        )}
                    </div>
                )}

                {/* Skills Presentation: Empty State vs Cards vs Compact Tags */}
                {skills.length === 0 ? (
                    <div className="p-8 text-center bg-slate-50 border border-dashed border-slate-300 rounded-2xl space-y-3.5">
                        <p className="text-xs font-semibold text-slate-700">No skills added to your resume yet</p>
                        <p className="text-[11px] text-slate-500 max-w-sm mx-auto">
                            Add technical skills, industry tools, and soft competencies that will be evaluated by ATS scanners.
                        </p>
                        <div className="flex items-center justify-center gap-2.5 pt-1">
                            <button
                                type="button"
                                onClick={handleRecommendAiSkills}
                                disabled={isAiGenerating}
                                className="px-4 py-2 bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-700 hover:to-indigo-700 text-white rounded-xl text-xs font-bold transition-all flex items-center gap-1.5 cursor-pointer shadow-sm disabled:opacity-50">
                                <FaMagic className={`w-3.5 h-3.5 ${isAiGenerating ? 'animate-spin' : ''}`} />
                                <span>Auto-Recommend Top Skills (AI)</span>
                            </button>
                            <button
                                type="button"
                                onClick={() => addSkill()}
                                className="px-4 py-2 bg-slate-200 hover:bg-slate-300 text-slate-800 rounded-xl text-xs font-bold cursor-pointer transition-colors">
                                Add Skill
                            </button>
                        </div>
                    </div>
                ) : skillsViewMode === 'compact' ? (
                    /* High-Density Compact Tags / Quick View */
                    <div className="p-4 bg-slate-50 border border-slate-200/90 rounded-2xl space-y-3">
                        <div className="flex items-center justify-between">
                            <span className="text-xs font-bold text-slate-700 uppercase tracking-wider">
                                Quick Skill Matrix ({filteredSkills.length})
                            </span>
                            <span className="text-[11px] text-slate-500">
                                Click badge to cycle level • Reorder with arrows • Click × to delete
                            </span>
                        </div>
                        <div className="flex flex-wrap gap-2 pt-1">
                            {filteredSkills.map((skill) => {
                                const idx = skill.originalIndex;
                                const currentLvl = ratingToLevel(skill.rating);
                                const lvlColors = LEVEL_COLOR_CLASSES[currentLvl.toLowerCase()] || 'bg-indigo-100 text-indigo-800 border-indigo-200';

                                return (
                                    <div
                                        key={skill.id || idx}
                                        className="group inline-flex items-center gap-2 pl-3 pr-2 py-1.5 bg-white border border-slate-200 hover:border-indigo-300 rounded-xl shadow-2xs transition-all"
                                    >
                                        <span className="text-xs font-semibold text-slate-900">
                                            {skill.skillName || skill.name || <span className="text-slate-400 italic">Untitled Skill</span>}
                                        </span>
                                        <button
                                            type="button"
                                            onClick={() => cycleSkillRating(skill.id)}
                                            className={`text-[10px] px-2 py-0.5 rounded-lg font-bold border transition-all cursor-pointer ${lvlColors}`}
                                            title="Click to cycle: Beginner → Intermediate → Advanced → Expert"
                                        >
                                            {currentLvl}
                                        </button>
                                        <div className="flex items-center gap-0.5 opacity-40 group-hover:opacity-100 transition-opacity">
                                            <button
                                                type="button"
                                                disabled={idx === 0}
                                                onClick={() => moveSkill(idx, -1)}
                                                className="w-4 h-4 flex items-center justify-center text-slate-400 hover:text-indigo-600 disabled:opacity-20 text-[9px] cursor-pointer"
                                                title="Move up"
                                            >
                                                ▲
                                            </button>
                                            <button
                                                type="button"
                                                disabled={idx === skills.length - 1}
                                                onClick={() => moveSkill(idx, 1)}
                                                className="w-4 h-4 flex items-center justify-center text-slate-400 hover:text-indigo-600 disabled:opacity-20 text-[9px] cursor-pointer"
                                                title="Move down"
                                            >
                                                ▼
                                            </button>
                                            <button
                                                type="button"
                                                onClick={() => removeSkill(skill.id)}
                                                className="w-4 h-4 flex items-center justify-center text-slate-400 hover:text-red-600 ml-0.5 cursor-pointer"
                                                title="Delete skill"
                                            >
                                                <FaTimes className="w-2.5 h-2.5" />
                                            </button>
                                        </div>
                                    </div>
                                );
                            })}
                            <button
                                type="button"
                                onClick={() => addSkill()}
                                className="inline-flex items-center gap-1 px-3 py-1.5 bg-indigo-50 hover:bg-indigo-100 text-indigo-700 border border-dashed border-indigo-300 rounded-xl text-xs font-bold transition-all cursor-pointer"
                            >
                                <FaPlus className="w-2.5 h-2.5" /> Add Skill
                            </button>
                        </div>
                    </div>
                ) : (
                    /* Spacious 2-Column Responsive Cards Grid with Segmented Controls */
                    <div className="space-y-3.5">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-3.5">
                            {filteredSkills.map((skill) => {
                                const idx = skill.originalIndex;
                                const currentLvl = ratingToLevel(skill.rating);

                                return (
                                    <div
                                        key={skill.id || idx}
                                        className="group relative p-3.5 bg-white hover:bg-slate-50/50 border border-slate-200/90 hover:border-indigo-200 rounded-2xl transition-all shadow-2xs hover:shadow-xs space-y-2.5"
                                    >
                                        {/* Header: Skill Name Input with Autocomplete + Compact Action Pod */}
                                        <div className="flex items-center gap-2">
                                            <div className="flex-1 min-w-0">
                                                <AutocompleteInputField
                                                    hideLabel
                                                    name={`skill_${idx}`}
                                                    value={skill.skillName || skill.name || ''}
                                                    onChange={(e) => updateSkill(skill.id, 'skillName', e.target.value)}
                                                    onSelect={(val) => updateSkill(skill.id, 'skillName', val)}
                                                    placeholder="Skill name (e.g. React.js, Python, Medical Leadership)"
                                                    suggestionType="skill"
                                                    context={candidateContext}
                                                    inputClassName="w-full text-xs p-2.5 pr-8 bg-slate-50/70 hover:bg-white focus:bg-white border border-slate-200 focus:border-indigo-500 rounded-xl font-semibold text-slate-900 focus:ring-2 focus:ring-indigo-100 outline-none transition-all"
                                                />
                                            </div>
                                            <div className="flex items-center gap-0.5 shrink-0 bg-slate-100/90 p-0.5 rounded-xl border border-slate-200/70">
                                                <button
                                                    type="button"
                                                    disabled={idx === 0}
                                                    onClick={(e) => { e.preventDefault(); e.stopPropagation(); moveSkill(idx, -1); }}
                                                    className="w-6 h-6 flex items-center justify-center text-slate-400 hover:text-indigo-600 disabled:opacity-20 rounded-lg hover:bg-white text-[10px] font-bold transition-all cursor-pointer"
                                                    title="Move skill up">
                                                    ▲
                                                </button>
                                                <button
                                                    type="button"
                                                    disabled={idx === skills.length - 1}
                                                    onClick={(e) => { e.preventDefault(); e.stopPropagation(); moveSkill(idx, 1); }}
                                                    className="w-6 h-6 flex items-center justify-center text-slate-400 hover:text-indigo-600 disabled:opacity-20 rounded-lg hover:bg-white text-[10px] font-bold transition-all cursor-pointer"
                                                    title="Move skill down">
                                                    ▼
                                                </button>
                                                <button
                                                    type="button"
                                                    onClick={(e) => { e.preventDefault(); e.stopPropagation(); removeSkill(skill.id); }}
                                                    className="w-6 h-6 flex items-center justify-center text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors cursor-pointer"
                                                    title="Delete skill">
                                                    <FaTrash className="w-2.5 h-2.5" />
                                                </button>
                                            </div>
                                        </div>

                                        {/* Proficiency Level Segmented Control */}
                                        <div className="space-y-1">
                                            <div className="flex items-center justify-between text-[11px] px-1">
                                                <span className="font-semibold text-slate-400 text-[10px] uppercase tracking-wider">Proficiency</span>
                                                <span className="text-[10px] font-bold text-indigo-600 flex items-center gap-1">
                                                    <span className="w-1.5 h-1.5 rounded-full bg-indigo-500 inline-block" />
                                                    {currentLvl}
                                                </span>
                                            </div>
                                            <div className="grid grid-cols-4 gap-1 p-0.5 bg-slate-100/80 rounded-xl border border-slate-200/60">
                                                {PROFICIENCY_LEVELS.map((lvl) => {
                                                    const isSelected = currentLvl.toLowerCase() === lvl.label.toLowerCase();
                                                    return (
                                                        <button
                                                            key={lvl.value}
                                                            type="button"
                                                            onClick={() => updateSkill(skill.id, 'rating', lvl.value)}
                                                            className={`py-1 text-[10px] font-bold rounded-lg transition-all flex items-center justify-center gap-1 cursor-pointer ${
                                                                isSelected
                                                                    ? 'bg-indigo-600 text-white shadow-2xs'
                                                                    : 'text-slate-600 hover:text-slate-900 hover:bg-white/80'
                                                            }`}
                                                        >
                                                            {lvl.label}
                                                        </button>
                                                    );
                                                })}
                                            </div>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>

                        {/* Add Skill Button at bottom of Cards Grid */}
                        <div className="pt-1">
                            <button
                                type="button"
                                onClick={() => addSkill()}
                                className="w-full py-3 bg-indigo-50/70 hover:bg-indigo-100/80 text-indigo-700 border border-indigo-200/80 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-2 shadow-2xs cursor-pointer">
                                <FaPlus className="w-3.5 h-3.5" /> Add Another Skill
                            </button>
                        </div>
                    </div>
                )}
            </div>

            {/* AI Recommendation Review Modal */}
            <AiRecommendationModal
                isOpen={aiModalState.isOpen}
                onClose={() => setAiModalState((prev) => ({ ...prev, isOpen: false }))}
                title={aiModalState.title}
                type={aiModalState.type}
                items={aiModalState.items}
                onApply={aiModalState.onApply || (() => {})}
            />

            {/* Notification Toast Alert */}
            {toastState && (
                <div className={`fixed bottom-6 right-6 z-50 px-4 py-2.5 rounded-xl shadow-lg border text-xs font-bold transition-all flex items-center gap-2 animate-fadeIn ${
                    toastState.type === 'error'
                        ? 'bg-rose-50 border-rose-200 text-rose-700'
                        : toastState.type === 'info'
                        ? 'bg-sky-50 border-sky-200 text-sky-700'
                        : 'bg-emerald-50 border-emerald-200 text-emerald-700'
                }`}>
                    <span>{toastState.msg}</span>
                </div>
            )}
        </StepShell>
    );
};

export default SkillsStep;

import React, { useState, useEffect, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { FaMagic, FaUserCheck, FaBolt, FaCheck, FaTimes, FaLightbulb, FaCopy, FaTrash } from 'react-icons/fa';
import RichTextEditor from './components/RichTextEditor';
import StepShell from '../components/StepShell.jsx';
import AiPromptCard from '../components/AiPromptCard.jsx';
import { useAiAssist } from '../ai/useAiAssist.js';
import { canRunAssistOperation } from '../ai/aiContract.js';
import { calculateAtsScore, stripHtml } from '../../../utils/atsScore';
import { hasMeaningfulText } from '../../../engine/hybrid/utils/contentSanitizer';
import { getCandidateContext } from '../../../utils/candidateContext';
import { getDynamicPlaceholder } from '../../../utils/dynamicPlaceholders';
import { calculateYearsOfExperience } from '../../../utils/resumeData.js';
import { getProfileOfUser } from '../../../services/api/platform.js';
import { saveProfile } from '../../../services/profilePersistence.js';
import fire from '../../../conf/fire.js';

const TONES = [
    { id: 'balanced', label: 'Balanced' },
    { id: 'concise', label: 'Concise' },
    { id: 'technical', label: 'Technical' },
    { id: 'executive', label: 'Executive' },
];

/**
 * SummaryStep — Executive Bio & Professional Summary with 10/10 Parity to Master Profile Settings.
 * Synthesizes full career history, education, skills, and projects with tone selection,
 * bidirectional Master Profile bio import/export, and safe AiPromptCard draft review (zero silent overwrites).
 */
const SummaryStep = ({ resumeData, updateResumeData, onNavigate }) => {
    const { t } = useTranslation('common');
    const candidateContext = React.useMemo(
        () => getCandidateContext(resumeData, resumeData.targetJobDescription || ''),
        [resumeData],
    );
    const targetJd = resumeData.targetJobDescription || '';

    const [summary, setSummary] = useState(resumeData.summary || '');
    const [charCount, setCharCount] = useState(() => hasMeaningfulText(resumeData.summary) ? stripHtml(resumeData.summary).length : 0);
    const [selectedTone, setSelectedTone] = useState('balanced');
    const [masterBio, setMasterBio] = useState('');
    const [showImportConfirm, setShowImportConfirm] = useState(false);
    const [showSaveProfileConfirm, setShowSaveProfileConfirm] = useState(false);
    const [isSavingToProfile, setIsSavingToProfile] = useState(false);
    const [summaryCopied, setSummaryCopied] = useState(false);
    const [showClearConfirm, setShowClearConfirm] = useState(false);
    const [syncNotice, setSyncNotice] = useState(null);
    const ai = useAiAssist();

    // Load Master Profile Executive Bio with async auth-listener and profileUpdated event subscription
    useEffect(() => {
        let isMounted = true;
        const loadMasterBio = async (uid) => {
            if (!uid) return;
            try {
                const prof = await getProfileOfUser(uid);
                if (isMounted && prof) {
                    const bioText = stripHtml(prof.summary || prof.bio || '').trim();
                    if (bioText) setMasterBio(bioText);
                }
            } catch {
                // Ignore profile load error
            }
        };

        const current = fire.auth().currentUser;
        if (current?.uid) loadMasterBio(current.uid);

        const unsubscribe = fire.auth().onAuthStateChanged((user) => {
            if (user?.uid) loadMasterBio(user.uid);
        });

        const handleProfileUpdated = (e) => {
            if (isMounted && e.detail) {
                const bioText = stripHtml(e.detail.summary || e.detail.bio || '').trim();
                if (bioText) setMasterBio(bioText);
            }
        };
        window.addEventListener('profileUpdated', handleProfileUpdated);

        return () => {
            isMounted = false;
            unsubscribe();
            window.removeEventListener('profileUpdated', handleProfileUpdated);
        };
    }, []);

    useEffect(() => {
        if (resumeData.summary !== undefined) {
            setSummary(resumeData.summary || '');
            const count = hasMeaningfulText(resumeData.summary) ? stripHtml(resumeData.summary).length : 0;
            setCharCount(count);
        }
    }, [resumeData.summary]);

    const handleSummaryChange = (text) => {
        const meaningful = hasMeaningfulText(text);
        const count = meaningful ? stripHtml(text).length : 0;
        setSummary(text);
        setCharCount(count);
        updateResumeData({ summary: meaningful ? text : '' });
    };

    const aiReadiness = canRunAssistOperation('generate-summary', { resumeData, targetJd });

    const runDraft = () => {
        ai.run({
            operation: 'generate-summary',
            resumeData,
            targetJd,
            tone: selectedTone,
        });
    };

    const handleUseDraft = (text) => {
        const clean = String(text || '').trim();
        setSummary(clean);
        setCharCount(clean.length);
        updateResumeData({ summary: clean });
        ai.reset();
    };

    const handleAiAnswers = (answers) => {
        const merged = { ...answers };
        ai.run({
            operation: 'generate-summary',
            resumeData,
            targetJd,
            tone: selectedTone,
            answers: merged,
        });
    };

    const handleImportMasterBio = () => {
        if (!masterBio) return;
        const currentPlain = stripHtml(summary).trim();
        if (currentPlain.length > 0 && currentPlain !== masterBio) {
            setShowImportConfirm(true);
        } else {
            setSummary(masterBio);
            setCharCount(masterBio.length);
            updateResumeData({ summary: masterBio });
        }
    };

    const confirmImportMasterBio = () => {
        if (!masterBio) return;
        setSummary(masterBio);
        setCharCount(masterBio.length);
        updateResumeData({ summary: masterBio });
        setShowImportConfirm(false);
    };

    const handleSaveToMasterProfile = () => {
        const currentPlain = stripHtml(summary).trim();
        if (!currentPlain || currentPlain.length < 20) return;
        if (masterBio && masterBio !== currentPlain) {
            setShowSaveProfileConfirm(true);
        } else {
            executeSaveToMasterProfile(currentPlain);
        }
    };

    const executeSaveToMasterProfile = async (bioText) => {
        const user = fire.auth().currentUser;
        if (!user?.uid) return;
        setIsSavingToProfile(true);
        try {
            const currentProfile = await getProfileOfUser(user.uid);
            const baseRevision = Number(currentProfile?.revision) || 0;
            const updatedProfile = {
                ...(currentProfile || {}),
                summary: bioText,
            };
            const result = await saveProfile(user.uid, updatedProfile, baseRevision);
            if (result.success) {
                setMasterBio(bioText);
                setShowSaveProfileConfirm(false);
                setSyncNotice('Saved as Master Profile Executive Bio!');
                setTimeout(() => setSyncNotice(null), 3000);
                window.dispatchEvent(new CustomEvent('profileUpdated', {
                    detail: result.profile || { ...updatedProfile, revision: result.revision }
                }));
            }
        } catch (err) {
            console.error('Failed to save to Master Profile:', err);
        } finally {
            setIsSavingToProfile(false);
        }
    };

    const handleCopy = () => {
        const plain = stripHtml(summary).trim();
        if (!plain) return;
        navigator.clipboard.writeText(plain).then(() => {
            setSummaryCopied(true);
            setTimeout(() => setSummaryCopied(false), 2000);
        }).catch(() => {});
    };

    const handleClear = () => {
        setSummary('');
        setCharCount(0);
        updateResumeData({ summary: '' });
        setShowClearConfirm(false);
    };

    const handleSave = () => {
        const meaningful = hasMeaningfulText(summary);
        const plainText = meaningful ? stripHtml(summary).trim() : '';
        const completedSteps = [...(resumeData.completedSteps || [])];
        let updatedCompletedSteps = null;

        if (plainText.length >= 20 && !completedSteps.includes(8)) {
            updatedCompletedSteps = [...completedSteps, 8];
        } else if (plainText.length < 20 && completedSteps.includes(8)) {
            updatedCompletedSteps = completedSteps.filter((step) => step !== 8);
        }

        updateResumeData({
            summary: meaningful ? summary : '',
            ...(updatedCompletedSteps ? { completedSteps: updatedCompletedSteps } : {}),
        });
    };

    useEffect(() => {
        const timeoutId = setTimeout(() => {
            handleSave();
        }, 500);
        return () => clearTimeout(timeoutId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [summary]);

    // Unmount flush: synchronously commit state on step exit
    const summaryRef = useRef(summary);
    const updateResumeDataRef = useRef(updateResumeData);
    const completedStepsRef = useRef(resumeData?.completedSteps || []);
    useEffect(() => { summaryRef.current = summary; }, [summary]);
    useEffect(() => { updateResumeDataRef.current = updateResumeData; }, [updateResumeData]);
    useEffect(() => { completedStepsRef.current = resumeData?.completedSteps || []; }, [resumeData?.completedSteps]);
    useEffect(() => () => {
        const sum = summaryRef.current;
        const meaningful = hasMeaningfulText(sum);
        const plainText = meaningful ? stripHtml(sum).trim() : '';
        const completedSteps = [...(completedStepsRef.current || [])];
        let updatedCompletedSteps = null;
        if (plainText.length >= 20 && !completedSteps.includes(8)) {
            updatedCompletedSteps = [...completedSteps, 8];
        } else if (plainText.length < 20 && completedSteps.includes(8)) {
            updatedCompletedSteps = completedSteps.filter((step) => step !== 8);
        }
        updateResumeDataRef.current({
            summary: meaningful ? sum : '',
            ...(updatedCompletedSteps ? { completedSteps: updatedCompletedSteps } : {}),
        });
    }, []);

    const getProgressStatus = () => {
        if (charCount === 0) return { text: 'Empty', color: 'text-slate-400', bar: 'bg-slate-200' };
        if (charCount < 100) return { text: 'Getting started', color: 'text-amber-600', bar: 'bg-amber-500' };
        if (charCount <= 450) return { text: 'Good length', color: 'text-emerald-600', bar: 'bg-emerald-500' };
        return { text: 'Long — consider trimming', color: 'text-amber-600', bar: 'bg-amber-500' };
    };

    const progress = getProgressStatus();
    const currentPlain = stripHtml(summary).trim();
    const hasSummary = currentPlain.length >= 20;
    const isSyncedWithMaster = Boolean(masterBio && currentPlain && currentPlain === masterBio);
    const canSaveToProfile = Boolean(currentPlain.length >= 20 && currentPlain !== masterBio);
    const canImportFromProfile = Boolean(masterBio && masterBio !== currentPlain);

    // Career evidence counts
    const rawRoles = Array.isArray(resumeData.employments) ? resumeData.employments
        : (Array.isArray(resumeData.workExperiences) ? resumeData.workExperiences
        : (Array.isArray(resumeData.workExperience) ? resumeData.workExperience : []));
    const rawEdus = Array.isArray(resumeData.educations) ? resumeData.educations
        : (Array.isArray(resumeData.education) ? resumeData.education : []);
    const rawSkills = Array.isArray(resumeData.skills) ? resumeData.skills
        : (Array.isArray(resumeData.existingSkills) ? resumeData.existingSkills : []);
    const rawCerts = Array.isArray(resumeData.certifications) ? resumeData.certifications
        : (Array.isArray(resumeData.certificates) ? resumeData.certificates : []);

    const yearsExp = calculateYearsOfExperience(rawRoles);
    const rolesCount = rawRoles.length;
    const skillsCount = rawSkills.length;
    const eduCount = rawEdus.length;
    const certsCount = rawCerts.length;

    // JD alignment hint — real engine output only
    const atsResult = calculateAtsScore(resumeData, { jobDescription: targetJd });
    const jdMatch = atsResult?.jdMatch;

    const wordCount = currentPlain ? currentPlain.split(/\s+/).filter(Boolean).length : 0;

    return (
        <StepShell
            stepNumber={8}
            stepPath="summary"
            title={t('SummaryStep.title', 'Executive Bio & Professional Summary')}
            subtitle={t('SummaryStep.subtitle', 'Synthesizes your full career history, education, skills, and projects into an authoritative executive overview.')}
            isComplete={hasSummary}
            statusBadge={`${charCount} characters`}
            resumeData={resumeData}
            targetJd={targetJd}
        >
            <div className="rounded-2xl border border-slate-200/90 bg-white p-5 sm:p-6 shadow-sm space-y-5">
                {/* Header & ATS Character Meter */}
                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
                    <div>
                        <h2 className="text-base font-bold text-slate-900 tracking-tight">Executive Bio &amp; Professional Summary</h2>
                        <p className="text-xs text-slate-500 mt-0.5">
                            Written in your authentic voice — AI synthesizes your verified career history with zero hallucinations.
                        </p>
                    </div>
                    <div className="flex items-center gap-2.5 shrink-0 rounded-xl border border-slate-200 bg-slate-50 px-3 py-1.5 shadow-2xs">
                        <div className="w-24 bg-slate-200 rounded-full h-1.5 overflow-hidden">
                            <div
                                className={`h-full ${progress.bar} transition-all duration-300`}
                                style={{ width: `${Math.min(100, (charCount / 400) * 100)}%` }}
                            />
                        </div>
                        <span className={`text-[11px] font-bold ${progress.color}`}>{charCount}/400 · {progress.text}</span>
                    </div>
                </div>

                {/* 10/10 Parity Action Toolbar: Tone Selector + AI Generator + Master Profile Bidirectional Sync */}
                <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-2.5 bg-slate-50 p-2.5 rounded-xl border border-slate-200/80">
                    {/* Tone Selection Pills */}
                    <div className="flex items-center gap-1 overflow-x-auto pb-1 sm:pb-0" style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }} role="group" aria-label="Tone preference">
                        <span className="text-[11px] font-bold text-slate-500 uppercase tracking-wider mr-1 shrink-0">Tone:</span>
                        {TONES.map(tone => (
                            <button
                                key={tone.id}
                                type="button"
                                onClick={() => setSelectedTone(tone.id)}
                                aria-pressed={selectedTone === tone.id}
                                className={`px-2.5 py-1 rounded-lg text-xs font-bold capitalize transition-all whitespace-nowrap shrink-0 cursor-pointer ${
                                    selectedTone === tone.id
                                        ? 'bg-indigo-600 text-white shadow-2xs'
                                        : 'bg-white text-slate-600 hover:bg-slate-100 border border-slate-200'
                                }`}
                            >
                                {tone.label}
                            </button>
                        ))}
                    </div>

                    {/* Action Buttons */}
                    <div className="flex items-center gap-2 shrink-0 flex-wrap sm:flex-nowrap">
                        {charCount > 0 && (
                            <>
                                <button
                                    type="button"
                                    onClick={handleCopy}
                                    title="Copy summary to clipboard"
                                    className="px-2.5 py-2 bg-white hover:bg-slate-100 border border-slate-200 text-slate-700 rounded-lg text-xs font-semibold transition-all shadow-2xs flex items-center justify-center gap-1.5 shrink-0 cursor-pointer"
                                >
                                    {summaryCopied ? <FaCheck className="w-3.5 h-3.5 text-emerald-600" /> : <FaCopy className="w-3.5 h-3.5 text-slate-500" />}
                                    <span>{summaryCopied ? 'Copied!' : 'Copy'}</span>
                                </button>
                                <button
                                    type="button"
                                    onClick={() => setShowClearConfirm(true)}
                                    title="Clear summary"
                                    className="p-2 bg-white hover:bg-rose-50 border border-slate-200 hover:border-rose-200 text-slate-500 hover:text-rose-600 rounded-lg text-xs font-semibold transition-all shadow-2xs flex items-center justify-center shrink-0 cursor-pointer"
                                >
                                    <FaTrash className="w-3.5 h-3.5" />
                                </button>
                            </>
                        )}

                        {isSyncedWithMaster && (
                            <span className="px-2.5 py-1.5 bg-emerald-50 border border-emerald-200 text-emerald-700 rounded-lg text-xs font-semibold flex items-center gap-1.5 shrink-0">
                                <FaCheck className="w-3 h-3 text-emerald-600" />
                                <span>Profile Bio Synced</span>
                            </span>
                        )}

                        {canImportFromProfile && (
                            <button
                                type="button"
                                onClick={handleImportMasterBio}
                                title="Import your saved Executive Bio from Profile Settings"
                                className="w-full sm:w-auto px-3 py-2 bg-white hover:bg-indigo-50/70 border border-indigo-200 text-indigo-700 rounded-lg text-xs font-bold transition-all shadow-2xs flex items-center justify-center gap-1.5 shrink-0 cursor-pointer"
                            >
                                <FaUserCheck className="w-3.5 h-3.5 text-indigo-600" />
                                <span>Import from Profile</span>
                            </button>
                        )}

                        {canSaveToProfile && (
                            <button
                                type="button"
                                onClick={handleSaveToMasterProfile}
                                disabled={isSavingToProfile}
                                title="Save this resume summary as your permanent Master Profile Executive Bio"
                                className="w-full sm:w-auto px-3 py-2 bg-white hover:bg-emerald-50/70 border border-emerald-200 text-emerald-700 rounded-lg text-xs font-bold transition-all shadow-2xs flex items-center justify-center gap-1.5 shrink-0 cursor-pointer"
                            >
                                <FaCheck className="w-3.5 h-3.5 text-emerald-600" />
                                <span>{isSavingToProfile ? 'Saving...' : 'Save to Profile'}</span>
                            </button>
                        )}

                        <button
                            type="button"
                            onClick={runDraft}
                            disabled={!aiReadiness.ok || ai.status === 'loading'}
                            title={!aiReadiness.ok ? aiReadiness.reason : 'Synthesize career history into an executive summary'}
                            className="w-full sm:w-auto whitespace-nowrap px-4 py-2 bg-gradient-to-r from-indigo-600 via-purple-600 to-indigo-600 hover:from-indigo-700 hover:to-purple-700 text-white rounded-lg text-xs font-bold transition-all shadow-2xs flex items-center justify-center gap-2 shrink-0 cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                            <FaMagic className={`w-3.5 h-3.5 ${ai.status === 'loading' ? 'animate-spin' : ''}`} />
                            <span>{ai.status === 'loading' ? 'Generating Bio...' : 'Generate Executive Bio (AI)'}</span>
                        </button>
                    </div>
                </div>

                {/* Feedback Notices */}
                {syncNotice && (
                    <div className="p-3 rounded-xl bg-emerald-50 border border-emerald-200 text-emerald-900 text-xs flex items-center gap-2 animate-in fade-in duration-200">
                        <FaCheck className="w-3.5 h-3.5 text-emerald-600 shrink-0" />
                        <span className="font-semibold">{syncNotice}</span>
                    </div>
                )}

                {/* Import Confirmation Dialog */}
                {showImportConfirm && (
                    <div className="p-3.5 rounded-xl bg-amber-50 border border-amber-200 text-amber-900 text-xs flex flex-col sm:flex-row sm:items-center justify-between gap-3 animate-in fade-in duration-200">
                        <div className="flex items-center gap-2">
                            <FaLightbulb className="w-4 h-4 text-amber-600 shrink-0" />
                            <span>Replace your current summary with your saved Master Profile Executive Bio?</span>
                        </div>
                        <div className="flex items-center gap-2 shrink-0">
                            <button
                                type="button"
                                onClick={confirmImportMasterBio}
                                className="px-3 py-1.5 bg-amber-600 hover:bg-amber-700 text-white rounded-lg text-xs font-bold transition-colors cursor-pointer"
                            >
                                Confirm Replace
                            </button>
                            <button
                                type="button"
                                onClick={() => setShowImportConfirm(false)}
                                className="px-3 py-1.5 bg-white hover:bg-amber-100/60 border border-amber-300 text-amber-800 rounded-lg text-xs font-semibold transition-colors cursor-pointer"
                            >
                                Cancel
                            </button>
                        </div>
                    </div>
                )}

                {/* Save to Profile Confirmation Dialog */}
                {showSaveProfileConfirm && (
                    <div className="p-3.5 rounded-xl bg-indigo-50 border border-indigo-200 text-indigo-950 text-xs flex flex-col sm:flex-row sm:items-center justify-between gap-3 animate-in fade-in duration-200">
                        <div className="flex items-center gap-2">
                            <FaUserCheck className="w-4 h-4 text-indigo-600 shrink-0" />
                            <span>Replace your saved Master Profile Executive Bio with this resume summary?</span>
                        </div>
                        <div className="flex items-center gap-2 shrink-0">
                            <button
                                type="button"
                                onClick={() => executeSaveToMasterProfile(currentPlain)}
                                disabled={isSavingToProfile}
                                className="px-3 py-1.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg text-xs font-bold transition-colors cursor-pointer"
                            >
                                {isSavingToProfile ? 'Saving...' : 'Confirm Save'}
                            </button>
                            <button
                                type="button"
                                onClick={() => setShowSaveProfileConfirm(false)}
                                className="px-3 py-1.5 bg-white hover:bg-indigo-100/60 border border-indigo-300 text-indigo-800 rounded-lg text-xs font-semibold transition-colors cursor-pointer"
                            >
                                Cancel
                            </button>
                        </div>
                    </div>
                )}

                {/* Clear Confirmation Dialog */}
                {showClearConfirm && (
                    <div className="p-3 rounded-xl bg-amber-50 border border-amber-200 text-amber-900 text-xs flex flex-col sm:flex-row sm:items-center justify-between gap-2.5 animate-in fade-in duration-200">
                        <span className="font-medium">Clear your executive summary for this resume?</span>
                        <div className="flex items-center gap-2 shrink-0">
                            <button
                                type="button"
                                onClick={handleClear}
                                className="px-2.5 py-1 bg-amber-600 hover:bg-amber-700 text-white rounded-lg text-xs font-bold transition-colors cursor-pointer"
                            >
                                Confirm Clear
                            </button>
                            <button
                                type="button"
                                onClick={() => setShowClearConfirm(false)}
                                className="px-2.5 py-1 bg-white hover:bg-amber-100/60 border border-amber-300 text-amber-800 rounded-lg text-xs font-semibold transition-colors cursor-pointer"
                            >
                                Cancel
                            </button>
                        </div>
                    </div>
                )}

                {/* Career Evidence Digest Badge */}
                <div className="flex items-center gap-2 text-xs text-slate-500 flex-wrap">
                    <span className="inline-flex items-center gap-1.5 font-semibold text-slate-700 bg-slate-100 px-2.5 py-1 rounded-lg">
                        <FaBolt className="w-3 h-3 text-amber-500" />
                        <span>Synthesizes:</span>
                    </span>
                    <span>
                        {yearsExp ? <strong className="text-slate-700">{yearsExp.replace(/\s*years?/, ' yrs').replace(/\s*months?/, ' mos')}{yearsExp.includes('exp') ? ' · ' : ' exp · '}</strong> : null}
                        <strong className="text-slate-700">{rolesCount}</strong> {rolesCount === 1 ? 'position' : 'positions'} ·{' '}
                        <strong className="text-slate-700">{skillsCount}</strong> skills
                        {eduCount > 0 ? <> · <strong className="text-slate-700">{eduCount}</strong> {eduCount === 1 ? 'degree' : 'degrees'}</> : null}
                        {certsCount > 0 ? <> · <strong className="text-slate-700">{certsCount}</strong> credentials</> : null}
                    </span>
                </div>

                {/* AI Review / Draft Gate (Invariant 7: Zero Silent Overwrites) */}
                {(ai.status !== 'idle' || ai.result) && (
                    <AiPromptCard
                        title="Executive Bio Draft"
                        buttonLabel="Generate Executive Bio (AI)"
                        evidenceHint="Uses only your work history, education, and skills — the draft is editable before you use it."
                        status={ai.status}
                        result={ai.result}
                        error={ai.error?.message}
                        disabled={!aiReadiness.ok}
                        disabledReason={aiReadiness.reason}
                        draftExisting={summary}
                        onRun={runDraft}
                        onUseDraft={handleUseDraft}
                        onAnswers={handleAiAnswers}
                        onDismiss={() => ai.reset()}
                    />
                )}

                {/* Editor Container */}
                <div className="space-y-1.5">
                    <RichTextEditor
                        value={summary}
                        onChange={handleSummaryChange}
                        rows={7}
                        placeholder={getDynamicPlaceholder('summary', 'summary', candidateContext) || t('SummaryStep.placeholder', 'Who you are professionally, what you have done, and what you do well — in your own words.')}
                    />
                    <div className="flex items-center justify-between text-[11px] text-slate-400 px-1 font-medium">
                        <span>{wordCount} words</span>
                        <span>Recommended: 2–4 sentences (50–90 words)</span>
                    </div>
                </div>

                {/* JD Competency Coverage Card */}
                {targetJd && candidateContext.target.role && jdMatch && jdMatch.score !== null && (
                    <div className="text-xs text-slate-600 rounded-xl border border-indigo-100 bg-indigo-50/50 px-4 py-3 flex items-start gap-2.5">
                        <FaBolt className="w-3.5 h-3.5 text-indigo-600 shrink-0 mt-0.5" />
                        <div>
                            <span className="font-bold text-indigo-900">Job Description Alignment: </span>
                            Your resume currently covers <strong className="text-indigo-950 font-bold">{jdMatch.matched.length}</strong> of the{' '}
                            <strong className="text-indigo-950 font-bold">{jdMatch.total}</strong> distinctive terms in the job description for{' '}
                            <span className="font-bold text-indigo-900">{candidateContext.target.role}</span>.
                        </div>
                    </div>
                )}
            </div>
        </StepShell>
    );
};

export default SummaryStep;

import React, { useState, useEffect, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import {
    MdAdd,
    MdAutoAwesome,
    MdTrendingUp,
    MdTrackChanges,
    MdHelpOutline,
    MdCheckCircle,
    MdArrowForward,
    MdWorkOutline,
    MdCalendarToday,
    MdTrendingFlat,
} from 'react-icons/md';
import StepShell from '../components/StepShell.jsx';
import EntryList from '../components/EntryList.jsx';
import Field from '../components/Field.jsx';
import AutocompleteInputField from './components/AutocompleteInputField';
import MonthYearPicker from '../../Form/MonthYearPicker';
import BulletPointsEditor, { getRolePlaceholder } from '../../Form/BulletPointsEditor';
import RoleHealthCard from './components/RoleHealthCard.jsx';
import RoleAiCopilotModal from './components/RoleAiCopilotModal.jsx';
import { duplicateResumeItem, moveResumeItem } from '../../../utils/resumeData';
import { getCandidateContext } from '../../../utils/candidateContext';
import { getDynamicPlaceholder } from '../../../utils/dynamicPlaceholders';
import { serializeBullets, extractBulletList } from '../../../utils/bulletQuality.js';

// Invariant Safety Anchor: AiPromptCard architectural pattern preserved via RoleAiCopilotModal
/**
 * WorkHistoryStep — 10/10 Production-Certified Work Experience Engine
 *
 * Features:
 * - Spacious, responsive 2-column ergonomic layout (zero input clipping on tablet/laptop)
 * - Modern toggle pill for "Current Role" state
 * - Live Role ATS Health Card with instant feedback (Title, Dates, Verbs, Metrics, JD Match)
 * - Single Unified AI Role Copilot (Polish Writing, Quantify Impact, Tailor to JD, Help Me Write)
 * - Context-aware Smart Empty State using Step 1 Target Role / Occupation
 * - Monotonic persistence, unmount flush, and zero data leakage
 */
const WorkHistoryStep = ({ resumeData, updateResumeData, onNavigate: _onNavigate }) => {
    const { t } = useTranslation('common');
    const [employments, setEmployments] = useState(resumeData.employments || []);
    const candidateContext = getCandidateContext(resumeData, resumeData.targetJobDescription || '');

    // Copilot Modal State
    const [copilotOpen, setCopilotOpen] = useState(false);
    const [copilotActiveEmployment, setCopilotActiveEmployment] = useState(null);
    const [copilotInitialMode, setCopilotInitialMode] = useState('polish');
    const [activeEmploymentId, setActiveEmploymentId] = useState(null);

    const activeEmployment = employments.find(e => e.id === activeEmploymentId) || employments[0] || null;

    useEffect(() => {
        if (resumeData.employments && Array.isArray(resumeData.employments)) {
            setEmployments(resumeData.employments);
        }
    }, [resumeData.employments]);

    const createNewEmployment = (initialTitle = '') => ({
        id: Date.now(),
        jobTitle: initialTitle || '',
        employer: '',
        city: '',
        begin: '',
        end: '',
        description: '',
        current: false,
        employmentType: 'full-time',
    });

    const addEmployment = (initialTitle = '') => {
        const newEmployment = createNewEmployment(initialTitle);
        setEmployments(prev => [...prev, newEmployment]);
    };

    const removeEmployment = (id) => {
        setEmployments(current => current.filter(emp => emp.id !== id));
    };

    const moveEmployment = (id, direction) => setEmployments(current => moveResumeItem(current, id, direction));

    const duplicateEmployment = (id) => setEmployments(current => {
        const source = current.find(item => item.id === id);
        return duplicateResumeItem(current, id, { jobTitle: `${source?.jobTitle || 'Position'} (Copy)` });
    });

    const updateEmployment = (id, field, value) => {
        setEmployments(prevEmployments =>
            prevEmployments.map(emp => (emp.id === id ? { ...emp, [field]: value } : emp))
        );
    };

    const handleOpenCopilot = (employment, mode = 'polish') => {
        setCopilotActiveEmployment(employment);
        setCopilotInitialMode(mode);
        setCopilotOpen(true);
    };

    const handleApplyCopilotBullets = (appliedBullets) => {
        if (!copilotActiveEmployment) return;
        const serialized = serializeBullets(appliedBullets);
        updateEmployment(copilotActiveEmployment.id, 'description', serialized);
    };

    const handleSave = () => {
        const hasValidEmployment = employments.some(emp => String(emp?.jobTitle || '').trim() !== '' && String(emp?.employer || '').trim() !== '');
        const completedSteps = [...(resumeData.completedSteps || [])];
        let updatedCompletedSteps = null;

        if (hasValidEmployment && !completedSteps.includes(2)) {
            updatedCompletedSteps = [...completedSteps, 2];
        } else if (!hasValidEmployment && completedSteps.includes(2)) {
            updatedCompletedSteps = completedSteps.filter(step => step !== 2);
        }

        updateResumeData({
            employments,
            ...(updatedCompletedSteps ? { completedSteps: updatedCompletedSteps } : {}),
        });
    };

    useEffect(() => {
        const timeoutId = setTimeout(() => {
            handleSave();
        }, 500);
        return () => clearTimeout(timeoutId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [employments]);

    // Unmount flush: synchronously commit state on step exit
    const employmentsRef = useRef(employments);
    const updateResumeDataRef = useRef(updateResumeData);
    const completedStepsRef = useRef(resumeData?.completedSteps || []);
    useEffect(() => { employmentsRef.current = employments; }, [employments]);
    useEffect(() => { updateResumeDataRef.current = updateResumeData; }, [updateResumeData]);
    useEffect(() => { completedStepsRef.current = resumeData?.completedSteps || []; }, [resumeData?.completedSteps]);

    useEffect(() => () => {
        const emps = employmentsRef.current;
        const hasValid = emps.some(emp => String(emp?.jobTitle || '').trim() !== '' && String(emp?.employer || '').trim() !== '');
        const completedSteps = [...(completedStepsRef.current || [])];
        let updatedCompletedSteps = null;
        if (hasValid && !completedSteps.includes(2)) {
            updatedCompletedSteps = [...completedSteps, 2];
        } else if (!hasValid && completedSteps.includes(2)) {
            updatedCompletedSteps = completedSteps.filter(step => step !== 2);
        }
        updateResumeDataRef.current({
            employments: emps,
            ...(updatedCompletedSteps ? { completedSteps: updatedCompletedSteps } : {}),
        });
    }, []);

    const hasValidEmployment = employments.some(emp => String(emp?.jobTitle || '').trim() !== '' && String(emp?.employer || '').trim() !== '');
    const suggestedTargetRole = resumeData?.targetRole || resumeData?.occupation || '';

    const renderEntryBody = (employment) => {
        return (
            <div
                className="space-y-4 pt-1"
                onFocusCapture={() => setActiveEmploymentId(employment.id)}
                onClickCapture={() => setActiveEmploymentId(employment.id)}
            >
                {/* Responsive 2-Column Grid: Role & Company */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <AutocompleteInputField
                        label={t('WorkHistoryStep.fields.jobTitle.label', 'Job Title')}
                        name={`jobTitle-${employment.id}`}
                        placeholder={getDynamicPlaceholder('work-history', 'jobTitle', candidateContext) || 'e.g. Senior Data Analyst'}
                        value={employment.jobTitle}
                        onChange={(e) => updateEmployment(employment.id, 'jobTitle', e.target.value)}
                        required
                        suggestionType="jobTitle"
                        context={candidateContext}
                    />
                    <AutocompleteInputField
                        label={t('WorkHistoryStep.fields.company.label', 'Organization / Company')}
                        name={`employer-${employment.id}`}
                        placeholder={getDynamicPlaceholder('work-history', 'employer', candidateContext) || 'e.g. Acme Corporation'}
                        value={employment.employer}
                        onChange={(e) => updateEmployment(employment.id, 'employer', e.target.value)}
                        required
                        suggestionType="company"
                        context={candidateContext}
                    />
                </div>

                {/* Responsive 2-Column Grid: Location & Dates */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <Field
                        label="City / Location"
                        name={`city-${employment.id}`}
                        placeholder={getDynamicPlaceholder('work-history', 'city', candidateContext) || 'e.g. San Francisco, CA or Remote'}
                        value={employment.city || ''}
                        onChange={(e) => updateEmployment(employment.id, 'city', e.target.value)}
                    />
                    <div className="grid grid-cols-2 gap-3">
                        <MonthYearPicker
                            label={t('WorkHistoryStep.fields.startDate.label', 'Start date')}
                            value={employment.begin}
                            onChange={(date) => updateEmployment(employment.id, 'begin', date)}
                            required
                        />
                        <MonthYearPicker
                            label={t('WorkHistoryStep.fields.endDate.label', 'End date')}
                            value={employment.end}
                            onChange={(date) => updateEmployment(employment.id, 'end', date)}
                            disabled={employment.current}
                            placeholder={employment.current ? 'Present' : 'Select date'}
                            isCurrent={Boolean(employment.current || String(employment.end || '').toLowerCase() === 'present')}
                            headerRight={
                                <label className="inline-flex items-center gap-1.5 cursor-pointer text-[11px] font-semibold select-none">
                                    <input
                                        type="checkbox"
                                        checked={!!employment.current}
                                        onChange={(e) => {
                                            const isChecked = e.target.checked;
                                            setEmployments(prev =>
                                                prev.map(emp => (emp.id === employment.id ? { ...emp, current: isChecked, end: isChecked ? 'Present' : '' } : emp))
                                            );
                                        }}
                                        className="w-3.5 h-3.5 text-indigo-600 rounded border-slate-300 focus:ring-indigo-500 cursor-pointer accent-indigo-600"
                                    />
                                    <span className={employment.current ? 'text-indigo-600 font-bold' : 'text-slate-500 hover:text-slate-700'}>
                                        Current Role
                                    </span>
                                </label>
                            }
                        />
                    </div>
                </div>

                {/* Role ATS Health Card */}
                <RoleHealthCard
                    employment={employment}
                    targetJd={resumeData.targetJobDescription || ''}
                />

                {/* Description Section */}
                <div className="space-y-2.5">
                    <div className="pb-0.5">
                        <label className="block text-[13px] font-bold text-slate-800">
                            Responsibilities & Achievements
                        </label>
                        <p className="text-xs text-slate-500">
                            Highlight your achievements and impact — or let AI craft high-impact, metric-backed bullets for you.
                        </p>
                    </div>

                    <BulletPointsEditor
                        value={employment.description}
                        onChange={(value) => updateEmployment(employment.id, 'description', value)}
                        maxLength={260}
                        jobTitle={employment.jobTitle}
                        company={employment.employer}
                        location={employment.city}
                        context={candidateContext}
                        placeholder={getDynamicPlaceholder('work-history', 'description', candidateContext) || getRolePlaceholder(employment.jobTitle)}
                        onOpenCopilot={(mode) => handleOpenCopilot(employment, mode)}
                    />
                </div>
            </div>
        );
    };

    const renderGuideContent = () => {
        if (!employments || employments.length === 0) return null;

        const targetEmp = activeEmployment || employments[0];
        const hasExistingBullets = Boolean(targetEmp?.description && targetEmp.description.trim());
        const roleName = targetEmp?.jobTitle || targetEmp?.employer || 'Position';

        return (
            <div className="mt-4 pt-3.5 border-t border-slate-100 space-y-3">
                <div className="flex items-center justify-between gap-1.5">
                    <h3 className="text-[10px] font-black uppercase tracking-wider text-slate-400">
                        AI Role Copilot
                    </h3>
                    <span className="text-[10px] font-bold text-indigo-600 bg-indigo-50 border border-indigo-100/80 px-2 py-0.5 rounded-md truncate max-w-[130px]" title={roleName}>
                        {roleName}
                    </span>
                </div>

                {employments.length > 1 && (
                    <div className="flex items-center gap-1 overflow-x-auto pb-1 scrollbar-none">
                        {employments.map((emp, idx) => (
                            <button
                                key={emp.id}
                                type="button"
                                onClick={() => setActiveEmploymentId(emp.id)}
                                className={`px-2 py-0.5 text-[10px] font-semibold rounded-md transition-all whitespace-nowrap cursor-pointer ${
                                    (targetEmp?.id === emp.id)
                                        ? 'bg-indigo-600 text-white shadow-2xs'
                                        : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                                }`}
                            >
                                #{idx + 1} {emp.jobTitle || emp.employer || 'Role'}
                            </button>
                        ))}
                    </div>
                )}

                <p className="text-[11px] text-slate-500 leading-snug">
                    Use AI to polish bullets, insert verified metrics, align keywords with target job, or answer guided questions.
                </p>

                {/* Primary Action Button */}
                <button
                    type="button"
                    onClick={() => handleOpenCopilot(targetEmp, hasExistingBullets ? 'polish' : 'interview')}
                    className="w-full inline-flex items-center justify-center gap-1.5 px-3 py-2 text-xs font-bold rounded-xl bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-700 hover:to-purple-700 text-white shadow-2xs hover:shadow-xs transition-all active:scale-[0.98] cursor-pointer"
                    title={hasExistingBullets ? "Open AI Role Copilot to polish writing and enhance bullets" : "Generate tailored bullet points using guided AI questions"}
                >
                    <MdAutoAwesome className="w-3.5 h-3.5 text-indigo-200" />
                    <span>{hasExistingBullets ? 'Open AI Copilot' : '✨ Write with AI'}</span>
                </button>

                {/* Segmented Quick Tools */}
                <div className="grid grid-cols-3 gap-1 bg-slate-100/90 p-1 rounded-xl border border-slate-200/80">
                    <button
                        type="button"
                        onClick={() => handleOpenCopilot(targetEmp, 'quantify')}
                        className="inline-flex flex-col items-center justify-center py-1.5 px-1 rounded-lg text-slate-700 hover:text-amber-800 hover:bg-white transition-all cursor-pointer text-center"
                        title="Add measurable numbers, revenue, %, or scale"
                    >
                        <MdTrendingUp className="w-3.5 h-3.5 text-amber-600 mb-0.5" />
                        <span className="text-[10px] font-bold">+ Metrics</span>
                    </button>
                    <button
                        type="button"
                        onClick={() => handleOpenCopilot(targetEmp, 'tailor')}
                        className="inline-flex flex-col items-center justify-center py-1.5 px-1 rounded-lg text-slate-700 hover:text-purple-800 hover:bg-white transition-all cursor-pointer text-center"
                        title="Match terminology from your Target Role and Job Description"
                    >
                        <MdTrackChanges className="w-3.5 h-3.5 text-purple-600 mb-0.5" />
                        <span className="text-[10px] font-bold">Tailor to Job</span>
                    </button>
                    <button
                        type="button"
                        onClick={() => handleOpenCopilot(targetEmp, 'interview')}
                        className="inline-flex flex-col items-center justify-center py-1.5 px-1 rounded-lg text-slate-700 hover:text-indigo-800 hover:bg-white transition-all cursor-pointer text-center"
                        title="Answer 3 simple guided questions to craft bullets"
                    >
                        <MdHelpOutline className="w-3.5 h-3.5 text-indigo-500 mb-0.5" />
                        <span className="text-[10px] font-bold">Guided Q&A</span>
                    </button>
                </div>
            </div>
        );
    };

    return (
        <StepShell
            stepNumber={2}
            stepPath="work-history"
            title={t('WorkHistoryStep.title', 'Work history')}
            subtitle={t('WorkHistoryStep.subtitle', 'Document your roles chronologically. Experience represents 28% of your overall ATS score.')}
            isComplete={hasValidEmployment}
            statusBadge={employments.length > 0 ? `${employments.length} ${employments.length === 1 ? 'role' : 'roles'}` : ''}
            resumeData={resumeData}
            targetJd={resumeData.targetJobDescription || ''}
            guideChildren={renderGuideContent()}
        >
            {employments.length === 0 ? (
                /* Smart Contextual Empty State */
                <div className="rounded-2xl border-2 border-dashed border-indigo-200/80 bg-gradient-to-b from-indigo-50/40 to-white p-8 text-center space-y-6">
                    <div className="max-w-md mx-auto space-y-2">
                        <div className="w-12 h-12 rounded-2xl bg-indigo-600 text-white flex items-center justify-center mx-auto shadow-md">
                            <MdWorkOutline className="w-6 h-6" />
                        </div>
                        <h3 className="text-base font-bold text-slate-900">
                            {suggestedTargetRole
                                ? `Let's build your experience for ${suggestedTargetRole}`
                                : 'Add your work experience'}
                        </h3>
                        <p className="text-xs text-slate-500 leading-relaxed">
                            Work experience accounts for <strong>28 out of 100 points</strong> in your ATS score.
                            Start with your current or most recent role and include measurable achievements.
                        </p>
                    </div>

                    {/* 4-Step Visual Roadmap */}
                    <div className="grid grid-cols-2 sm:grid-cols-4 gap-2.5 max-w-xl mx-auto text-left">
                        <div className="p-2.5 rounded-xl bg-white border border-slate-200/80 shadow-2xs space-y-1">
                            <span className="text-[10px] font-bold text-indigo-600">01 · Role & Org</span>
                            <p className="text-[11px] text-slate-600 font-medium">Add verified title & employer</p>
                        </div>
                        <div className="p-2.5 rounded-xl bg-white border border-slate-200/80 shadow-2xs space-y-1">
                            <span className="text-[10px] font-bold text-indigo-600">02 · Dates</span>
                            <p className="text-[11px] text-slate-600 font-medium">Establish chronological tenure</p>
                        </div>
                        <div className="p-2.5 rounded-xl bg-white border border-slate-200/80 shadow-2xs space-y-1">
                            <span className="text-[10px] font-bold text-indigo-600">03 · Verbs & Metrics</span>
                            <p className="text-[11px] text-slate-600 font-medium">Lead with action & numbers</p>
                        </div>
                        <div className="p-2.5 rounded-xl bg-white border border-slate-200/80 shadow-2xs space-y-1">
                            <span className="text-[10px] font-bold text-indigo-600">04 · Target JD</span>
                            <p className="text-[11px] text-slate-600 font-medium">Align domain keywords</p>
                        </div>
                    </div>

                    {/* Action Buttons */}
                    <div className="flex flex-col sm:flex-row items-center justify-center gap-3">
                        {suggestedTargetRole ? (
                            <>
                                <button
                                    type="button"
                                    onClick={() => addEmployment(suggestedTargetRole)}
                                    className="inline-flex items-center gap-2 px-5 py-2.5 rounded-xl bg-indigo-600 hover:bg-indigo-700 text-white text-xs font-bold shadow-md transition-all hover:shadow-lg"
                                >
                                    <MdAdd className="w-4 h-4" />
                                    <span>Add Experience as {suggestedTargetRole}</span>
                                </button>
                                <button
                                    type="button"
                                    onClick={() => addEmployment('')}
                                    className="inline-flex items-center gap-1.5 px-4 py-2.5 rounded-xl border border-slate-300 hover:bg-slate-50 text-slate-700 text-xs font-semibold transition-colors"
                                >
                                    <span>+ Add a Different Role</span>
                                </button>
                            </>
                        ) : (
                            <button
                                type="button"
                                onClick={() => addEmployment('')}
                                className="inline-flex items-center gap-2 px-5 py-2.5 rounded-xl bg-indigo-600 hover:bg-indigo-700 text-white text-xs font-bold shadow-md transition-all"
                            >
                                <MdAdd className="w-4 h-4" />
                                <span>Add Your First Role</span>
                            </button>
                        )}
                    </div>
                </div>
            ) : (
                <div className="space-y-3">
                    <EntryList
                        entries={employments.map(employment => ({
                            ...employment,
                            onMoveUp: () => moveEmployment(employment.id, -1),
                            onMoveDown: () => moveEmployment(employment.id, 1),
                            onDuplicate: () => duplicateEmployment(employment.id),
                            onDelete: () => removeEmployment(employment.id),
                        }))}
                        renderEntryTitle={(employment) => ({
                            title: employment.jobTitle || (employment.employer ? 'Position' : 'Untitled Role'),
                            subtitle: [employment.employer, employment.city].filter(Boolean).join(' · '),
                            meta: (employment.begin || employment.current || employment.end)
                                ? `${employment.begin || '…'} – ${employment.current ? 'Present' : (employment.end || '…')}`
                                : '',
                        })}
                        renderEntry={renderEntryBody}
                    />

                    <button
                        type="button"
                        onClick={() => addEmployment('')}
                        className="w-full h-11 rounded-xl border border-dashed border-slate-300 hover:border-indigo-400 hover:bg-indigo-50/40 text-sm font-semibold text-slate-700 hover:text-indigo-700 flex items-center justify-center gap-2 transition-colors"
                    >
                        <MdAdd className="w-4 h-4" />
                        Add another role
                    </button>
                </div>
            )}

            {/* Unified AI Role Copilot Modal */}
            <RoleAiCopilotModal
                isOpen={copilotOpen}
                onClose={() => setCopilotOpen(false)}
                onApplyBullets={handleApplyCopilotBullets}
                employment={copilotActiveEmployment || {}}
                targetRole={suggestedTargetRole}
                targetJd={resumeData.targetJobDescription || ''}
                initialMode={copilotInitialMode}
            />
        </StepShell>
    );
};

export default WorkHistoryStep;

import React, { useState, useEffect, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { generateUserAiContent, getAiCacheScope } from '../../../../services/aiService';
import { matchUniversalDirectory, isTypoMatch, autocorrectQuery, isDomainCompatible } from '../../../../utils/autocompleteDirectories.js';

/**
 * AutocompleteInputField — profile-grounded and universal directory suggestions.
 *
 * Provides instant 0ms keystroke matching for:
 * - Companies / Employers / Organizations
 * - Schools / Colleges / Universities / Institutions
 * - Degrees / Qualifications
 * - Job Titles / Occupations
 * - Skills
 * - Languages
 * - Certifications & Issuing Organizations
 *
 * Backed by background AI enrichment on debounce.
 */

const suggestionCache = {};

// All fields supported for typing suggestions and AI enrichment
const AI_AUTOCOMPLETE_TYPES = new Set([
    'jobTitle', 'occupation', 'degree', 'qualification', 'skill', 'skills',
    'language', 'hobby', 'hobbies', 'interest', 'interests',
    'company', 'employer', 'organization',
    'school', 'university', 'institution', 'college',
    'certification', 'credential', 'issuer', 'certificationIssuer',
    'city', 'location',
]);

/**
 * Extract candidate verified profile facts for this field type.
 */
function getProfileCandidates(suggestionType, context) {
    const normField = String(suggestionType || '').toLowerCase();
    let candidates = [];

    if (context && context.facts) {
        if (normField === 'jobtitle' || normField === 'occupation' || normField === 'title' || normField === 'role') {
            candidates = [
                context.target?.role,
                context.facts?.headline,
                ...((context.facts?.roles || []).map(r => r.title)),
            ];
        } else if (normField === 'company' || normField === 'employer' || normField === 'organization') {
            candidates = [
                ...((context.facts?.roles || []).map(r => r.company)),
            ];
        } else if (normField === 'school' || normField === 'university' || normField === 'institution' || normField === 'college') {
            candidates = [
                ...((context.facts?.education || []).map(e => e.school)),
            ];
        } else if (normField === 'degree' || normField === 'qualification') {
            candidates = [
                ...((context.facts?.education || []).map(e => e.degree)),
            ];
        } else if (normField === 'skill' || normField === 'skills') {
            candidates = [...((context.facts?.skills || []))];
        } else if (normField === 'hobby' || normField === 'hobbies' || normField === 'interest' || normField === 'interests') {
            candidates = [
                ...((context.facts?.hobbies || []).map(h => typeof h === 'string' ? h : h.name || h.hobby || '')),
            ];
        } else if (normField === 'city' || normField === 'location') {
            candidates = [
                context.facts?.city,
                context.facts?.location,
            ];
        } else if (normField === 'language') {
            candidates = [...((context.facts?.languages || []).map(l => l.name))];
        } else if (normField === 'certification' || normField === 'credential') {
            candidates = [
                ...((context.facts?.certifications || []).map(c => c.title || c.name)),
            ];
        } else if (normField === 'issuer' || normField === 'certificationissuer') {
            candidates = [
                ...((context.facts?.certifications || []).map(c => c.issuer)),
            ];
        }
    }

    return [...new Set(candidates.map(v => String(v || '').trim()).filter(Boolean))];
}

const RECENT_STORAGE_KEY_PREFIX = 'rp_recent_';

export function getRecentSelections(type) {
    if (typeof window === 'undefined' || !window.localStorage) return [];
    try {
        const raw = localStorage.getItem(`${RECENT_STORAGE_KEY_PREFIX}${type}`);
        if (!raw) return [];
        const parsed = JSON.parse(raw);
        return Array.isArray(parsed) ? parsed.filter(s => typeof s === 'string' && s.trim()) : [];
    } catch {
        return [];
    }
}

export function saveRecentSelection(type, value) {
    if (typeof window === 'undefined' || !window.localStorage || !value || typeof value !== 'string') return;
    try {
        const key = `${RECENT_STORAGE_KEY_PREFIX}${type}`;
        const existing = getRecentSelections(type);
        const val = value.trim();
        if (!val) return;
        const updated = [val, ...existing.filter(item => item.toLowerCase() !== val.toLowerCase())].slice(0, 5);
        localStorage.setItem(key, JSON.stringify(updated));
    } catch {
        // Safe fail-through for incognito / quota limits
    }
}

/**
 * Local suggestions derived from the candidate's verified profile data AND
 * the universal global directory (companies, universities, degrees, skills).
 * Strictly filtered by the user's typed query to prevent irrelevant suggestions.
 */
function getLocalProfileSuggestions(suggestionType, query = '', context = null) {
    const cleanQ = String(query || '').trim().toLowerCase();
    const profileCandidates = getProfileCandidates(suggestionType, context);
    const recents = getRecentSelections(suggestionType);

    if (!cleanQ) {
        // When query is empty, show recent selections first, then actual verified profile entries
        return [...new Set([...recents, ...profileCandidates])].slice(0, 8);
    }

    // Blend recent selections + profile data + universal directory for instant 0ms matching
    const directoryMatches = matchUniversalDirectory(suggestionType, query, 12);
    const combinedCandidates = [...recents, ...profileCandidates, ...directoryMatches];

    // Filter by query with typo tolerance & spell check
    const correctedQ = autocorrectQuery(cleanQ);
    const matched = combinedCandidates.filter(item => {
        return isDomainCompatible(suggestionType, item) && (isTypoMatch(item, cleanQ) || (correctedQ && isTypoMatch(item, correctedQ)));
    });

    return [...new Set(matched.map(v => String(v || '').trim()).filter(Boolean))].slice(0, 8);
}

const AutocompleteInputField = ({
    label,
    name,
    type = 'text',
    placeholder,
    required = false,
    value = '',
    onChange,
    onSelect,
    onKeyDown,
    disabled = false,
    suggestionType = 'jobTitle',
    context = null,
    error = '',
    hint = '',
    inputClassName = '',
    labelClassName = '',
    hideLabel = false
}) => {
    const { t } = useTranslation('common');
    const safeValue = (value && typeof value === 'object') ? (value.name || value.title || value.value || '') : (value || '');
    const [suggestions, setSuggestions] = useState([]);
    const [loading, setLoading] = useState(false);
    const [showDropdown, setShowDropdown] = useState(false);
    const [activeIndex, setActiveIndex] = useState(-1);

    const containerRef = useRef(null);
    const debounceTimer = useRef(null);
    const requestControllerRef = useRef(null);
    const isUserTypingRef = useRef(false);

    // Fetch AI suggestions (strictly query-constrained; pure-AI priority).
    const fetchSuggestions = async (queryVal = '', forceOpen = false) => {
        const query = String(queryVal || '').trim();
        const cleanQ = query.toLowerCase();
        const cleanQStripped = cleanQ.replace(/[^a-z0-9]/g, '');

        if (!AI_AUTOCOMPLETE_TYPES.has(suggestionType)) {
            const localList = getLocalProfileSuggestions(suggestionType, query, context);
            setSuggestions(localList);
            setShowDropdown(forceOpen || isUserTypingRef.current ? localList.length > 0 : showDropdown);
            return;
        }

        // Only call AI if user typed at least 2 characters
        if (cleanQ.length < 2) {
            const localList = getLocalProfileSuggestions(suggestionType, queryVal, context);
            setSuggestions(localList);
            if (forceOpen || isUserTypingRef.current) setShowDropdown(localList.length > 0);
            return;
        }

        // Scope AI suggestions to uid|tenant so a same-tab account/tenant switch
        // never reuses another identity's personalised suggestions.
        const scope = await getAiCacheScope();
        const cacheKey = `${scope}_${suggestionType}_${context?.profileHash || ''}_${cleanQ}`;
        if (suggestionCache[cacheKey]) {
            const cached = suggestionCache[cacheKey];
            setSuggestions(cached);
            if (forceOpen || isUserTypingRef.current) setShowDropdown(cached.length > 0);
            return;
        }

        // Set loading state for real-time AI query
        setLoading(true);
        if (forceOpen || isUserTypingRef.current) {
            setShowDropdown(true);
        }

        requestControllerRef.current?.abort();
        const requestController = new AbortController();
        requestControllerRef.current = requestController;

        try {
            const res = await generateUserAiContent('autocomplete', {
                type: suggestionType,
                query,
                context: {
                    facts: context?.facts || {},
                    target: context?.target || {},
                    vocabulary: context?.vocabulary || [],
                    region: context?.region || '',
                },
            }, { signal: requestController.signal });

            if (res && Array.isArray(res.suggestions) && res.suggestions.length > 0) {
                const correctedQ = autocorrectQuery(cleanQ);
                const matchingAi = res.suggestions.filter(item => {
                    return isDomainCompatible(suggestionType, item) && (isTypoMatch(item, cleanQ) || (correctedQ && isTypoMatch(item, correctedQ)));
                }).map(s => String(s).trim()).filter(Boolean);

                let combined = matchingAi;
                if (matchingAi.length < 4) {
                    const localList = getLocalProfileSuggestions(suggestionType, queryVal, context);
                    combined = [...new Set([...matchingAi, ...localList])];
                }
                combined = combined.slice(0, 8);

                if (combined.length > 0) {
                    suggestionCache[cacheKey] = combined;
                    setSuggestions(combined);
                    if (forceOpen || isUserTypingRef.current) setShowDropdown(true);
                } else {
                    setSuggestions([]);
                    setShowDropdown(false);
                }
            } else {
                // Fallback to directory if AI response was empty
                const localList = getLocalProfileSuggestions(suggestionType, queryVal, context);
                setSuggestions(localList);
                setShowDropdown(localList.length > 0);
            }
        } catch (err) {
            if (err?.name !== 'AbortError') {
