const htmlToPlainText = (val) => {
    if (!val) return '';
    if (!/<[^>]*>/g.test(val)) return String(val).trim();
    return String(val)
        .replace(/<\/(p|div|li|h[1-6])>/gi, '\n')
        .replace(/<br\s*\/?>/gi, '\n')
        .replace(/<[^>]*>/g, '')
        .replace(/&nbsp;/gi, ' ')
        .replace(/&#160;/gi, ' ')
        .replace(/&amp;/gi, '&')
        .replace(/&lt;/gi, '<')
        .replace(/&gt;/gi, '>')
        .replace(/&quot;/gi, '"')
        .replace(/&#39;/gi, "'")
        .replace(/\n{3,}/g, '\n\n')
        .trim();
};

const normalizeProfileForSave = value => {
    const authEmail = fire.auth().currentUser?.email;
    return normalizeProfileData({
        ...value,
        email: (authEmail || value?.email || '').trim().toLowerCase(),
        postalcode: value?.postalCode || '',
        website: value?.websiteUrl || ''
    });
};

