function DashboardSettings(_props) {
    const { i18n } = useTranslation('common');
    const location = useLocation();
    const navigate = useNavigate();

    // State management
    const [selectedSettings, setSelectedSettings] = useState('Profile');
    const [profileSubTab, setProfileSubTab] = useState('basic');
    const [showProfileGuidanceRail, setShowProfileGuidanceRail] = useState(true);
    const subTabsRef = useRef(null);
    const [showStepsDropdown, setShowStepsDropdown] = useState(false);
    const stepsDropdownRef = useRef(null);

    // Close steps dropdown when clicking outside or pressing Escape
    useEffect(() => {
        const handleClickOutside = (e) => {
            if (stepsDropdownRef.current && !stepsDropdownRef.current.contains(e.target)) {
                setShowStepsDropdown(false);
            }
        };
        const handleKeyDown = (e) => {
            if (e.key === 'Escape') setShowStepsDropdown(false);
        };
        if (showStepsDropdown) {
            document.addEventListener('mousedown', handleClickOutside);
            document.addEventListener('keydown', handleKeyDown);
        }
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
            document.removeEventListener('keydown', handleKeyDown);
        };
    }, [showStepsDropdown]);

    const scrollSubTabs = (direction) => {
        if (subTabsRef.current) {
            const offset = direction === 'left' ? -220 : 220;
            subTabsRef.current.scrollBy({ left: offset, behavior: 'smooth' });
        }
    };

    useEffect(() => {
        if (subTabsRef.current) {
            const activeBtn = subTabsRef.current.querySelector('.step-nav-btn[aria-current="step"]');
            if (activeBtn) {
                activeBtn.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
            }
        }
    }, [profileSubTab]);

    const SUB_TAB_ORDER = ['basic', 'experience', 'education', 'skills', 'certifications', 'projects', 'languages', 'hobbies', 'achievements', 'references', 'customSections', 'summary'];

    // Seamless Subtab Switching with URL Deep-Linking
    const switchProfileSubTab = (tabKey) => {
        if (!SUB_TAB_ORDER.includes(tabKey)) return;
        setProfileSubTab(tabKey);
        navigate(`?tab=Profile&subtab=${tabKey}`, { replace: true });
    };

    // Stepper Keyboard Navigation (ArrowLeft / ArrowRight)
    const handleStepperKeyDown = (e) => {
        const currentIdx = SUB_TAB_ORDER.indexOf(profileSubTab);
        if (e.key === 'ArrowRight' && currentIdx < SUB_TAB_ORDER.length - 1) {
            e.preventDefault();
            switchProfileSubTab(SUB_TAB_ORDER[currentIdx + 1]);
        } else if (e.key === 'ArrowLeft' && currentIdx > 0) {
            e.preventDefault();
            switchProfileSubTab(SUB_TAB_ORDER[currentIdx - 1]);
        }
    };

    // Interactive Copilot Gap Focusing Helper
    const handleFocusGap = (gapText) => {
        const lower = String(gapText || '').toLowerCase();
        let targetSelector = null;

        if (lower.includes('name')) targetSelector = 'input[name="firstname"], input[name="lastname"]';
        else if (lower.includes('job title') || lower.includes('headline')) targetSelector = 'input[name="occupation"]';
        else if (lower.includes('phone')) targetSelector = 'input[name="phone"]';
        else if (lower.includes('location') || lower.includes('city') || lower.includes('country')) targetSelector = 'input[name="city"], input[name="country"]';
        else if (lower.includes('summary') || lower.includes('bio')) targetSelector = 'textarea[name="summary"]';
        else if (lower.includes('work position') || lower.includes('role')) targetSelector = 'button:has-text("Add Position"), input[name="jobTitle"]';
        else if (lower.includes('education') || lower.includes('degree')) targetSelector = 'input[name="school"], input[name="degree"]';
        else if (lower.includes('skill')) targetSelector = 'input[placeholder*="skill" i], input[placeholder*="Search" i]';
        else if (lower.includes('project')) targetSelector = 'input[name="title"], input[placeholder*="Project" i]';
        else if (lower.includes('language')) targetSelector = 'input[placeholder*="Language" i], input[name="language"]';

        if (targetSelector) {
            try {
                const el = document.querySelector(targetSelector);
                if (el) {
                    el.scrollIntoView({ behavior: 'smooth', block: 'center' });
                    el.focus();
                    el.classList.add('ring-2', 'ring-indigo-400');
                    setTimeout(() => el.classList.remove('ring-2', 'ring-indigo-400'), 2000);
                }
            } catch {
                // Ignore selector parsing nuances
            }
        }
    };

    // Reactive URL query parameter listener for ?tab=Account, ?tab=Profile, and ?subtab=...
    useEffect(() => {
        const searchParams = new URLSearchParams(location.search);
        const tabParam = searchParams.get('tab');
        const subTabParam = searchParams.get('subtab') || searchParams.get('section') || searchParams.get('step');
        if (tabParam) {
            const lower = tabParam.toLowerCase();
            if (lower.includes('account') || lower.includes('security') || lower === '2fa') {
                setSelectedSettings('Account');
            } else if (lower.includes('profile')) {
                setSelectedSettings('Profile');
            }
        }
        if (subTabParam) {
            const matched = SUB_TAB_ORDER.find(k => k.toLowerCase() === subTabParam.toLowerCase());
            if (matched) {
                setProfileSubTab(matched);
            }
        }
    }, [location.search]);
    const [summaryTone, setSummaryTone] = useState('balanced');
    const [summaryAiDraft, setSummaryAiDraft] = useState(null);
    const [bioCopied, setBioCopied] = useState(false);
    const [showClearBioConfirm, setShowClearBioConfirm] = useState(false);
    const [_skillFilter] = useState('all');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [profileSaveState, setProfileSaveState] = useState('loading');
    const [profileConflict, setProfileConflict] = useState(null);
    const persistProfileRef = useRef(null);
    const profileRef = useRef(null);
    const profileConflictRef = useRef(null);
    const profileSavingRef = useRef(null);
    const pendingProfileSaveRef = useRef(null);
    const skipNextAutosaveRef = useRef(false);
    const autosaveTimerRef = useRef(null);
    const loadedProfileUidRef = useRef(null);
    const mountedRef = useRef(true);
    const [isAiGenerating, setIsAiGenerating] = useState(false);
    const aiRequestControllerRef = useRef(null);
    const [toastState, setToastState] = useState(null);
    const [cropModalSrc, setCropModalSrc] = useState(null); // raw image src waiting to be cropped
    const [aiModalState, setAiModalState] = useState({
        isOpen: false,
        title: '',
        type: 'skills',
        items: [],
        onApply: null
    });
    const [projectSearchQuery, setProjectSearchQuery] = useState('');
    const [projectTypeFilter, setProjectTypeFilter] = useState('all');
    const [certSearchQuery, setCertSearchQuery] = useState('');
    const [certTypeFilter, setCertTypeFilter] = useState('all');
    const [achievementSearchQuery, setAchievementSearchQuery] = useState('');
    const [achievementTypeFilter, setAchievementTypeFilter] = useState('all');
    const [isPolishingAchIndex, setIsPolishingAchIndex] = useState(null);

    const [accountSettings, setAccountSettings] = useState({
        email: '',
        password: '',
    });
    const [databaseAccountSettings, setDatabaseAccountSettings] = useState({
        email: '',
        membership: '',
        membershipEnds: '',
    });
    const [accountPasswordState, setAccountPasswordState] = useState({
        currentPassword: '',
        newPassword: '',
        confirmPassword: '',
    });
    const [showPasswordMap, setShowPasswordMap] = useState({
        current: false,
        new: false,
        confirm: false,
    });
    const [deleteAccountModalOpen, setDeleteAccountModalOpen] = useState(false);
    const [deleteInputText, setDeleteInputText] = useState('');
    const [deletePassword, setDeletePassword] = useState('');
    const [_userTransactions, setUserTransactions] = useState([]);
    const [preferences, setPreferences] = useState({ language: 'en', emailNotifications: true, securityNotifications: true, productUpdates: false, profileDiscoverable: false, revision: 0 });
    const [savingPreferences, setSavingPreferences] = useState(false);
    const [isSubscriptionModalOpen, setIsSubscriptionModalOpen] = useState(false);

    // TOTP 2FA State Management
    const [totpStatus, setTotpStatus] = useState({ enabled: false, secret: null, backupCodes: [] });
    const [totpSetupModalOpen, setTotpSetupModalOpen] = useState(false);
    const [totpSetupStep, setTotpSetupStep] = useState(1);
    const [totpSetupSecret, setTotpSetupSecret] = useState('');
    const [totpEnrollmentSecret, setTotpEnrollmentSecret] = useState(null);
    const [totpQrCodeDataUrl, setTotpQrCodeDataUrl] = useState('');
    const [totpVerificationCode, setTotpVerificationCode] = useState('');
    const [totpDisableModalOpen, setTotpDisableModalOpen] = useState(false);
    const [totpDisablePassword, setTotpDisablePassword] = useState('');
    const [loginHistory, setLoginHistory] = useState([]);
    const userAuthProviders = (fire.auth().currentUser?.providerData || []).map(provider => provider?.providerId).filter(Boolean);
    const usesPasswordProvider = userAuthProviders.includes('password');
    const isOAuthOnly = userAuthProviders.length > 0 && !usesPasswordProvider;
    void isOAuthOnly;
    const primaryOAuthProvider = userAuthProviders.find(p => p !== 'password') === 'google.com' ? 'Google' : (userAuthProviders.find(p => p !== 'password') || 'OAuth');

    // Master Profile State matching ALL Resume & Cover Letter fields
    const [profile, setProfile] = useState({
        firstname: '',
        lastname: '',
        name: '',
        email: '',
        phone: '',
        address: '',
        city: '',
        postalCode: '',
        country: '',
        occupation: '',
        linkedinUrl: '',
        githubUrl: '',
        websiteUrl: '',
        summary: '',
        selectedImage: null,
        workExperiences: [],
        education: [],
        skills: [],
        languages: [],
        hobbies: [],
        certifications: [],
        projects: [],
        achievements: [],
        references: [],
        customSections: [],
        revision: 0,
    });

    const candidateContext = React.useMemo(() => ({
        target: { role: profile.occupation || profile.workExperiences?.[0]?.jobTitle || '' },
        facts: {
            headline: profile.occupation || '',
            roles: profile.workExperiences || [],
            education: profile.education || [],
            skills: (profile.skills || []).map(s => typeof s === 'string' ? s : s?.name || s?.skillName || ''),
            certifications: profile.certifications || []
        }
    }), [profile.occupation, profile.workExperiences, profile.education, profile.skills, profile.certifications]);

    const [isDragging, setIsDragging] = useState(false);

    // Toast Notification helper
    const triggerNotification = (msg, type = 'success') => {
        setToastState({ msg, type });
        setTimeout(() => setToastState(null), 5000);
    };

    // Global Escape Key Listener for dismissible modal dialogs
    useEffect(() => {
        const handleGlobalEscape = (e) => {
            if (e.key === 'Escape') {
                if (deleteAccountModalOpen && !isSubmitting) setDeleteAccountModalOpen(false);
                if (totpSetupModalOpen && !isSubmitting) setTotpSetupModalOpen(false);
                if (totpDisableModalOpen && !isSubmitting) setTotpDisableModalOpen(false);
                if (cropModalSrc) setCropModalSrc(null);
                if (isSubscriptionModalOpen) setIsSubscriptionModalOpen(false);
            }
        };
        window.addEventListener('keydown', handleGlobalEscape);
        return () => window.removeEventListener('keydown', handleGlobalEscape);
    }, [deleteAccountModalOpen, totpSetupModalOpen, totpDisableModalOpen, cropModalSrc, isSubscriptionModalOpen, isSubmitting]);

    // Data normalizers for historical profile shapes
    const normalizeSkills = (arr) => {
        if (!Array.isArray(arr)) return [];
        return arr.map((item, idx) => {
            if (typeof item === 'string') return { id: `skill_${idx}_${Date.now()}`, name: item, level: '' };
            if (item && typeof item === 'object') return { id: item.id || `skill_${idx}`, name: item.name || item.title || '', level: item.level || '' };
            return { id: `skill_${idx}`, name: String(item || ''), level: '' };
        });
    };

    const normalizeLanguages = (arr) => {
        if (!Array.isArray(arr)) return [];
        return arr.map((item, idx) => {
            if (typeof item === 'string') return { id: `lang_${idx}_${Date.now()}`, name: item, level: '' };
            if (item && typeof item === 'object') return { id: item.id || `lang_${idx}`, name: item.name || item.language || '', level: item.level || item.proficiency || '' };
            return { id: `lang_${idx}`, name: String(item || ''), level: '' };
        });
    };

    const normalizeHobbies = (arr) => {
        if (!Array.isArray(arr)) {
            if (typeof arr === 'string' && arr.trim()) return [arr.trim()];
            return [];
        }
        return arr.map(item => {
            if (typeof item === 'string') return item;
            if (item && typeof item === 'object') return item.name || item.hobby || item.title || item.interest || '';
            return String(item || '');
        }).filter(Boolean);
    };

    const normalizeCertifications = (arr) => {
        if (!Array.isArray(arr)) return [];
        return arr.map((item, idx) => {
            if (typeof item === 'string') return { id: `cert_${idx}_${Date.now()}`, title: item, issuer: '', date: '', endDate: '', credentialId: '', url: '', certType: 'Certification', isLicense: false };
            if (item && typeof item === 'object') return {
                id: item.id || `cert_${idx}`,
                title: item.title || item.name || '',
                issuer: item.issuer || item.authority || '',
                date: item.date || item.year || '',
                endDate: item.endDate || item.expirationDate || '',
                credentialId: item.credentialId || item.idNumber || item.licenseNumber || '',
                url: item.url || item.verificationUrl || item.link || '',
                certType: item.certType || (item.isLicense ? 'License' : 'Certification'),
                isLicense: Boolean(item.isLicense || item.certType === 'License'),
            };
            return { id: `cert_${idx}`, title: String(item || ''), issuer: '', date: '', endDate: '', credentialId: '', url: '', certType: 'Certification', isLicense: false };
        });
    };

    const normalizeWorkExperiences = (arr) => {
        if (!Array.isArray(arr)) return [];
        return arr.map((item, idx) => {
            if (!item || typeof item !== 'object') return { id: `work_${idx}`, jobTitle: '', company: '', city: '', startDate: '', endDate: '', description: '' };
            return {
                id: item.id || `work_${idx}`,
                jobTitle: String(item.jobTitle || item.title || item.position || ''),
                company: String(item.company || item.employer || ''),
