export default function DashboardSupport({ showToast, sidebarCollapsed }) {
    const { t } = useTranslation('common');
    const [tickets, setTickets] = useState([]);
    const [statusFilter, setStatusFilter] = useState('ALL');
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedTicketId, setSelectedTicketId] = useState(null);
    const [ticketDetail, setTicketDetail] = useState(null);
    const [isLoadingList, setIsLoadingList] = useState(true);
    const [isLoadingDetail, setIsLoadingDetail] = useState(false);
    const [listError, setListError] = useState('');
    const [detailError, setDetailError] = useState('');
    const [replyText, setReplyText] = useState('');
    const [isSubmittingReply, setIsSubmittingReply] = useState(false);

    const [activeSupportTab, setActiveSupportTab] = useState('tickets'); // 'tickets' | 'faq'
    const [faqSearch, setFaqSearch] = useState('');
    const [expandedFaqIndex, setExpandedFaqIndex] = useState(null);

    // Modal state for creating a new support ticket
    const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
    const [newSubject, setNewSubject] = useState('');
    const [newPriority, setNewPriority] = useState('NORMAL');
    const [newBody, setNewBody] = useState('');
    const [isCreatingTicket, setIsCreatingTicket] = useState(false);
    const [createError, setCreateError] = useState('');

    // Load ticket list for the logged-in candidate
    const loadTickets = useCallback(async () => {
        setIsLoadingList(true);
        setListError('');
        try {
            const user = fire.auth().currentUser;
            if (!user) {
                setTickets([]);
                return;
            }
            const fetched = await getUserSupportTickets();
            setTickets(Array.isArray(fetched) ? fetched : []);
        } catch (err) {
            console.error('[DashboardSupport] load error:', err);
            setListError(err.message || 'Unable to load your support tickets.');
            if (showToast) showToast('error', 'Error', 'Failed to load support tickets');
        } finally {
            setIsLoadingList(false);
        }
    }, [showToast]);

    useEffect(() => {
        loadTickets();
    }, [loadTickets]);

    // Load detailed thread for selected ticket
    const loadDetail = useCallback(async (ticketId) => {
        if (!ticketId) {
            setTicketDetail(null);
            return;
        }
        setIsLoadingDetail(true);
        setDetailError('');
        try {
            const ticket = await getUserSupportTicket(ticketId);
            setTicketDetail(ticket);
        } catch (err) {
            console.error('[DashboardSupport] detail load error:', err);
            setDetailError(err.message || 'Unable to load ticket conversation.');
            if (showToast) showToast('error', 'Error', 'Failed to load ticket details');
        } finally {
            setIsLoadingDetail(false);
        }
    }, [showToast]);

    useEffect(() => {
        if (selectedTicketId) {
            loadDetail(selectedTicketId);
        } else {
            setTicketDetail(null);
        }
    }, [selectedTicketId, loadDetail]);

    // Global escape key listener for modal
    useEffect(() => {
        const handleKeyDown = (e) => {
            if (e.key === 'Escape') {
                if (isCreateModalOpen && !isCreatingTicket) {
                    setIsCreateModalOpen(false);
                }
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [isCreateModalOpen, isCreatingTicket]);

    // Create ticket handler
    const handleCreateTicket = async (e) => {
        e.preventDefault();
        const cleanSubject = newSubject.trim();
        const cleanBody = newBody.trim();

        if (cleanSubject.length < 4) {
            setCreateError('Subject must be at least 4 characters long.');
            return;
        }
        if (cleanBody.length < 8) {
            setCreateError('Please provide a descriptive message of at least 8 characters.');
            return;
        }

        setCreateError('');
        setIsCreatingTicket(true);

        try {
            const created = await createUserSupportTicket({
                subject: cleanSubject,
                body: cleanBody,
                priority: newPriority,
            });

            setIsCreateModalOpen(false);
            setNewSubject('');
            setNewBody('');
            setNewPriority('NORMAL');
            if (showToast) showToast('success', 'Ticket Submitted', 'Our support engineering team will assist you shortly.');
            await loadTickets();
            if (created?.id) {
                setSelectedTicketId(created.id);
            }
        } catch (err) {
            console.error('[DashboardSupport] create error:', err);
            setCreateError(err.message || 'Unable to create support ticket. Please try again.');
        } finally {
            setIsCreatingTicket(false);
        }
    };

    // Reply to ticket handler
    const handleSendReply = async (e) => {
        e.preventDefault();
        const cleanReply = replyText.trim();
        if (!selectedTicketId || !cleanReply || isSubmittingReply) return;

        setIsSubmittingReply(true);
        setDetailError('');

        try {
            const updated = await replyUserSupportTicket(selectedTicketId, cleanReply);
            setTicketDetail(updated);
            setReplyText('');
            if (showToast) showToast('success', 'Message Sent', 'Your reply has been added to the ticket.');
            // Refresh list in background to update timestamps/counts
            loadTickets();
        } catch (err) {
            console.error('[DashboardSupport] reply error:', err);
            setDetailError(err.message || 'Unable to post your reply.');
        } finally {
            setIsSubmittingReply(false);
        }
    };

    // Filter tickets by status and search query
    const filteredTickets = useMemo(() => {
        const query = searchTerm.toLowerCase().trim();
        return tickets.filter((t) => {
            const matchesStatus = statusFilter === 'ALL' || String(t.status).toUpperCase() === statusFilter;
            const matchesSearch = !query ||
                String(t.subject || '').toLowerCase().includes(query) ||
                String(t.id || '').toLowerCase().includes(query);
            return matchesStatus && matchesSearch;
        });
    }, [tickets, statusFilter, searchTerm]);

    const getStatusPill = (status) => {
        const s = String(status || '').toUpperCase();
        switch (s) {
            case 'OPEN':
                return 'bg-amber-50 text-amber-700 border-amber-200';
            case 'PENDING':
                return 'bg-blue-50 text-blue-700 border-blue-200';
            case 'RESOLVED':
                return 'bg-emerald-50 text-emerald-700 border-emerald-200';
            case 'CLOSED':
            default:
                return 'bg-slate-100 text-slate-700 border-slate-200';
        }
    };

    const getPriorityPill = (priority) => {
        const p = String(priority || '').toUpperCase();
        switch (p) {
            case 'URGENT':
                return 'bg-rose-50 text-rose-700 border-rose-200 font-black';
            case 'HIGH':
                return 'bg-orange-50 text-orange-700 border-orange-200 font-bold';
            case 'NORMAL':
                return 'bg-indigo-50 text-indigo-700 border-indigo-200';
            case 'LOW':
            default:
                return 'bg-slate-100 text-slate-600 border-slate-200';
        }
    };

    const formatDate = (isoString) => {
        if (!isoString) return 'Recent';
        try {
            const d = new Date(isoString);
            return d.toLocaleDateString(undefined, {
                year: 'numeric',
                month: 'short',
                day: 'numeric',
                hour: '2-digit',
                minute: '2-digit',
            });
        } catch (_) {
            return String(isoString);
        }
    };

    return (
        <div className="min-h-screen bg-slate-50 py-6 px-4 sm:px-6 lg:px-8" data-testid="user-support-desk">
            <div className="max-w-7xl mx-auto space-y-6">

                {/* ── HEADER & ACTIONS ────────────────────────────────────────── */}
                <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 bg-white p-5 rounded-2xl border border-slate-200/80 shadow-2xs">
                    <div className="flex items-center gap-3.5">
                        <div className="w-12 h-12 rounded-2xl bg-indigo-50 border border-indigo-100 text-indigo-600 flex items-center justify-center shrink-0 shadow-2xs">
                            <FiLifeBuoy className="w-6 h-6" />
                        </div>
                        <div>
                            <h1 className="text-xl sm:text-2xl font-bold text-slate-900 tracking-tight">
                                Help Desk &amp; Support Tickets
                            </h1>
                            <p className="text-xs sm:text-sm text-slate-500 mt-0.5">
                                Connect directly with our support engineering team for account, billing, or export assistance.
                            </p>
                        </div>
                    </div>

                    <div className="flex items-center gap-2.5 shrink-0">
                        <button
                            type="button"
                            onClick={loadTickets}
                            disabled={isLoadingList}
                            className="inline-flex items-center gap-1.5 px-3.5 py-2.5 rounded-xl border border-slate-200 bg-white text-xs font-bold text-slate-700 hover:bg-slate-50 hover:text-slate-900 transition shadow-2xs cursor-pointer disabled:opacity-50"
                            aria-label="Refresh tickets"
                            data-testid="refresh-tickets-button"
                        >
                            <FiRefreshCw className={`w-3.5 h-3.5 ${isLoadingList ? 'animate-spin' : ''}`} />
                            <span className="hidden sm:inline">Refresh</span>
                        </button>

                        <button
                            type="button"
                            onClick={() => {
                                setCreateError('');
                                setIsCreateModalOpen(true);
                            }}
                            className="inline-flex items-center gap-2 px-4 py-2.5 rounded-xl bg-indigo-600 text-white text-xs font-bold hover:bg-indigo-700 active:bg-indigo-800 transition shadow-sm hover:shadow shadow-indigo-500/20 cursor-pointer"
                            data-testid="create-ticket-button"
                        >
                            <FiPlus className="w-4 h-4" />
                            <span>Raise New Ticket</span>
                        </button>
                    </div>
                </div>

                {/* ── LIST ERROR NOTIFICATION ──────────────────────────────────── */}
                {listError && (
                    <div role="alert" className="p-4 bg-rose-50 border border-rose-200 rounded-2xl text-xs text-rose-800 flex items-center justify-between gap-3">
                        <div className="flex items-center gap-2">
                            <FiAlertCircle className="w-4 h-4 text-rose-600 shrink-0" />
                            <span>{listError}</span>
                        </div>
                        <button
                            onClick={loadTickets}
                            className="px-3 py-1 bg-rose-100 hover:bg-rose-200 text-rose-900 font-bold rounded-lg transition cursor-pointer"
                        >
                            Retry
                        </button>
                    </div>
                )}

                {/* ── SUB-NAVIGATION TABS ────────────────────────────────────────── */}
                <div className="flex items-center gap-2 border-b border-slate-200 pb-2">
                    <button
                        onClick={() => setActiveSupportTab('tickets')}
                        className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                            activeSupportTab === 'tickets'
                                ? 'bg-indigo-600 text-white shadow-sm'
                                : 'bg-white text-slate-600 hover:bg-slate-100 hover:text-slate-900 border border-slate-200/80'
                        }`}
                        data-testid="tab-support-tickets"
                    >
                        <FiInbox className="w-3.5 h-3.5" />
                        <span>My Support Tickets</span>
                        <span className={`px-1.5 py-0.5 rounded-full text-[10px] font-black ${
                            activeSupportTab === 'tickets' ? 'bg-indigo-800 text-indigo-100' : 'bg-slate-100 text-slate-600'
                        }`}>
                            {tickets.length}
                        </span>
                    </button>

                    <button
                        onClick={() => setActiveSupportTab('faq')}
                        className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                            activeSupportTab === 'faq'
                                ? 'bg-indigo-600 text-white shadow-sm'
                                : 'bg-white text-slate-600 hover:bg-slate-100 hover:text-slate-900 border border-slate-200/80'
                        }`}
                        data-testid="tab-knowledge-base"
                    >
                        <FiHelpCircle className="w-3.5 h-3.5" />
                        <span>Knowledge Base &amp; FAQs</span>
                    </button>
                </div>

                {/* ── KNOWLEDGE BASE & FAQ VIEW ───────────────────────────────── */}
                {activeSupportTab === 'faq' && (
                    <div className="bg-white p-6 rounded-2xl border border-slate-200/80 shadow-2xs space-y-6" data-testid="support-knowledge-base">
                        <div className="max-w-2xl mx-auto text-center space-y-2">
                            <h2 className="text-lg sm:text-xl font-bold text-slate-900">Frequently Asked Questions &amp; Knowledge Base</h2>
                            <p className="text-xs sm:text-sm text-slate-500">Instant answers to common candidate questions about resume building, AI tools, exports, and accounts.</p>
                            <div className="relative mt-4">
                                <FiSearch className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4 pointer-events-none" />
                                <input
                                    type="text"
                                    placeholder="Search knowledge base articles..."
                                    value={faqSearch}
                                    onChange={(e) => setFaqSearch(e.target.value)}
                                    className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs text-slate-800 placeholder-slate-400 focus:outline-none focus:bg-white focus:border-indigo-500 transition-all"
                                    aria-label="Search FAQs"
                                />
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-4">
                            {KNOWLEDGE_BASE_ITEMS.map((cat, catIdx) => {
                                const filteredItems = cat.items.filter(item => {
                                    if (!faqSearch) return true;
                                    const q = faqSearch.toLowerCase();
                                    return item.q.toLowerCase().includes(q) || item.a.toLowerCase().includes(q);
                                });
                                if (filteredItems.length === 0) return null;

                                return (
                                    <div key={cat.category} className="bg-slate-50/80 rounded-2xl p-5 border border-slate-200/60 space-y-3">
                                        <div className="flex items-center gap-2 text-indigo-700 font-bold text-sm">
                                            <FiBook className="w-4 h-4 text-indigo-600" />
                                            <span>{cat.category}</span>
                                        </div>
                                        <div className="space-y-2">
                                            {filteredItems.map((item, itemIdx) => {
                                                const globalIdx = `${catIdx}_${itemIdx}`;
                                                const isExpanded = expandedFaqIndex === globalIdx;
                                                return (
                                                    <div key={item.q} className="bg-white rounded-xl border border-slate-200/80 overflow-hidden shadow-2xs">
                                                        <button
                                                            onClick={() => setExpandedFaqIndex(isExpanded ? null : globalIdx)}
                                                            className="w-full px-4 py-3 text-left text-xs font-bold text-slate-800 flex items-center justify-between gap-3 hover:text-indigo-600 transition-colors cursor-pointer"
                                                        >
                                                            <span>{item.q}</span>
                                                            {isExpanded ? <FiChevronUp className="w-4 h-4 text-slate-400 shrink-0" /> : <FiChevronDown className="w-4 h-4 text-slate-400 shrink-0" />}
                                                        </button>
                                                        {isExpanded && (
                                                            <div className="px-4 pb-3.5 pt-1 text-xs text-slate-600 border-t border-slate-100 leading-relaxed bg-slate-50/50">
                                                                {item.a}
                                                            </div>
                                                        )}
                                                    </div>
                                                );
                                            })}
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                )}

                {/* ── MAIN WORKSPACE GRID ──────────────────────────────────────── */}
                {activeSupportTab === 'tickets' && (
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">

                    {/* LEFT PANEL: Tickets Queue & Search */}
                    <div className={`${selectedTicketId ? 'hidden lg:block' : 'block'} lg:col-span-5 space-y-4`}>
                        {/* Search & Status Filters */}
                        <div className="bg-white p-4 rounded-2xl border border-slate-200/80 shadow-2xs space-y-3">
                            <div className="relative">
                                <FiSearch className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                                <input
                                    type="text"
                                    placeholder="Search by subject or ticket ID..."
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                    className="w-full pl-9 pr-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs text-slate-800 placeholder-slate-400 focus:outline-hidden focus:bg-white focus:border-indigo-500 transition"
                                    data-testid="support-search-input"
                                />
                                {searchTerm && (
                                    <button
                                        onClick={() => setSearchTerm('')}
                                        className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 cursor-pointer"
                                    >
                                        <FiX className="w-3.5 h-3.5" />
                                    </button>
                                )}
                            </div>

                            {/* Status Filter Tabs */}
                            <div className="flex flex-wrap items-center gap-1.5 pt-1">
                                {STATUS_FILTERS.map((st) => (
                                    <button
                                        key={st}
                                        type="button"
                                        onClick={() => setStatusFilter(st)}
                                        className={`px-2.5 py-1 text-[11px] font-bold rounded-lg border transition cursor-pointer ${
                                            statusFilter === st
                                                ? 'bg-indigo-600 text-white border-indigo-600 shadow-2xs'
                                                : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'
                                        }`}
                                        data-testid={`filter-status-${st.toLowerCase()}`}
                                    >
                                        {st === 'ALL' ? 'All' : st}
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* Ticket Queue List */}
                        <div className="bg-white rounded-2xl border border-slate-200/80 shadow-2xs overflow-hidden">
                            <div className="px-4 py-3 border-b border-slate-100 bg-slate-50/70 flex items-center justify-between">
                                <span className="text-xs font-bold text-slate-700 uppercase tracking-wider">
                                    Your Tickets ({filteredTickets.length})
                                </span>
                            </div>

                            {isLoadingList ? (
                                <div className="p-8 text-center space-y-3">
                                    <div className="w-8 h-8 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin mx-auto"></div>
                                    <p className="text-xs text-slate-500 font-medium">Loading your support tickets...</p>
                                </div>
                            ) : filteredTickets.length === 0 ? (
                                <div className="p-8 text-center space-y-3" data-testid="empty-tickets-state">
                                    <div className="w-12 h-12 rounded-2xl bg-slate-100 text-slate-400 flex items-center justify-center mx-auto">
                                        <FiInbox className="w-6 h-6" />
                                    </div>
                                    <h3 className="text-sm font-bold text-slate-800">No support tickets found</h3>
                                    <p className="text-xs text-slate-500 max-w-xs mx-auto">
                                        {searchTerm || statusFilter !== 'ALL'
                                            ? 'No tickets match your filter criteria.'
                                            : 'Need help? Click "Raise New Ticket" above to reach our support team.'}
                                    </p>
                                    {!searchTerm && statusFilter === 'ALL' && (
                                        <button
                                            type="button"
                                            onClick={() => setIsCreateModalOpen(true)}
                                            className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-bold text-indigo-600 bg-indigo-50 hover:bg-indigo-100 rounded-lg transition cursor-pointer"
                                        >
                                            <FiPlus className="w-3.5 h-3.5" />
                                            <span>Create Ticket</span>
                                        </button>
                                    )}
                                </div>
                            ) : (
                                <div className="divide-y divide-slate-100 max-h-[600px] overflow-y-auto custom-scrollbar">
                                    {filteredTickets.map((t) => {
                                        const isSelected = selectedTicketId === t.id;
                                        return (
                                            <div
                                                key={t.id}
                                                onClick={() => setSelectedTicketId(t.id)}
                                                className={`p-4 transition cursor-pointer hover:bg-slate-50/80 ${
                                                    isSelected ? 'bg-indigo-50/60 border-l-4 border-indigo-600' : ''
                                                }`}
                                                data-testid={`ticket-item-${t.id}`}
                                            >
                                                <div className="flex items-start justify-between gap-2 mb-1.5">
                                                    <h4 className="text-xs sm:text-sm font-bold text-slate-900 line-clamp-1">
                                                        {t.subject}
                                                    </h4>
                                                    <span className={`px-2 py-0.5 text-[10px] font-extrabold rounded-full border shrink-0 ${getStatusPill(t.status)}`}>
                                                        {t.status}
                                                    </span>
                                                </div>

                                                <div className="flex flex-wrap items-center gap-2 text-[11px] text-slate-500">
                                                    <span className={`px-1.5 py-0.5 text-[9px] font-extrabold rounded-md border ${getPriorityPill(t.priority)}`}>
                                                        {t.priority}
                                                    </span>
                                                    <span className="flex items-center gap-1">
                                                        <FiClock className="w-3 h-3 text-slate-400" />
                                                        {formatDate(t.updatedAt || t.createdAt)}
                                                    </span>
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            )}
                        </div>
                    </div>

                    {/* RIGHT PANEL: Ticket Detail & Message Conversation */}
                    <div className={`${!selectedTicketId ? 'hidden lg:block' : 'block'} lg:col-span-7`}>
                        {selectedTicketId && ticketDetail ? (
                            <div className="bg-white rounded-2xl border border-slate-200/80 shadow-2xs overflow-hidden flex flex-col min-h-[600px]" data-testid="ticket-detail-view">
                                {/* Detail Header */}
                                <div className="p-5 border-b border-slate-100 bg-slate-50/50 flex flex-col gap-3">
                                    <div className="flex items-center justify-between gap-2">
                                        <button
                                            type="button"
                                            onClick={() => setSelectedTicketId(null)}
                                            className="lg:hidden inline-flex items-center gap-1 text-xs font-bold text-slate-600 hover:text-slate-900 cursor-pointer"
                                        >
                                            <FiArrowLeft className="w-4 h-4" /> Back to list
                                        </button>
                                        <div className="flex items-center gap-2 ml-auto">
                                            <span className={`px-2.5 py-1 text-[11px] font-extrabold rounded-full border ${getStatusPill(ticketDetail.status)}`}>
                                                Status: {ticketDetail.status}
                                            </span>
                                            <span className={`px-2.5 py-1 text-[11px] font-extrabold rounded-md border ${getPriorityPill(ticketDetail.priority)}`}>
                                                Priority: {ticketDetail.priority}
                                            </span>
                                        </div>
                                    </div>

                                    <div>
                                        <h2 className="text-lg font-bold text-slate-900" data-testid="ticket-detail-subject">
                                            {ticketDetail.subject}
                                        </h2>
                                        <p className="text-[11px] text-slate-400 mt-0.5">
                                            Ticket ID: <span className="font-mono text-slate-600">{ticketDetail.id}</span> • Opened: {formatDate(ticketDetail.createdAt)}
                                        </p>
                                    </div>
                                </div>

                                {/* Detail Error alert */}
                                {detailError && (
                                    <div role="alert" className="m-4 p-3 bg-rose-50 border border-rose-200 rounded-xl text-xs text-rose-800 flex items-center gap-2">
                                        <FiAlertCircle className="w-4 h-4 text-rose-600 shrink-0" />
                                        <span>{detailError}</span>
                                    </div>
                                )}

                                {/* Message Stream */}
                                <div className="flex-1 p-5 space-y-4 overflow-y-auto max-h-[440px] custom-scrollbar bg-slate-50/30" data-testid="ticket-messages-stream">
                                    {isLoadingDetail ? (
                                        <div className="p-8 text-center">
                                            <div className="w-6 h-6 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin mx-auto"></div>
                                            <p className="text-xs text-slate-400 mt-2">Loading conversation thread...</p>
                                        </div>
                                    ) : (ticketDetail.messages || []).map((msg, idx) => {
                                        const isStaff = msg.authorRole !== 'USER';
                                        return (
                                            <div
                                                key={msg.id || idx}
                                                className={`flex flex-col ${isStaff ? 'items-start' : 'items-end'}`}
                                                data-testid={`ticket-message-${msg.id || idx}`}
                                            >
                                                <div className="flex items-center gap-1.5 text-[10px] text-slate-400 mb-1 px-1">
                                                    {isStaff ? (
                                                        <span className="font-bold text-indigo-600 flex items-center gap-1">
                                                            <FiShield className="w-3 h-3" /> Support Specialist
                                                        </span>
                                                    ) : (
                                                        <span className="font-bold text-slate-700 flex items-center gap-1">
                                                            <FiUser className="w-3 h-3" /> You
                                                        </span>
                                                    )}
                                                    <span>• {formatDate(msg.createdAt)}</span>
                                                </div>

                                                <div
                                                    className={`max-w-[85%] rounded-2xl px-4 py-3 text-xs leading-relaxed ${
                                                        isStaff
                                                            ? 'bg-white border border-slate-200 text-slate-800 shadow-2xs rounded-tl-xs'
                                                            : 'bg-indigo-600 text-white shadow-2xs rounded-tr-xs'
                                                    }`}
                                                >
                                                    <p className="whitespace-pre-wrap">{msg.body}</p>
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>

                                {/* Reply Section */}
                                <div className="p-4 border-t border-slate-200 bg-white">
                                    {ticketDetail.status === 'CLOSED' ? (
                                        <div className="p-3 bg-slate-100 border border-slate-200 rounded-xl text-center text-xs text-slate-600">
                                            <FiCheckCircle className="w-4 h-4 text-emerald-600 inline-block mr-1.5" />
                                            This support ticket has been resolved and closed. If you require further assistance, please raise a new ticket.
                                        </div>
                                    ) : (
                                        <form onSubmit={handleSendReply} className="space-y-3" data-testid="ticket-reply-form">
                                            <textarea
                                                rows={3}
                                                placeholder="Write a reply or provide further details..."
                                                value={replyText}
                                                onChange={(e) => setReplyText(e.target.value)}
                                                className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs text-slate-800 placeholder-slate-400 focus:outline-hidden focus:bg-white focus:border-indigo-500 transition resize-none"
                                                data-testid="ticket-reply-input"
                                            />
                                            <div className="flex justify-end">
                                                <button
                                                    type="submit"
                                                    disabled={!replyText.trim() || isSubmittingReply}
                                                    className="inline-flex items-center gap-2 px-4 py-2 rounded-xl bg-indigo-600 text-white text-xs font-bold hover:bg-indigo-700 transition shadow-xs cursor-pointer disabled:opacity-50"
                                                    data-testid="ticket-reply-button"
                                                >
                                                    {isSubmittingReply ? (
                                                        <>
                                                            <div className="w-3 h-3 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                                                            <span>Sending...</span>
                                                        </>
                                                    ) : (
                                                        <>
                                                            <FiSend className="w-3.5 h-3.5" />
                                                            <span>Send Reply</span>
                                                        </>
                                                    )}
                                                </button>
                                            </div>
                                        </form>
                                    )}
                                </div>
                            </div>
                        ) : (
                            <div className="bg-white rounded-2xl border border-slate-200/80 shadow-2xs p-12 text-center min-h-[400px] flex flex-col items-center justify-center space-y-3">
                                <div className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center">
                                    <FiMessageSquare className="w-7 h-7" />
                                </div>
                                <h3 className="text-base font-bold text-slate-800">Select a Ticket</h3>
                                <p className="text-xs text-slate-500 max-w-sm">
                                    Choose a support ticket from the list to view the full message thread or send a reply.
                                </p>
                            </div>
                        )}
                    </div>
                </div>
                )}

                {/* ── CREATE TICKET MODAL ──────────────────────────────────────── */}
                {isCreateModalOpen && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xs" data-testid="create-ticket-modal">
                        <div className="bg-white rounded-2xl border border-slate-200 shadow-2xl max-w-lg w-full overflow-hidden animate-in fade-in zoom-in-95 duration-150">
                            <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/60">
                                <div className="flex items-center gap-2.5">
                                    <div className="w-8 h-8 rounded-xl bg-indigo-50 text-indigo-600 flex items-center justify-center font-bold">
                                        <FiPlus className="w-4 h-4" />
                                    </div>
                                    <h3 className="text-sm sm:text-base font-bold text-slate-900">
                                        Raise Support Ticket
                                    </h3>
                                </div>
                                <button
                                    type="button"
                                    onClick={() => !isCreatingTicket && setIsCreateModalOpen(false)}
                                    className="text-slate-400 hover:text-slate-600 p-1.5 rounded-lg hover:bg-slate-100 transition cursor-pointer"
                                    aria-label="Close modal"
                                >
                                    <FiX className="w-5 h-5" />
                                </button>
                            </div>

                            <form onSubmit={handleCreateTicket} className="p-6 space-y-4">
                                {createError && (
                                    <div role="alert" className="p-3 bg-rose-50 border border-rose-200 rounded-xl text-xs text-rose-800 flex items-center gap-2">
                                        <FiAlertCircle className="w-4 h-4 text-rose-600 shrink-0" />
                                        <span>{createError}</span>
                                    </div>
                                )}

                                <div className="space-y-1.5">
                                    <label htmlFor="ticket-subject" className="block text-xs font-bold text-slate-700">
                                        Subject <span className="text-rose-500">*</span>
                                    </label>
                                    <input
                                        id="ticket-subject"
                                        type="text"
                                        placeholder="Brief summary of your question or issue"
                                        value={newSubject}
                                        onChange={(e) => setNewSubject(e.target.value)}
                                        className="w-full px-3.5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs text-slate-900 focus:outline-hidden focus:bg-white focus:border-indigo-500 transition"
                                        data-testid="ticket-subject-input"
                                        required
                                    />
                                </div>

                                <div className="space-y-1.5">
                                    <label htmlFor="ticket-priority" className="block text-xs font-bold text-slate-700">
                                        Priority / Category
                                    </label>
                                    <select
                                        id="ticket-priority"
                                        value={newPriority}
                                        onChange={(e) => setNewPriority(e.target.value)}
                                        className="w-full px-3.5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs text-slate-900 focus:outline-hidden focus:bg-white focus:border-indigo-500 transition cursor-pointer"
                                        data-testid="ticket-priority-select"
                                    >
                                        {PRIORITIES.map((p) => (
                                            <option key={p.value} value={p.value}>
                                                {p.label}
                                            </option>
                                        ))}
                                    </select>
                                </div>

                                <div className="space-y-1.5">
                                    <label htmlFor="ticket-body" className="block text-xs font-bold text-slate-700">
                                        Description / Details <span className="text-rose-500">*</span>
                                    </label>
                                    <textarea
                                        id="ticket-body"
                                        rows={4}
                                        placeholder="Please provide complete context, steps taken, or specific error messages so we can assist you quickly..."
                                        value={newBody}
                                        onChange={(e) => setNewBody(e.target.value)}
                                        className="w-full p-3.5 bg-slate-50 border border-slate-200 rounded-xl text-xs text-slate-900 focus:outline-hidden focus:bg-white focus:border-indigo-500 transition resize-none"
                                        data-testid="ticket-body-input"
                                        required
                                    />
                                </div>

                                <div className="pt-3 flex items-center justify-end gap-2.5 border-t border-slate-100">
                                    <button
                                        type="button"
                                        onClick={() => setIsCreateModalOpen(false)}
                                        disabled={isCreatingTicket}
                                        className="px-4 py-2 rounded-xl border border-slate-200 text-xs font-bold text-slate-600 hover:bg-slate-50 transition cursor-pointer"
                                    >
                                        Cancel
                                    </button>
                                    <button
                                        type="submit"
                                        disabled={isCreatingTicket || !newSubject.trim() || !newBody.trim()}
                                        className="inline-flex items-center gap-2 px-5 py-2 rounded-xl bg-indigo-600 text-white text-xs font-bold hover:bg-indigo-700 transition shadow-sm cursor-pointer disabled:opacity-50"
                                        data-testid="ticket-submit-button"
                                    >
                                        {isCreatingTicket ? (
                                            <>
                                                <div className="w-3.5 h-3.5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                                                <span>Submitting...</span>
                                            </>
                                        ) : (
                                            <>
                                                <FiSend className="w-3.5 h-3.5" />
                                                <span>Submit Ticket</span>
                                            </>
                                        )}
                                    </button>
                                </div>
                            </form>
                        </div>
                    </div>
                )}

            </div>
        </div>
    );
}

import React, { useState, useEffect, useContext, useRef } from 'react';
import { motion } from 'framer-motion';
import { withTranslation } from 'react-i18next';
import { FaBriefcase, FaSearch, FaFilter, FaCalendar, FaMapMarkerAlt, FaDollarSign, FaEye, FaClock, FaCheckCircle, FaTimesCircle, FaHourglass, FaInfoCircle, FaSortAmountDown, FaBuilding, FaPlus, FaEdit, FaTrash, FaUsers, FaChartBar, FaFileAlt, FaExclamationTriangle, FaChevronDown, FaChevronUp } from 'react-icons/fa';
import { getEmployerJobs, getJobApplications, updateJobPosting, deleteJobPosting } from '../../../services/api/platform';
import { AuthContext } from '../../../context/AuthContext';
import { formatSafeDate } from '../../../utils/subscriptionUtils.js';
import JobApplicationsModal from './JobApplicationsModal';
import AddCompanyModal from './AddCompanyModal';
import EditJobModal from './EditJobModal';

// eslint-disable-next-line react-refresh/only-export-components
const EmployerDashboard = ({ showToast, _sidebarCollapsed, t }) => {
    const user = useContext(AuthContext);
    const [jobs, setJobs] = useState([]);
    const [filteredJobs, setFilteredJobs] = useState([]);
    const [searchTerm, setSearchTerm] = useState('');
    const [statusFilter, setStatusFilter] = useState('all');
    const [sortBy, setSortBy] = useState('date');
    const [loading, setLoading] = useState(true);
    const [selectedJob, setSelectedJob] = useState(null);
    const [applications, setApplications] = useState([]);
    const [loadingApplications, setLoadingApplications] = useState(false);
    // Monotonic request token. Opening the ATS modal is asynchronous (the applicant
    // list is fetched), so without this a slow response for a previously-clicked
    // requisition can resolve AFTER a newer one and overwrite the visible pipeline.
    const applicationsRequestRef = useRef(0);
    const [expandedJob, setExpandedJob] = useState(null);
    const [showApplicationsModal, setShowApplicationsModal] = useState(false);
    const [showAddCompanyModal, setShowAddCompanyModal] = useState(false);
    const [showEditJobModal, setShowEditJobModal] = useState(false);
    const [selectedJobForEdit, setSelectedJobForEdit] = useState(null);

    // Real data is now loaded from Firebase via getEmployerJobs and getJobApplications

    useEffect(() => {
        loadJobs();
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    useEffect(() => {
        filterAndSortJobs();
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [jobs, searchTerm, statusFilter, sortBy]);

    const loadJobs = async () => {
        if (!user?.uid) {
            setLoading(false);
            return;
        }

        setLoading(true);
        try {


            const employerJobs = await getEmployerJobs(user.uid);


            if (employerJobs && employerJobs.length > 0) {
                // Transform the data to match the expected format
                const transformedJobs = employerJobs.map((job) => {
                    return {
                        ...job,
                        id: job.id,
                        title: job.title || 'Untitled Job',
                        company: job.company || 'Your Company',
                        location: job.location || 'Location not specified',
                        salary: formatSalaryDisplay(job.minSalary, job.maxSalary),
                        postedDate: job.createdAt ? formatDate(job.createdAt) : null,
                        status: job.status || 'unknown',
                        statusColor: getStatusColor(job.status),
                        jobType: job.jobType || 'Full-time',
                        workMode: job.workMode || 'On-site',
                        description: job.description || 'No description provided',
                        requirements: job.requirements || [],
                        applicationsCount: job.applicationsCount || 0,
                        viewsCount: job.viewsCount || 0,
                        deadline: job.deadline ? formatDate(job.deadline) : null,
                    };
                });

                setJobs(transformedJobs);
            } else {
                setJobs([]);
            }
        } catch (error) {
            console.error('Error loading employer jobs:', error.message);
            showToast && showToast('error', 'Error', 'Failed to load jobs');
            setJobs([]);
        } finally {
            setLoading(false);
        }
    };

    const filterAndSortJobs = () => {
        let filtered = [...jobs];

        // Filter by search term
        if (searchTerm) {
            const searchLower = searchTerm.toLowerCase();
            filtered = filtered.filter(
                (job) => job.title.toLowerCase().includes(searchLower) || job.location.toLowerCase().includes(searchLower) || job.requirements.some((req) => req.toLowerCase().includes(searchLower))
            );
        }

        // Filter by status
        if (statusFilter !== 'all') {
            filtered = filtered.filter((job) => job.status === statusFilter);
        }

        // Sort jobs
        filtered.sort((a, b) => {
            switch (sortBy) {
                case 'date':
                    return new Date(b.postedDate) - new Date(a.postedDate);
                case 'applications':
                    return b.applicationsCount - a.applicationsCount;
                case 'views':
                    return b.viewsCount - a.viewsCount;
                case 'title':
                    return a.title.localeCompare(b.title);
                default:
                    return 0;
            }
        });

        setFilteredJobs(filtered);
    };

    const loadApplications = async (jobId) => {
        const requestId = ++applicationsRequestRef.current;
        setLoadingApplications(true);
        try {
            const jobApplications = await getJobApplications(jobId);

            // Stale response: a newer requisition was opened while this fetch was in
            // flight. Discard it rather than painting the wrong applicant pipeline
            // into the modal (DIR-010 §2 in-modal review correctness).
            if (requestId !== applicationsRequestRef.current) return;

       
            if (jobApplications && jobApplications.length > 0) {
                // Transform the data to match the expected format
                const transformedApplications = jobApplications.map((app) => {
                    return {
                        id: app.id,
                        jobId: app.jobId,
                        applicantName: app.applicantName || app.fullName || 'Unknown Applicant',
                        applicantEmail: app.applicantEmail || app.email || 'No email provided',
                        appliedDate: app.appliedAt ? formatDate(app.appliedAt) : formatDate(app.createdAt),
                        status: app.status || 'pending',
                        statusColor: getApplicationStatusColor(app.status),
                        resume: app.resumeUrl || app.selectedResume?.id || 'No resume',
                        coverLetter: app.coverLetter || 'No cover letter provided',
                        experience: app.experience || 'Not specified',
                        skills: app.skills || [],
                        // Include all original data
                        ...app,
                    };
                });

                setApplications(transformedApplications);
            } else {
                setApplications([]);
            }
        } catch (error) {
            console.error('❌ EmployerDashboard: Error loading applications:', error);
            showToast && showToast('error', 'Error', 'Failed to load applications');
            setApplications([]);
        } finally {
            // Only the newest request may clear the loading flag; a stale one
            // settling here would switch off the spinner for a fetch still running.
            if (requestId === applicationsRequestRef.current) setLoadingApplications(false);
        }
    };

    const handleJobClick = (job) => {
        setSelectedJob(job);
        // Clear the previous requisition's applicants synchronously BEFORE the new
        // fetch starts. The modal opens on the same tick as this call, so any
        // retained rows would render as the new job's pipeline for a frame.
        setApplications([]);
        loadApplications(job.id);
        setShowApplicationsModal(true);
    };

    const handleCloseModal = () => {
        setShowApplicationsModal(false);
        setSelectedJob(null);
        setApplications([]);
    };

    const handleUpdateApplicationStatus = (applicationId, newStatus, revision) => {
        setApplications(previous => previous.map(application => application.id === applicationId
            ? { ...application, status: newStatus, revision }
            : application));
    };

    const toggleJobExpansion = (jobId) => {
        setExpandedJob(expandedJob === jobId ? null : jobId);
    };

    // Handle edit job
    const handleEditJob = (job) => {
        setSelectedJobForEdit(job);
        setShowEditJobModal(true);
    };

    // Handle job updated from edit modal
    const handleJobUpdated = (updatedJob) => {
        setJobs((prevJobs) => 
            prevJobs.map((job) => 
                job.id === updatedJob.id 
                    ? { ...job, ...updatedJob, salary: formatSalaryDisplay(updatedJob.minSalary, updatedJob.maxSalary) }
                    : job
            )
        );
        showToast('success', 'Success', 'Job updated successfully!');
    };

    // Handle deactivate/activate job
    const handleToggleJobStatus = async (job) => {
        try {
            const newStatus = job.status === 'active' ? 'paused' : 'active';
            
            const result = await updateJobPosting(job.id, { status: newStatus }, job.revision);
            
            if (result.success) {
                setJobs((prevJobs) => 
                    prevJobs.map((j) => 
                        j.id === job.id 
                            ? { ...j, status: result.status, revision: result.revision, statusColor: getStatusColor(result.status) }
                            : j
                    )
                );
                showToast('success', 'Success', `Job ${newStatus === 'active' ? 'activated' : 'paused'} successfully`);
            } else {
                throw new Error(result.error || 'Failed to update job status');
            }
        } catch (error) {
            console.error('Error updating job status:', error);
            showToast('error', 'Error', `Failed to ${job.status === 'active' ? 'pause' : 'activate'} job: ${error.message}`);
        }
    };

    const [deleteJobModal, setDeleteJobModal] = useState({ isOpen: false, job: null });

    // Handle delete job
    const handleDeleteJob = (job) => {
        setDeleteJobModal({ isOpen: true, job });
    };

    const confirmDeleteJob = async () => {
        const job = deleteJobModal.job;
        if (!job) return;
        
        try {
            const result = await deleteJobPosting(job.id, job.revision);
            
            if (result.success) {
                setJobs((prevJobs) => prevJobs.filter((j) => j.id !== job.id));
                showToast('success', 'Success', 'Job deleted successfully');
                if (expandedJob === job.id) {
                    setExpandedJob(null);
                }
            } else {
                throw new Error(result.error || 'Failed to delete job');
            }
        } catch (error) {
            console.error('Error deleting job:', error);
            showToast('error', 'Error', `Failed to delete job: ${error.message}`);
        } finally {
            setDeleteJobModal({ isOpen: false, job: null });
        }
    };

    // Handle close edit modal
    const handleCloseEditModal = () => {
        setShowEditJobModal(false);
        setSelectedJobForEdit(null);
    };

    const getStatusBadge = (status) => {
        // Canonical Cuba status pills (DIR-010 §2). Tones resolve to the opaque
        // .cuba-pill-* tokens, which are the only approved way to express ATS
        // stage status: their fill/ink pairs are contrast-verified to WCAG 2.1
        // AA in both themes, so no component may re-invent a bg-*/text-* pair.
        const statusConfig = {
            active: { tone: 'cuba-pill-success', icon: FaCheckCircle, label: 'Active' },
            pending: { tone: 'cuba-pill-warning', icon: FaClock, label: 'Pending Approval' },
            paused: { tone: 'cuba-pill-neutral', icon: FaHourglass, label: 'Paused' },
            closed: { tone: 'cuba-pill-neutral', icon: FaTimesCircle, label: 'Closed' },
            draft: { tone: 'cuba-pill-neutral', icon: FaFileAlt, label: 'Draft' },
        };

        const config = statusConfig[status] || statusConfig.pending; // Default to pending instead of active
        const IconComponent = config.icon;

        return (
            <span className={`${config.tone} px-2.5 py-1 text-xs font-bold`}>
                <IconComponent className="w-2.5 h-2.5 mr-1" aria-hidden="true" />
                {config.label}
            </span>
        );
    };

    const getApplicationStatusBadge = (status) => {
        const statusConfig = {
            pending: { bg: 'bg-yellow-100', text: 'text-yellow-700', icon: FaClock, label: 'Pending' },
            interview: { bg: 'bg-blue-100', text: 'text-blue-700', icon: FaUsers, label: 'Interview' },
            accepted: { bg: 'bg-emerald-100', text: 'text-emerald-700', icon: FaCheckCircle, label: 'Accepted' },
            rejected: { bg: 'bg-red-100', text: 'text-red-700', icon: FaTimesCircle, label: 'Rejected' },
        };

        const config = statusConfig[status] || statusConfig.pending;
        const IconComponent = config.icon;

        return (
            <span className={`inline-flex items-center px-2 py-1 rounded-md text-xs font-medium ${config.bg} ${config.text}`}>
                <IconComponent className="w-3 h-3 mr-1" />
                {config.label}
            </span>
        );
    };

    // Helper function to format salary display with default Rupee symbol
    const formatSalaryDisplay = (minSalary, maxSalary, currencySymbol = '₹') => {
        if (!minSalary && !maxSalary) return 'Salary not specified';
        const sym = currencySymbol || '₹';
        if (minSalary && maxSalary) {
            return `${sym}${(minSalary / 1000).toFixed(0)}k - ${sym}${(maxSalary / 1000).toFixed(0)}k`;
        }
        if (minSalary) return `${sym}${(minSalary / 1000).toFixed(0)}k+`;
        if (maxSalary) return `Up to ${sym}${(maxSalary / 1000).toFixed(0)}k`;
        return 'Salary not specified';
    };

    // Helper function to get status color
    const getStatusColor = (status) => {
        const statusColors = {
            active: 'green',
            pending: 'yellow',
            paused: 'gray',
            closed: 'red',
            draft: 'gray',
        };
        return statusColors[status] || 'yellow'; // Default to yellow (pending) instead of green
    };

    // Helper function to get application status color
    const getApplicationStatusColor = (status) => {
        const statusColors = {
            pending: 'yellow',
            interview: 'blue',
            accepted: 'green',
            rejected: 'red',
        };
        return statusColors[status] || 'yellow';
    };

    const formatDate = (dateInput) => {
        const formatted = formatSafeDate(dateInput, 'en-US', { year: 'numeric', month: 'short', day: 'numeric' });
        return formatted || (dateInput ? 'Invalid date' : 'Date not specified');
    };

    if (loading) {
        return (
            <div className="min-h-screen bg-slate-50">
                <div className="mx-auto px-3 sm:px-4 lg:px-6 xl:px-8 py-3 sm:py-4">
                    <div className="flex items-center justify-center h-64">
                        <div className="text-center">
                            <div className="animate-spin rounded-full h-10 w-10 border-2 border-slate-200 border-t-slate-600 mx-auto mb-3"></div>
                            <p className="text-slate-600 text-sm font-medium">{t('JobsUpdate.EmployerDashboard.loading', 'Loading your job postings...')}</p>
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    return (
            <div className="min-h-screen bg-slate-50">
                <div className="mx-auto px-3 sm:px-4 lg:px-6 xl:px-8 py-3 sm:py-4">
                {/* Header */}
                <div className="mb-4 sm:mb-6">
                    <div className="flex flex-col space-y-4 sm:space-y-0 sm:flex-row sm:items-center sm:justify-between">
                        <div className="flex items-center space-x-3 flex-1 min-w-0">
                            <div className="p-2 bg-slate-100 rounded-lg">
                                <FaBriefcase className="w-5 h-5 text-slate-600" />
                            </div>
                            <div className="flex-1 min-w-0">
                                <h1 className="text-xl font-semibold text-slate-900 tracking-tight truncate">{t('JobsUpdate.EmployerDashboard.header.title', 'Job Postings')}</h1>
                                <p className="text-slate-600 text-sm mt-0.5">{t('JobsUpdate.EmployerDashboard.header.subtitle', 'Manage your job postings and review applications')}</p>
                            </div>
                        </div>
                        <div className="flex space-x-3">
                            <button 
                                className="bg-slate-700 hover:bg-slate-600 text-white px-4 py-2.5 rounded-md flex items-center gap-2 transition-colors text-sm font-medium shadow-sm"
                                onClick={() => setShowAddCompanyModal(true)}
                            >
                                <FaBuilding className="w-3.5 h-3.5" />
                                <span className="hidden sm:inline">{t('JobsUpdate.EmployerDashboard.buttons.addCompany', 'Add Company')}</span>
                                <span className="sm:hidden">{t('JobsUpdate.EmployerDashboard.buttons.company', 'Company')}</span>
                            </button>
                            <button className="bg-slate-900 hover:bg-slate-800 text-white px-4 py-2.5 rounded-md flex items-center gap-2 transition-colors text-sm font-medium shadow-sm">
                                <FaPlus className="w-3.5 h-3.5" />
                                <span className="hidden sm:inline">{t('JobsUpdate.EmployerDashboard.buttons.postNewJob', 'Post New Job')}</span>
                                <span className="sm:hidden">{t('JobsUpdate.EmployerDashboard.buttons.newJob', 'New Job')}</span>
                            </button>
                        </div>
                    </div>
                </div>

                {/* Stats Cards */}
                <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4 mb-6">
                    <div className="bg-white rounded-lg p-4 border border-slate-200 shadow-sm">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-xs font-medium text-slate-500 uppercase tracking-wide">{t('JobsUpdate.EmployerDashboard.stats.totalJobs', 'Total Jobs')}</p>
                                <p className="text-xl font-semibold text-slate-900 mt-1">{jobs.length}</p>
                            </div>
                            <div className="p-2 bg-slate-100 rounded-md">
                                <FaBriefcase className="w-4 h-4 text-slate-600" />
                            </div>
                        </div>
                    </div>

                    <div className="bg-white rounded-lg p-4 border border-slate-200 shadow-sm">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-xs font-medium text-slate-500 uppercase tracking-wide">{t('JobsUpdate.EmployerDashboard.stats.active', 'Active')}</p>
                                <p className="text-xl font-semibold text-slate-900 mt-1">{jobs.filter((job) => job.status === 'active').length}</p>
                            </div>
                            <div className="p-2 bg-emerald-50 rounded-md">
                                <FaCheckCircle className="w-4 h-4 text-emerald-600" />
                            </div>
                        </div>
                    </div>

                    <div className="bg-white rounded-lg p-4 border border-slate-200 shadow-sm">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-xs font-medium text-slate-500 uppercase tracking-wide">{t('JobsUpdate.EmployerDashboard.stats.applications', 'Applications')}</p>
                                <p className="text-xl font-semibold text-slate-900 mt-1">{jobs.reduce((sum, job) => sum + job.applicationsCount, 0)}</p>
                            </div>
                            <div className="p-2 bg-blue-50 rounded-md">
                                <FaUsers className="w-4 h-4 text-blue-600" />
                            </div>
                        </div>
                    </div>

                    <div className="bg-white rounded-lg p-4 border border-slate-200 shadow-sm">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-xs font-medium text-slate-500 uppercase tracking-wide">{t('JobsUpdate.EmployerDashboard.stats.views', 'Views')}</p>
                                <p className="text-xl font-semibold text-slate-900 mt-1">{jobs.reduce((sum, job) => sum + job.viewsCount, 0)}</p>
                            </div>
                            <div className="p-2 bg-slate-100 rounded-md">
                                <FaEye className="w-4 h-4 text-slate-600" />
                            </div>
                        </div>
                    </div>
                </div>

                {/* Search and Filters */}
                <div className="bg-white rounded-lg p-4 border border-slate-200 shadow-sm mb-6">
                    <div className="flex flex-col sm:flex-row gap-3">
                        {/* Search */}
                        <div className="flex-1">
                            <div className="relative">
                                <FaSearch className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400 w-3.5 h-3.5" />
                                <input
                                    type="text"
                                    placeholder={t('JobsUpdate.EmployerDashboard.search.placeholder', 'Search jobs by title, location...')}
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                    className="w-full pl-9 pr-3 py-2.5 text-sm border border-slate-300 rounded-md focus:outline-none focus:ring-1 focus:ring-slate-400 focus:border-slate-400 placeholder-slate-400"
                                />
                            </div>
                        </div>

                        {/* Status Filter */}
                        <div className="sm:w-40">
                            <select
                                value={statusFilter}
                                onChange={(e) => setStatusFilter(e.target.value)}
                                className="w-full px-3 py-2.5 text-sm border border-slate-300 rounded-md focus:outline-none focus:ring-1 focus:ring-slate-400 focus:border-slate-400 bg-white">
                                <option value="all">{t('JobsUpdate.EmployerDashboard.filters.allStatus', 'All Status')}</option>
                                <option value="active">{t('JobsUpdate.EmployerDashboard.filters.active', 'Active')}</option>
                                <option value="pending">{t('JobsUpdate.EmployerDashboard.filters.pending', 'Pending Approval')}</option>
                                <option value="paused">{t('JobsUpdate.EmployerDashboard.filters.paused', 'Paused')}</option>
                                <option value="closed">{t('JobsUpdate.EmployerDashboard.filters.closed', 'Closed')}</option>
                                <option value="draft">{t('JobsUpdate.EmployerDashboard.filters.draft', 'Draft')}</option>
                            </select>
                        </div>

                        {/* Sort By */}
                        <div className="sm:w-44">
                            <select
                                value={sortBy}
                                onChange={(e) => setSortBy(e.target.value)}
                                className="w-full px-3 py-2.5 text-sm border border-slate-300 rounded-md focus:outline-none focus:ring-1 focus:ring-slate-400 focus:border-slate-400 bg-white">
                                <option value="date">{t('JobsUpdate.EmployerDashboard.sort.byDate', 'Sort by Date')}</option>
                                <option value="applications">{t('JobsUpdate.EmployerDashboard.sort.byApplications', 'Applications')}</option>
                                <option value="views">{t('JobsUpdate.EmployerDashboard.sort.byViews', 'Views')}</option>
                                <option value="title">{t('JobsUpdate.EmployerDashboard.sort.byTitle', 'Title')}</option>
                            </select>
                        </div>
                    </div>
                </div>

                {/* Jobs List */}
                {filteredJobs.length === 0 ? (
                    <div className="bg-white rounded-lg p-8 border border-slate-200 text-center">
                        <FaBriefcase className="w-10 h-10 text-slate-400 mx-auto mb-3" />
                        <h3 className="text-lg font-medium text-slate-900 mb-2">{t('JobsUpdate.EmployerDashboard.emptyState.title', 'No job postings found')}</h3>
                        <p className="text-slate-600 text-sm mb-4 max-w-md mx-auto">
                            {jobs.length === 0
                                ? t('JobsUpdate.EmployerDashboard.emptyState.noJobs', "You haven't posted any jobs yet. Create your first job posting to get started!")
                                : t('JobsUpdate.EmployerDashboard.emptyState.noResults', 'No jobs match your current filters. Try adjusting your search criteria.')}
                        </p>
                        <button className="bg-slate-900 hover:bg-slate-800 text-white px-5 py-2.5 rounded-md flex items-center gap-2 mx-auto transition-colors text-sm font-medium">
                            <FaPlus className="w-3.5 h-3.5" />
                            {t('JobsUpdate.EmployerDashboard.buttons.postFirstJob', 'Post Your First Job')}
                        </button>
                    </div>
                ) : (
                    <div className="space-y-3">
                        {filteredJobs.map((job) => (
                            <motion.div
                                key={job.id}
                                // Stable per-row anchor for the DIR-010 E2E suite. The ATS
                                // applications modal is opened from THIS row's CTA, and the
                                // suite must target the requisition that actually holds
                                // applicant rows in MariaDB — a positional `openers.first()`
                                // silently opened job-air-12 (0 applications) and made the
                                // in-modal review stage assert against an empty pipeline.
                                // Naming convention matches data-template-id in
                                // src/components/BuildResume; it is inert to CSS and to a11y.
                                data-job-id={job.id}
                                initial={{ opacity: 0, y: 10 }}
                                animate={{ opacity: 1, y: 0 }}
                                className="bg-white rounded-lg border border-slate-200 overflow-hidden hover:border-slate-300 transition-all duration-200">
                                <div className="p-4">
                                    <div className="flex items-start justify-between">
                                        <div className="flex-1 min-w-0">
                                            <div className="flex items-center gap-2 mb-2">
                                                <h3 className="text-sm font-medium text-slate-900 truncate">{job.title}</h3>
                                                {getStatusBadge(job.status)}
                                            </div>

                                            <div className="flex flex-wrap items-center gap-3 text-xs text-slate-600 mb-3">
                                                <div className="flex items-center gap-1">
                                                    <FaMapMarkerAlt className="w-3 h-3" />
                                                    <span>{job.location}</span>
                                                </div>
                                                <div className="flex items-center gap-1">
                                                    <FaDollarSign className="w-3 h-3" />
                                                    <span>{job.salary}</span>
                                                </div>
                                                <div className="flex items-center gap-1">
                                                    <FaClock className="w-3 h-3" />
                                                    <span>
                                                        {job.jobType} • {job.workMode}
                                                    </span>
                                                </div>
                                                <div className="flex items-center gap-1">
                                                    <FaCalendar className="w-3 h-3" />
                                                    <span>Posted {formatDate(job.postedDate)}</span>
                                                </div>
                                            </div>

                                            <div className="flex items-center gap-4 text-xs">
                                                <div className="flex items-center gap-1">
                                                    <FaUsers className="w-3 h-3 text-slate-500" />
                                                    <span className="font-medium text-slate-900">{job.applicationsCount}</span>
                                                    <span className="text-slate-500">{t('JobsUpdate.EmployerDashboard.jobInfo.applications', 'applications')}</span>
                                                </div>
                                                <div className="flex items-center gap-1">
                                                    <FaEye className="w-3 h-3 text-slate-500" />
                                                    <span className="font-medium text-slate-900">{job.viewsCount}</span>
                                                    <span className="text-slate-500">{t('JobsUpdate.EmployerDashboard.jobInfo.views', 'views')}</span>
                                                </div>
                                                {job.deadline && (
                                                    <div className="flex items-center gap-1">
                                                        <FaCalendar className="w-3 h-3 text-slate-500" />
                                                        <span className="text-slate-500">{t('JobsUpdate.EmployerDashboard.jobInfo.deadline', 'Deadline:')}</span>
                                                        <span className="font-medium text-slate-900">{formatDate(job.deadline)}</span>
                                                    </div>
                                                )}
                                            </div>
                                        </div>

                                        <div className="flex items-center gap-2 ml-3 flex-shrink-0">
                                            <button
                                                onClick={() => handleJobClick(job)}
                                                className="bg-slate-900 hover:bg-slate-800 text-white px-3 py-2 rounded-md text-xs font-medium flex items-center gap-1.5 transition-colors">
                                                <FaUsers className="w-3 h-3" />
                                                <span className="hidden sm:inline">{t('JobsUpdate.EmployerDashboard.buttons.applications', 'Applications')}</span>
                                                <span className="sm:hidden">{job.applicationsCount}</span>
                                            </button>
                                            <button onClick={() => toggleJobExpansion(job.id)} className="p-2 text-slate-400 hover:text-slate-600 transition-colors rounded-md hover:bg-slate-50">
                                                {expandedJob === job.id ? <FaChevronUp className="w-3 h-3" /> : <FaChevronDown className="w-3 h-3" />}
                                            </button>
                                        </div>
                                    </div>

                                    {/* Expanded Job Details */}
                                    {expandedJob === job.id && (
                                        <motion.div
                                            initial={{ opacity: 0, height: 0 }}
                                            animate={{ opacity: 1, height: 'auto' }}
                                            exit={{ opacity: 0, height: 0 }}
                                            className="mt-3 pt-3 border-t border-slate-200">
                                            <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
                                                <div className="lg:col-span-2">
                                                    <h4 className="text-sm font-medium text-slate-900 mb-2">{t('JobsUpdate.EmployerDashboard.jobDetails.description', 'Job Description')}</h4>
                                                    <p className="text-slate-600 text-xs leading-relaxed mb-3 line-clamp-3">{job.description}</p>

                                                    <h4 className="text-sm font-medium text-slate-900 mb-2">{t('JobsUpdate.EmployerDashboard.jobDetails.requirements', 'Requirements')}</h4>
                                                    <div className="flex flex-wrap gap-1.5">
                                                        {job.requirements.slice(0, 6).map((req, index) => (
                                                            <span key={index} className="px-2 py-1 bg-slate-100 text-slate-700 rounded text-xs font-medium">
                                                                {req}
                                                            </span>
                                                        ))}
                                                        {job.requirements.length > 6 && (
                                                            <span className="px-2 py-1 bg-slate-100 text-slate-500 rounded text-xs">{t('JobsUpdate.EmployerDashboard.jobDetails.moreRequirements', '+{{count}} more', { count: job.requirements.length - 6 })}</span>
                                                        )}
                                                    </div>
                                                </div>

                                                <div className="flex flex-col gap-2">
                                                    <button 
                                                        onClick={() => handleEditJob(job)}
                                                        className="flex items-center gap-2 px-3 py-2 bg-slate-50 text-slate-700 rounded-md hover:bg-slate-100 transition-colors text-xs font-medium border border-slate-200"
                                                    >
                                                        <FaEdit className="w-3 h-3" />
                                                        {t('JobsUpdate.EmployerDashboard.buttons.editJob', 'Edit Job')}
                                                    </button>
                                                    <button 
                                                        onClick={() => handleToggleJobStatus(job)}
                                                        className="flex items-center gap-2 px-3 py-2 bg-slate-50 text-slate-700 rounded-md hover:bg-slate-100 transition-colors text-xs font-medium border border-slate-200"
                                                    >
                                                        <FaHourglass className="w-3 h-3" />
                                                        {job.status === 'active' ? t('JobsUpdate.EmployerDashboard.buttons.pause', 'Pause') : t('JobsUpdate.EmployerDashboard.buttons.activate', 'Activate')}
                                                    </button>
                                                    <button 
                                                        onClick={() => handleDeleteJob(job)}
                                                        className="flex items-center gap-2 px-3 py-2 bg-red-50 text-red-700 rounded-md hover:bg-red-100 transition-colors text-xs font-medium border border-red-200"
                                                    >
                                                        <FaTrash className="w-3 h-3" />
                                                        {t('JobsUpdate.EmployerDashboard.buttons.delete', 'Delete')}
                                                    </button>
                                                </div>
                                            </div>
                                        </motion.div>
                                    )}
                                </div>
                            </motion.div>
                        ))}
                    </div>
                )}

                {/* Job Applications Modal */}
                <JobApplicationsModal
                    isOpen={showApplicationsModal}
                    onClose={handleCloseModal}
                    job={selectedJob}
                    applications={applications}
                    isLoadingApplications={loadingApplications}
                    onUpdateStatus={handleUpdateApplicationStatus}
                    showToast={showToast}
                />

                {/* Add Company Modal */}
                <AddCompanyModal
                    isOpen={showAddCompanyModal}
                    onClose={() => setShowAddCompanyModal(false)}
                    showToast={showToast}
                />

                {/* Edit Job Modal */}
                <EditJobModal
                    isOpen={showEditJobModal}
                    onClose={handleCloseEditModal}
                    job={selectedJobForEdit}
                    onJobUpdated={handleJobUpdated}
                    showToast={showToast}
                />

                {/* In-App Delete Job Confirmation Modal with ESC key handling */}
                {deleteJobModal.isOpen && deleteJobModal.job && (
                    <div
                        className="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-xs flex items-center justify-center p-4"
                        role="presentation"
                        onKeyDown={(e) => { if (e.key === 'Escape') setDeleteJobModal({ isOpen: false, job: null }); }}>
                        <div
                            role="alertdialog"
                            aria-modal="true"
                            aria-labelledby="delete-job-title"
                            className="bg-white rounded-2xl max-w-md w-full p-6 shadow-xl space-y-4 border border-slate-200">
                            <h3 id="delete-job-title" className="text-base font-bold text-slate-900">
                                Confirm Job Deletion
                            </h3>
                            <p className="text-xs text-slate-600 leading-relaxed">
                                Delete the job <strong>"{deleteJobModal.job.title}"</strong>? This is allowed only when it has no applications and cannot be undone.
                            </p>
                            <div className="flex items-center justify-end gap-2 pt-2">
                                <button
                                    type="button"
                                    autoFocus
                                    onClick={() => setDeleteJobModal({ isOpen: false, job: null })}
                                    className="px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs rounded-xl cursor-pointer">
                                    Cancel
                                </button>
                                <button
                                    type="button"
                                    onClick={confirmDeleteJob}
                                    className="px-4 py-2 bg-red-600 hover:bg-red-700 text-white font-bold text-xs rounded-xl shadow-xs cursor-pointer">
                                    Delete Job
                                </button>
                            </div>
                        </div>
                    </div>
                )}
                </div>
            </div>
    );
};

// eslint-disable-next-line react-refresh/only-export-components
export default withTranslation('common')(EmployerDashboard);

import React, { useState, useEffect, useContext } from 'react';
import { useTranslation } from 'react-i18next';
import { FiGrid, FiSettings, FiFileText, FiBarChart, FiMousePointer, FiDownload, FiSearch, FiChevronLeft, FiChevronRight, FiChevronDown, FiSun, FiMoon, FiSidebar, FiX, FiUser, FiShield, FiLogOut, FiBell, FiMenu, FiMessageSquare, FiLifeBuoy } from 'react-icons/fi';
import { GoSidebarCollapse, GoSidebarExpand } from 'react-icons/go';
import { FaRegComments, FaBriefcase, FaCrown } from 'react-icons/fa';
import logo from '../../../assets/logo/logo.png';
import userPlaceholder from '../../../assets/user.png';
import { Link, useLocation } from 'react-router-dom';
import { checkIsEmployer, getSystemSettings } from '../../../services/api/platform';
import { AuthContext } from '../../../context/AuthContext';
import signOutUser from '../../../utils/signOut';
import NotificationPanel from './NotificationPanel';
import { useUnreadMessages } from '../../../hooks/useUnreadMessages';
import { useUnreadNotifications } from '../../../hooks/useUnreadNotifications';
import { useServiceAvailability } from '../../../hooks/useServiceAvailability';
import ContextSwitcher from '../../common/ContextSwitcher';

const ProfileDisplay = ({ profile, image, user, onSidebarToggle, sidebarCollapsed }) => {
    const { t } = useTranslation('common');
    const [darkMode, setDarkMode] = useState(false);
    const [isEmployer, setIsEmployer] = useState(false);
    const [showNotifications, setShowNotifications] = useState(false);
    const [modulesConfig, setModulesConfig] = useState({
        enablePortfolioModule: false,
        enableJobScraperModule: false,
        enableCoverLetterModule: false,
        enableMessagesModule: false,
        enableJobTrackerModule: false,
        enableAppliedJobsModule: false,
    });

    const location = useLocation(); // Get current location
    const authUser = useContext(AuthContext); // Get authenticated user from context
    const { unreadCount } = useUnreadMessages(); // Get unread messages count
    const { unreadNotificationCount, refreshCount } = useUnreadNotifications(); // Get unread notifications count
    const [liveProfileImage, setLiveProfileImage] = useState(null);
    const [liveProfileName, setLiveProfileName] = useState(null);
    const [isAdmin, setIsAdmin] = useState(false);

    useEffect(() => {
        let active = true;
        if (!authUser?.getIdTokenResult) { setIsAdmin(false); return () => { active = false; }; }
        authUser.getIdTokenResult().then(result => {
            if (active) setIsAdmin(['ADMIN', 'SUPER_ADMIN'].includes(String(result.claims.role || '').toUpperCase()));
        }).catch(() => { if (active) setIsAdmin(false); });
        return () => { active = false; };
    }, [authUser]);

    // CM360 / DV360 Categorized Navigation Accordion State
    const [openGroups, setOpenGroups] = useState({
        career: true,
        jobIntel: true,
        billing: true, // Always expanded by default
    });

    const toggleNavGroup = (groupKey) => {
        setOpenGroups((prev) => ({ ...prev, [groupKey]: !prev[groupKey] }));
    };

    // Auto-expand accordion when active path matches a sub-item
    useEffect(() => {
        const p = location.pathname;
        if (p.startsWith('/build-resume') || p.startsWith('/create-resume') || p === '/dashboard/cover-letters' || p === '/dashboard/portfolios') {
            setOpenGroups(prev => ({ ...prev, career: true }));
        } else if (p.startsWith('/jobs') || p.startsWith('/dashboard/jobs') || p === '/dashboard/applied-jobs' || p === '/dashboard/job-tracker' || p === '/dashboard/interview' || p === '/dashboard/messages') {
            setOpenGroups(prev => ({ ...prev, jobIntel: true }));
        } else if (p === '/dashboard/settings' || p === '/dashboard/plans' || p === '/dashboard/support' || p === '/dashboard/tickets' || p === '/dashboard/help') {
            setOpenGroups(prev => ({ ...prev, billing: true }));
        }
    }, [location.pathname]);

    // Listen for live profile updates from Settings
    useEffect(() => {
        const handleProfileUpdate = (e) => {
            if (e?.detail) {
                if (e.detail.selectedImage || e.detail.image) {
                    setLiveProfileImage(e.detail.selectedImage || e.detail.image);
                }
                const nameStr = (e.detail.name && e.detail.name.trim()) || `${e.detail.firstname || ''} ${e.detail.lastname || ''}`.trim();
                if (nameStr) setLiveProfileName(nameStr);
            }
        };
        window.addEventListener('profileUpdated', handleProfileUpdate);
        return () => window.removeEventListener('profileUpdated', handleProfileUpdate);
    }, []);

    const userAvatarUrl =
        liveProfileImage ||
        profile?.selectedImage ||
        profile?.image ||
        image?.selectedImage ||
        image?.image ||
        authUser?.photoURL ||
        userPlaceholder;

    const candidateDisplayName = (
        liveProfileName ||
        (profile?.name && profile.name.trim()) ||
        (`${profile?.firstname || ''} ${profile?.lastname || ''}`.trim()) ||
        authUser?.displayName ||
        (authUser?.email ? authUser.email.split('@')[0] : '') ||
        'Master User'
    ).replace(/\s+/g, ' ').trim();

    const userMembershipTier = isAdmin ? 'Admin Tier' : (profile?.membership || 'Basic');
    // Enterprise tenancy is opt-in and dark by default, preserving the certified
    // personal dashboard until the server-side data-plane gates are approved.
    // The build-time flag alone is not sufficient: if the client is built with
    // tenancy on but the backend has it dark, this link produces a 404. We
    // therefore require the backend to confirm tenancy is actually served.
    const buildTimeEnterpriseFlag = import.meta.env?.VITE_ENTERPRISE_TENANCY_ENABLED === 'true';
    const { availability: platformAvailability, status: availabilityStatus } = useServiceAvailability();
    const enterpriseEnabled = availabilityStatus === 'ready'
        && (buildTimeEnterpriseFlag || platformAvailability?.enterpriseTenancy === true)
        && platformAvailability?.enterpriseTenancy === true;

    // Check system modules settings
    useEffect(() => {
        const loadModules = (event) => {
            if (event?.detail?.modules) {
                const m = event.detail.modules;
                setModulesConfig({
                    enablePortfolioModule: m.enablePortfolioModule === true,
                    enableJobScraperModule: m.enableJobScraperModule === true,
                    enableCoverLetterModule: m.enableCoverLetterModule === true,
                    enableMessagesModule: m.enableMessagesModule === true,
                    enableJobTrackerModule: m.enableJobTrackerModule === true,
                    enableAppliedJobsModule: m.enableAppliedJobsModule === true,
                });
                return;
            }
            getSystemSettings().then((settings) => {
                const m = settings?.modules || {};
                setModulesConfig({
                    enablePortfolioModule: m.enablePortfolioModule === true,
                    enableJobScraperModule: m.enableJobScraperModule === true,
                    enableCoverLetterModule: m.enableCoverLetterModule === true,
                    enableMessagesModule: m.enableMessagesModule === true,
                    enableJobTrackerModule: m.enableJobTrackerModule === true,
                    enableAppliedJobsModule: m.enableAppliedJobsModule === true,
                });
            }).catch(() => {});
        };
        loadModules();
        window.addEventListener('systemSettingsUpdated', loadModules);
        return () => window.removeEventListener('systemSettingsUpdated', loadModules);
    }, []);

    const closeMobileSidebar = () => {
        if (window.innerWidth < 1024 && !sidebarCollapsed) {
            // On mobile, collapse = hidden
            if (onSidebarToggle) onSidebarToggle(true);
            document.body.classList.remove('mobile-sidebar-open');
        }
    };

    const toggleSidebar = () => {
        const newCollapsed = !sidebarCollapsed;
        if (onSidebarToggle) {
            onSidebarToggle(newCollapsed);
        }

        // Mobile body scroll prevention
        const isMobile = window.innerWidth < 1024;
        if (isMobile) {
            if (newCollapsed) {
                document.body.classList.remove('mobile-sidebar-open');
            } else {
                document.body.classList.add('mobile-sidebar-open');
            }
        }

        const contentWrapper = document.querySelector('.dashboardContentWrapper');
        const dashboardGrid = document.querySelector('.dashboardGrid');

        const elementsToToggle = [contentWrapper, dashboardGrid].filter(Boolean);

        elementsToToggle.forEach((el) => {
            if (el) {
                if (newCollapsed) {
                    el.classList.add('sidebar-collapsed');
                } else {
                    el.classList.remove('sidebar-collapsed');
                }
            }
        });
    };

    () => {;
        setDarkMode(!darkMode);
    };

    useEffect(() => {
        const savedState = localStorage.getItem('sidebarCollapsed');
        if (savedState) {
            const isCollapsed = savedState === 'true';
            if (onSidebarToggle) {
                onSidebarToggle(isCollapsed);
            }

            const contentWrapper = document.querySelector('.dashboardContentWrapper');
            const dashboardGrid = document.querySelector('.dashboardGrid');

            const elementsToToggle = [contentWrapper, dashboardGrid].filter(Boolean);

            elementsToToggle.forEach((el) => {
                if (el) {
                    if (isCollapsed) {
                        el.classList.add('sidebar-collapsed');
                    } else {
                        el.classList.remove('sidebar-collapsed');
                    }
                }
            });
        }
    }, [onSidebarToggle]);

    useEffect(() => {
        localStorage.setItem('sidebarCollapsed', sidebarCollapsed);
    }, [sidebarCollapsed]);

    useEffect(() => {
        if (user) {
            checkIsEmployer(user)
                .then((employerStatus) => {
                    setIsEmployer(employerStatus);
                })
                .catch((error) => {
                    console.error('Error checking employer status:', error);
                    setIsEmployer(false);
                });
        } else {
            setIsEmployer(false);
        }
    }, [user]);

    useEffect(() => {
        const handleNotificationsUpdated = () => {
            refreshCount();
        };

        window.addEventListener('notificationsUpdated', handleNotificationsUpdated);
        return () => {
            window.removeEventListener('notificationsUpdated', handleNotificationsUpdated);
        };
    }, [refreshCount]);

    useEffect(() => {
        const handleMobileToggle = () => {
            toggleSidebar();
        };

        const handleResize = () => {
            if (window.innerWidth >= 1024) {
                document.body.classList.remove('mobile-sidebar-open');
            }
        };

        window.addEventListener('toggleMobileSidebar', handleMobileToggle);
        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('toggleMobileSidebar', handleMobileToggle);
            window.removeEventListener('resize', handleResize);
            document.body.classList.remove('mobile-sidebar-open');
        };
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    return (
        <>
            <style>{`
                [data-shell-variant="legacy"] .dashboardContentWrapper,
                [data-shell-variant="legacy"] .dashboardGrid {
                    margin-left: 280px !important;
                    width: calc(100% - 280px) !important;
                    box-sizing: border-box !important;
                    transition: margin-left 0.3s ease, width 0.3s ease !important;
                }

                [data-shell-variant="legacy"] .dashboardContentWrapper.sidebar-collapsed,
                [data-shell-variant="legacy"] .dashboardGrid.sidebar-collapsed {
                    margin-left: 60px !important;
                    width: calc(100% - 60px) !important;
                }

                @media only screen and (max-width: 1050px) {
                    [data-shell-variant="legacy"] .dashboardContentWrapper,
                    [data-shell-variant="legacy"] .dashboardGrid {
                        margin-left: 0 !important;
                        width: 100% !important;
                    }

                    [data-shell-variant="legacy"] .dashboardContentWrapper.sidebar-collapsed,
                    [data-shell-variant="legacy"] .dashboardGrid.sidebar-collapsed {
                        margin-left: 60px !important;
                        width: calc(100% - 60px) !important;
                    }
                }

                @media only screen and (max-width: 1023px) {
                    /* Content shifts down for mobile top bar + up for bottom nav */
                    [data-shell-variant="legacy"] .dashboardContentWrapper,
                    [data-shell-variant="legacy"] .dashboardGrid {
                        margin-left: 0 !important;
                        width: 100% !important;
                        padding-top: 56px !important;
                        padding-bottom: 68px !important;
                    }

                    [data-shell-variant="legacy"] .dashboardContentWrapper.sidebar-collapsed,
                    [data-shell-variant="legacy"] .dashboardGrid.sidebar-collapsed {
                        margin-left: 0 !important;
                        width: 100% !important;
                    }

                    /* Sidebar becomes an overlay drawer */
                    body.mobile-sidebar-open {
                        overflow: hidden;
                    }

                    .mobile-overlay {
                        backdrop-filter: blur(4px);
                        -webkit-backdrop-filter: blur(4px);
                        background: rgba(15, 23, 42, 0.35);
                    }
                }

                @media only screen and (max-width: 480px) {
                    [data-shell-variant="legacy"] .dashboardContentWrapper,
                    [data-shell-variant="legacy"] .dashboardGrid,
                    [data-shell-variant="legacy"] .dashboardContentWrapper.sidebar-collapsed,
                    [data-shell-variant="legacy"] .dashboardGrid.sidebar-collapsed {
                        padding-left: 0 !important;
                        width: 100% !important;
                    }
                }

                @media only screen and (max-width: 1023px) {
                    .mobile-overlay {
                        backdrop-filter: blur(4px);
                        -webkit-backdrop-filter: blur(4px);
                        background: rgba(0, 0, 0, 0.25);
                    }

                    .mobile-overlay-enter {
                        opacity: 0;
                        backdrop-filter: blur(0px);
                        -webkit-backdrop-filter: blur(0px);
                    }

                    .mobile-overlay-enter-active {
                        opacity: 1;
                        backdrop-filter: blur(4px);
                        -webkit-backdrop-filter: blur(4px);
                        transition: opacity 0.25s ease-out, backdrop-filter 0.3s ease-out;
                    }

                    body.mobile-sidebar-open {
                        overflow: hidden;
                        position: fixed;
                        width: 100%;
                    }
                }
            `}</style>

            {/* ── MOBILE TOP BAR ────────────────────────────────────────────── */}
            <div className="fixed top-0 left-0 right-0 h-14 bg-white border-b border-gray-100 z-[60] lg:hidden flex items-center justify-between px-4 shadow-sm">
                {/* Hamburger */}
                <button
                    onClick={toggleSidebar}
                    className="w-10 h-10 flex items-center justify-center rounded-xl hover:bg-gray-100 active:bg-gray-200 transition-colors"
                    aria-label="Open menu"
                >
                    {!sidebarCollapsed ? (
                        <FiX className="w-5 h-5 text-gray-700" />
                    ) : (
                        <FiMenu className="w-5 h-5 text-gray-700" />
                    )}
                </button>

                {/* Logo centred */}
                <Link to="/dashboard" className="absolute left-1/2 -translate-x-1/2">
                    <img src={logo} alt="IME365.com" className="h-12 w-auto object-contain" />
                </Link>

                {/* Right actions: Bell */}
                <div className="flex items-center gap-1">
                    <button
                        onClick={() => setShowNotifications(!showNotifications)}
                        className="w-10 h-10 flex items-center justify-center rounded-xl hover:bg-gray-100 active:bg-gray-200 transition-colors relative"
                        aria-label="Notifications"
                    >
                        <FiBell className="w-5 h-5 text-gray-700" />
                        {unreadNotificationCount > 0 && (
                            <span className="absolute top-1.5 right-1.5 w-2 h-2 bg-indigo-600 rounded-full"></span>
                        )}
                    </button>
                </div>
            </div>

            {/* Mobile backdrop */}
            <div
                className={`fixed inset-0 bg-black mobile-overlay z-40 lg:hidden transition-opacity duration-300 ease-in-out ${!sidebarCollapsed ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}
                onClick={toggleSidebar}
            />

            <div
                className={`fixed left-0 top-0 h-screen bg-slate-50 border-r border-slate-200/90 z-50 flex flex-col transition-all duration-300 ease-in-out text-slate-700 ${
                    sidebarCollapsed ? 'lg:w-[60px] lg:min-w-[60px] w-[280px]' : 'w-[280px] lg:w-[280px]'
                }
                lg:flex lg:shadow-none
                ${sidebarCollapsed ? 'max-lg:-translate-x-full' : 'max-lg:translate-x-0 shadow-2xl lg:shadow-none'}
                `}>
                <div className={`transition-all duration-300 border-b border-slate-200/80 bg-white ${sidebarCollapsed ? 'p-3' : 'px-4 py-4'}`}>
                    {sidebarCollapsed ? (
                        <div className="space-y-5">
                            <div className="flex justify-center">
                                <button onClick={toggleSidebar} className="w-10 h-10 bg-slate-50 hover:bg-slate-100 rounded-xl border border-slate-200 shadow-2xs flex items-center justify-center transition-colors duration-200 cursor-pointer">
                                    <GoSidebarCollapse className="w-5 h-5 text-slate-600" />
                                </button>
                            </div>
                            <div className="flex justify-center">
                                <Link to="/dashboard/settings" title="Master Profile & Settings">
                                    <div className="relative cursor-pointer">
                                        <div className="w-10 h-10 rounded-full ring-2 ring-indigo-500/20 overflow-hidden bg-indigo-50">
                                            <img
                                                src={userAvatarUrl}
                                                alt="User Avatar"
                                                className="w-full h-full object-cover"
                                                onError={(e) => {
                                                    e.target.src = userPlaceholder;
                                                }}
                                            />
                                        </div>
                                        {unreadNotificationCount > 0 && (
                                            <div className="absolute -top-0.5 -right-0.5 w-4 h-4 bg-indigo-600 text-white text-[10px] leading-none rounded-full flex items-center justify-center font-bold border border-white">
                                                {unreadNotificationCount > 9 ? '9+' : unreadNotificationCount}
                                            </div>
                                        )}
                                        <div className="absolute bottom-0 right-0 w-2.5 h-2.5 bg-emerald-500 rounded-full border border-white"></div>
                                    </div>
                                </Link>
                            </div>
                        </div>
                    ) : (
                        <div className="space-y-4">
                            <div className="flex items-center justify-between">
                                <div className="flex items-center gap-2">
                                    <Link to="/">
                                        <img src={logo} alt="IME365.com" className="h-14 w-auto max-w-[220px] object-contain" />
                                    </Link>
                                </div>
                                <div className="flex items-center gap-2">
                                    <button onClick={toggleSidebar} aria-label="Toggle sidebar" title="Toggle sidebar" className="w-9 h-9 bg-slate-50 hover:bg-slate-100 border border-slate-200 text-slate-600 hover:text-slate-900 rounded-xl flex items-center justify-center transition-colors duration-200 cursor-pointer shadow-2xs">
                                        <GoSidebarExpand className="w-4 h-4" aria-hidden="true" focusable="false" />
                                    </button>
                                </div>
                            </div>

                            <Link to="/dashboard/settings" className="block text-slate-900 hover:opacity-95 transition-opacity" title="Master Profile & Settings">
                                <div className="bg-white p-3 rounded-xl flex items-center gap-3 border border-slate-200 shadow-2xs hover:border-indigo-300 transition-all cursor-pointer">
                                    <div className="relative flex-shrink-0">
                                        <div className="w-10 h-10 rounded-full ring-2 ring-indigo-500/20 overflow-hidden bg-indigo-50">
                                            <img
                                                src={userAvatarUrl}
                                                alt="User Avatar"
                                                className="w-full h-full object-cover"
                                                onError={(e) => {
                                                    e.target.src = userPlaceholder;
                                                }}
                                            />
                                        </div>
                                        <div className="absolute bottom-0 right-0 w-3 h-3 bg-emerald-500 rounded-full border-2 border-white"></div>
                                    </div>
                                    <div className="flex-1 min-w-0 overflow-hidden">
                                        <p className="text-xs font-bold text-slate-900 truncate whitespace-nowrap overflow-hidden text-ellipsis mb-0.5" title={candidateDisplayName}>
                                            {candidateDisplayName}
                                        </p>
                                        <p className="text-[10px] text-slate-500 truncate whitespace-nowrap overflow-hidden text-ellipsis mb-1" title={authUser?.email || profile?.email}>
                                            {authUser?.email || profile?.email || ''}
                                        </p>
                                        <span className={`inline-flex items-center px-2 py-0.5 text-[9px] font-extrabold rounded-full border ${
                                            userMembershipTier.includes('Admin')
                                                ? 'text-red-700 bg-red-50 border-red-200'
                                                : 'text-indigo-700 bg-indigo-50 border-indigo-200'
                                        }`}>
                                            <span className={`w-1.5 h-1.5 rounded-full mr-1 ${
                                                userMembershipTier.includes('Admin') ? 'bg-red-500' : 'bg-indigo-600 animate-pulse'
                                            }`}></span>
                                            {userMembershipTier}
                                        </span>
                                    </div>
                                </div>
                            </Link>
                        </div>
                    )}
                </div>

                {/* Navigation Menu — CM360 Light Categorized Dropdowns */}
                <div className="flex-1 overflow-y-auto px-2.5 py-3 space-y-3 custom-scrollbar">
                    {/* ── 1. MAIN WORKSPACE ── */}
                    <div>
                        {!sidebarCollapsed && (
                            <p className="text-[9px] font-extrabold text-slate-600 uppercase tracking-widest px-2 mb-1.5">Main Workspace</p>
                        )}
                        <Link to="/dashboard" onClick={closeMobileSidebar}>
                            <div
                                className={`flex items-center text-xs transition-all duration-150 rounded-xl ${
                                    location.pathname === '/dashboard'
                                        ? 'bg-indigo-50 text-indigo-700 font-bold border-l-3 border-indigo-600 shadow-2xs pl-2.5'
                                        : 'text-slate-600 hover:bg-slate-100 hover:text-slate-900 font-medium'
                                } ${sidebarCollapsed ? 'p-2.5 justify-center' : 'px-2.5 py-2'}`}>
                                <FiGrid className={`text-base min-w-[18px] ${sidebarCollapsed ? 'mr-0' : 'mr-2.5'}`} />
                                {!sidebarCollapsed && <span className="flex-1">Overview &amp; Resumes</span>}
                            </div>
                        </Link>
                        {/* Persona switching is centralized in the shared
                            ContextSwitcher below. The candidate sidebar does not
                            carry its own enterprise or admin entry, so there is
                            exactly one context switcher in the product. */}
                        {!sidebarCollapsed && (
                            <div className="mt-2">
                                <ContextSwitcher variant="sidebar" onNavigate={closeMobileSidebar} />
                            </div>
                        )}
                    </div>

                    {/* ── 2. CAREER SUITE (Dropdown) ── */}
                    <div>
                        {!sidebarCollapsed ? (
                            <button
                                type="button"
                                onClick={() => toggleNavGroup('career')}
                                className="w-full flex items-center justify-between px-2 py-1 text-[9px] font-extrabold text-slate-600 uppercase tracking-widest hover:text-slate-900 transition-colors cursor-pointer mb-1">
                                <span>Career Suite</span>
                                {openGroups.career ? <FiChevronDown className="w-3 h-3 text-slate-400" /> : <FiChevronRight className="w-3 h-3 text-slate-400" />}
                            </button>
                        ) : null}

