};

function setMeta(selector, attributes) {
  let element = document.head.querySelector(selector);
  if (!element) {
    element = document.createElement(selector.startsWith('link') ? 'link' : 'meta');
    document.head.appendChild(element);
  }
  Object.entries(attributes).forEach(([key, value]) => element.setAttribute(key, String(value)));
  element.setAttribute('data-route-seo-owner', 'route');
  return element;
}

function removeMeta(selector) {
  document.head.querySelector(selector)?.remove();
}

function canonicalBaseFor(geoSeo, origin) {
  const configured = String(geoSeo?.canonicalUrl || '').trim();
  if (configured) {
    try {
      const url = new URL(configured);
      if (url.protocol === 'https:' && !url.username && !url.password && !url.search && !url.hash && (!url.pathname || url.pathname === '/')) {
        return url.origin;
      }
    } catch { /* use the current origin when the operator value is invalid */ }
  }
  return origin;
}

function absoluteUrl(base, pathname) {
  return safeSchemaUrl(pathname, `${base.replace(/\/$/, '')}/`);
}

function setCanonical(href) {
  if (href) setMeta('link[rel="canonical"]', { rel: 'canonical', href });
  else removeMeta('link[rel="canonical"]');
}

function setRouteSchemas(schemas) {
  const valid = (Array.isArray(schemas) ? schemas : [schemas]).filter(Boolean);
  let script = document.getElementById('route-seo-structured-data');
  if (!valid.length) {
    script?.remove();
    return;
  }
  if (!script) {
    script = document.createElement('script');
    script.id = 'route-seo-structured-data';
    script.type = 'application/ld+json';
    document.head.appendChild(script);
  }
  script.textContent = safeJsonLd(valid.length === 1 ? valid[0] : valid);
}

function prettySlug(slug = '') {
  return decodeURIComponent(slug).split('-').filter(Boolean).map(part =>
    part.toLowerCase() === 'ncr' ? 'NCR' : part.charAt(0).toUpperCase() + part.slice(1)
  ).join(' ');
}

function publicJob(job) {
  if (!job || String(job.status || '').trim().toLowerCase() !== 'active') return false;
  if (job.deleted_at || job.deletedAt || job.tombstoned || job.is_deleted || job.isDeleted) return false;
  const expires = job.expires_at || job.expiresAt;
  if (!expires) return true;
  const expiresAt = new Date(expires).getTime();
  return Number.isFinite(expiresAt) && expiresAt > Date.now();
}

function addGeoMeta(geoSeo, regionName = '') {
  if (geoSeo?.enableGeoSeo !== true) {
    removeMeta('meta[name="keywords"]');
    removeMeta('meta[name="geo.region"]');
    removeMeta('meta[name="geo.placename"]');
    return;
  }
  if (geoSeo.metaKeywords) setMeta('meta[name="keywords"]', { name: 'keywords', content: geoSeo.metaKeywords });
  if (geoSeo.targetRegion) setMeta('meta[name="geo.region"]', { name: 'geo.region', content: geoSeo.targetRegion });
  const place = regionName || geoSeo.targetCity;
  if (place) setMeta('meta[name="geo.placename"]', { name: 'geo.placename', content: place });
}

export default function RouteSeo() {
  const location = useLocation();
  useEffect(() => {
    const path = location.pathname;
    // Public articles and published portfolios own their richer metadata.
    // Return before the generic route cleanup so that it cannot race with the
    // page-level canonical, social-preview, or structured-data effects.
    if (/^\/blog\/[^/]+$/.test(path) || /^\/portfolio\/[^/]+$/.test(path)) {
      document.head.querySelectorAll('[data-route-seo-owner="route"]').forEach(element => element.remove());
      document.getElementById('route-seo-structured-data')?.remove();
      return undefined;
    }

    document.getElementById('route-seo-structured-data')?.remove();
    removeMeta('meta[property="og:image"]');
    removeMeta('meta[property="og:image:alt"]');
    removeMeta('meta[property="og:image:type"]');
    removeMeta('meta[property="og:image:width"]');
    removeMeta('meta[property="og:image:height"]');
    removeMeta('meta[name="twitter:image"]');
    removeMeta('meta[name="twitter:card"]');

    const isPrivatePrefix = PRIVATE_PREFIXES.some(prefix => path === prefix || path.startsWith(prefix + '/'));
    const isLogin = path === '/login';
    const isJobCategory = /^\/jobs\/category\/[^/]+$/.test(path);
    const isJobDetail = /^\/jobs\/portal\/[^/]+$/.test(path);
    const regionalMatch = path.match(/^\/jobs\/(city|in)\/([^/]+)$/);
    const isRegionalHub = Boolean(regionalMatch);
    const isCustomPage = path.startsWith('/p/');

    let title;
    let description;
    if (isRegionalHub) {
      const place = prettySlug(regionalMatch[2]);
      title = `Technology Jobs in ${place} — ${SITE_NAME}`;
      description = `Browse current active job listings in ${place}. Listing counts and compensation details are based on published employer postings.`;
    } else if (isJobCategory) {
      const cat = decodeURIComponent(path.split('/').pop() || '').replace(/-/g, ' ');
      title = `${cat ? cat.charAt(0).toUpperCase() + cat.slice(1) + ' Jobs' : 'Job Category'} — ${SITE_NAME}`;
      description = `Browse ${cat || 'job'} opportunities on IME365.`;
    } else if (isJobDetail) {
      title = `Job Listing — ${SITE_NAME}`;
      description = 'View the published job details and application information.';
    } else if (isCustomPage) {
      title = `${SITE_NAME}`;
      description = 'Public information from IME365.';
    } else if (PUBLIC_PAGES[path]) {
      [title, description] = PUBLIC_PAGES[path];
    } else if (isPrivatePrefix || isLogin) {
      const matchedPrefix = PRIVATE_PREFIXES.find(prefix => path === prefix || path.startsWith(prefix + '/'));
      title = PRIVATE_TITLES[matchedPrefix] || `${SITE_NAME}`;
      description = PRIVATE_DESCRIPTIONS[matchedPrefix] || '';
    } else {
      title = `Page Not Found — ${SITE_NAME}`;
      description = 'The requested page is unavailable.';
    }

    const isIndexable = (!isPrivatePrefix && !isLogin && PUBLIC_PAGES[path] !== undefined)
      || isJobCategory || isJobDetail || isRegionalHub || isCustomPage;
    const canonicalPath = path === '/billing/plans' ? '/pricing' : path;
    const origin = window.location.origin;
    const fallbackCanonical = absoluteUrl(origin, canonicalPath);

    document.title = title;
    setMeta('meta[name="description"]', { name: 'description', content: description || '' });
    setMeta('meta[name="robots"]', {
      name: 'robots',
      content: isRegionalHub || isJobDetail ? 'noindex,nofollow' : isIndexable ? 'index,follow' : 'noindex,nofollow',
    });
    setMeta('meta[property="og:title"]', { property: 'og:title', content: title });
    setMeta('meta[property="og:description"]', { property: 'og:description', content: description || '' });
    setMeta('meta[property="og:url"]', { property: 'og:url', content: fallbackCanonical || `${origin}${canonicalPath}` });
    setMeta('meta[property="og:type"]', { property: 'og:type', content: isJobDetail ? 'article' : 'website' });
    setMeta('meta[property="og:site_name"]', { property: 'og:site_name', content: SITE_NAME });
    setMeta('meta[name="twitter:title"]', { name: 'twitter:title', content: title });
    setMeta('meta[name="twitter:description"]', { name: 'twitter:description', content: description || '' });
    if (isIndexable && !isRegionalHub && !isJobDetail) setCanonical(fallbackCanonical);
    else setCanonical(null);

    let active = true;
    const run = async () => {
      let config = null;
      try {
        const candidate = await fetchPublicConfig();
        if (candidate?._settingsSource === 'mariadb') config = candidate;
      } catch { /* no metadata is synthesized when MariaDB is unavailable */ }
      if (!active) return;

      const geoSeo = config?.geoSeo && typeof config.geoSeo === 'object' ? config.geoSeo : {};
      const canonicalBase = canonicalBaseFor(geoSeo, origin);
      const canonical = absoluteUrl(canonicalBase, canonicalPath);
      if (isIndexable && !isRegionalHub && !isJobDetail) setCanonical(canonical);
      if (canonical) setMeta('meta[property="og:url"]', { property: 'og:url', content: canonical });
      addGeoMeta(geoSeo);

      const schemas = [];
      if (path === '/' && geoSeo.enableGeoSeo === true) {
        if (geoSeo.enableOrganizationSchema === true) {
          schemas.push(buildOrganizationSchema(config, canonicalBase));
        }
        schemas.push(buildFaqPageSchema(HOMEPAGE_FAQS));
      }
      if (isJobCategory && geoSeo.enableGeoSeo === true) {
        const cat = prettySlug(path.split('/').pop() || 'Jobs');
        const crumbs = buildBreadcrumbSchema([
          { name: 'Home', url: absoluteUrl(canonicalBase, '/') },
          { name: 'Jobs', url: absoluteUrl(canonicalBase, '/jobs') },
          { name: `${cat} jobs`, url: canonical },
        ], canonicalBase);
        if (crumbs) schemas.push(crumbs);
      }

      if (isRegionalHub) {
        if (config?._settingsSource !== 'mariadb' || geoSeo.enableGeoSeo !== true) {
          setMeta('meta[name="robots"]', { name: 'robots', content: 'noindex,nofollow' });
          setCanonical(null);
          setRouteSchemas([]);
          return;
        }
        const kind = regionalMatch[1] === 'in' ? 'state' : 'city';
        try {
          const region = await getRegionalHub(kind, decodeURIComponent(regionalMatch[2]));
          if (!active) return;
          const place = region.name;
          const area = kind === 'city' && region.stateName ? `${region.name}, ${region.stateName}` : region.name;
          title = `Technology Jobs in ${place} — ${SITE_NAME}`;
          description = region.hasVacancies
            ? `${region.vacancyCount} active job ${region.vacancyCount === 1 ? 'listing' : 'listings'} currently published in ${area}. View current openings and salary information supplied by employers.`
            : `There are no active job listings currently published in ${area}. Check the live listings again later.`;
          document.title = title;
          setMeta('meta[name="description"]', { name: 'description', content: description });
          setMeta('meta[property="og:title"]', { property: 'og:title', content: title });
          setMeta('meta[property="og:description"]', { property: 'og:description', content: description });
          addGeoMeta(geoSeo, place);
          const regionCanonical = absoluteUrl(canonicalBase, path);
          if (region.hasVacancies && regionCanonical) {
            setMeta('meta[name="robots"]', { name: 'robots', content: 'index,follow' });
            setCanonical(regionCanonical);
            setMeta('meta[property="og:url"]', { property: 'og:url', content: regionCanonical });
            const breadcrumb = buildBreadcrumbSchema([
              { name: 'Home', url: absoluteUrl(canonicalBase, '/') },
              { name: 'Jobs', url: absoluteUrl(canonicalBase, '/jobs') },
              { name: place, url: regionCanonical },
            ], canonicalBase);
            if (breadcrumb) schemas.push(breadcrumb);
          } else {
            setMeta('meta[name="robots"]', { name: 'robots', content: 'noindex,follow' });
            setCanonical(null);
          }
        } catch (error) {
          if (!active) return;
          setMeta('meta[name="robots"]', { name: 'robots', content: 'noindex,nofollow' });
          setCanonical(null);
          setRouteSchemas([]);
          return;
        }
      }

      if (isJobDetail) {
        const rawId = path.split('/').pop() || '';
        let job;
        try {
          job = await getJob(decodeURIComponent(rawId));
        } catch {
          if (!active) return;
          setMeta('meta[name="robots"]', { name: 'robots', content: 'noindex,nofollow' });
          setCanonical(null);
          setRouteSchemas([]);
          return;
        }
        if (!active) return;
        if (!publicJob(job)) {
          setMeta('meta[name="robots"]', { name: 'robots', content: 'noindex,nofollow' });
          setCanonical(null);
          setRouteSchemas([]);
          return;
        }
        const jobTitle = schemaText(job.title, 255) || 'Job listing';
        const company = schemaText(job.company_name || job.companyName || job.company, 180);
        title = `${jobTitle}${company ? ` at ${company}` : ''} — ${SITE_NAME}`;
        description = schemaText(job.description, 165) || 'View the published job details and application information.';
        document.title = title;
        setMeta('meta[name="description"]', { name: 'description', content: description });
        setMeta('meta[property="og:title"]', { property: 'og:title', content: title });
        setMeta('meta[property="og:description"]', { property: 'og:description', content: description });
        setMeta('meta[name="twitter:title"]', { name: 'twitter:title', content: title });
        setMeta('meta[name="twitter:description"]', { name: 'twitter:description', content: description });
        const jobCanonical = absoluteUrl(canonicalBase, `/jobs/portal/${encodeURIComponent(job.id)}`);
        if (jobCanonical) {
          setMeta('meta[name="robots"]', { name: 'robots', content: 'index,follow' });
          setCanonical(jobCanonical);
          setMeta('meta[property="og:url"]', { property: 'og:url', content: jobCanonical });
          const preview = absoluteUrl(canonicalBase, `/api/public/jobs/${encodeURIComponent(job.id)}/og.png`);
          if (preview) {
            setMeta('meta[property="og:image"]', { property: 'og:image', content: preview });
            setMeta('meta[property="og:image:alt"]', { property: 'og:image:alt', content: `${jobTitle}${company ? ` at ${company}` : ''}` });
            setMeta('meta[property="og:image:type"]', { property: 'og:image:type', content: 'image/png' });
            setMeta('meta[property="og:image:width"]', { property: 'og:image:width', content: '1200' });
            setMeta('meta[property="og:image:height"]', { property: 'og:image:height', content: '630' });
            setMeta('meta[name="twitter:card"]', { name: 'twitter:card', content: 'summary_large_image' });
            setMeta('meta[name="twitter:image"]', { name: 'twitter:image', content: preview });
          }
        }
        addGeoMeta(geoSeo);
        if (geoSeo.enableJobPostingSchema === true) {
          schemas.push(buildJobPostingSchema(job, { canonicalUrl: jobCanonical }));
          const breadcrumb = buildBreadcrumbSchema([
            { name: 'Home', url: absoluteUrl(canonicalBase, '/') },
            { name: 'Jobs', url: absoluteUrl(canonicalBase, '/jobs') },
            { name: jobTitle, url: jobCanonical },
          ], canonicalBase);
          if (breadcrumb) schemas.push(breadcrumb);
        }
      }

      if (config?._settingsSource === 'mariadb' && config?.llmGeo?.enableLlmGeo === true) {
        setMeta('link[rel="alternate"][data-route-seo="llms"]', {
          rel: 'alternate', type: 'text/plain', title: 'Concise LLM discovery document', href: '/llms.txt', 'data-route-seo': 'llms',
        });
        if (String(config.llmGeo.llmsFullTxtContent || '').trim()) {
          setMeta('link[rel="alternate"][data-route-seo="llms-full"]', {
            rel: 'alternate', type: 'text/plain', title: 'Detailed LLM discovery document', href: '/llms-full.txt', 'data-route-seo': 'llms-full',
          });
        } else {
          removeMeta('link[rel="alternate"][data-route-seo="llms-full"]');
        }
      } else {
        removeMeta('link[rel="alternate"][data-route-seo="llms"]');
        removeMeta('link[rel="alternate"][data-route-seo="llms-full"]');
      }
      setRouteSchemas(schemas);
    };

    run();
    return () => {
      active = false;
      document.getElementById('route-seo-structured-data')?.remove();
    };
  }, [location.pathname]);
  return null;
}

import React, { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import { fetchAdminWithReauth } from '../../../services/adminReauth';
import { sanitizeImageUrl } from '../../../utils/sanitizeHtml';
import { listBlogPosts, updateBlogPost, deleteBlogPost, listBlogCategories, getUserData } from '../../../services/api/platform';
import { FiSearch, FiFilter, FiCheck, FiX, FiEye, FiEdit3, FiTrash2, FiClock, FiUser, FiTag, FiChevronDown, FiChevronUp, FiAlertCircle, FiRefreshCw } from 'react-icons/fi';
import BlogPreviewModal from './BlogPreviewModal';
import fire from '../../../conf/fire';

const BlogManagement = () => {
    const [posts, setPosts] = useState([]);
    const [categories, setCategories] = useState([]);
    const [loading, setLoading] = useState(true);
    const [processing, setProcessing] = useState(false);
    const [notification, setNotification] = useState(null);
    const [selectedPosts, setSelectedPosts] = useState([]);
    
    // Filters
    const [filters, setFilters] = useState({
        status: 'all',
        category: 'all',
        author: '',
        search: ''
    });
    
    // Pagination
    const [currentPage, setCurrentPage] = useState(1);
    const [pagination, setPagination] = useState(null);
    const [stats, setStats] = useState({
        total: 0,
        draft: 0,
        pending: 0,
        approved: 0,
        rejected: 0,
        scheduled: 0
    });

    // Expanded rows for viewing content
    const [expandedRows, setExpandedRows] = useState(new Set());
    
    // Preview modal state
    const [previewPost, setPreviewPost] = useState(null);
    const [isPreviewOpen, setIsPreviewOpen] = useState(false);
    const [schedulePost, setSchedulePost] = useState(null);
    const [scheduleValue, setScheduleValue] = useState('');
    const [confirmation, setConfirmation] = useState(null);
    const loadRequestRef = useRef(0);

    useEffect(() => {
        loadData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [filters, currentPage]);

    useEffect(() => {
        loadCategories();
    }, []);

    const loadData = async () => {
        const requestId = ++loadRequestRef.current;
        setLoading(true);
        
        try {
            const options = {
                status: filters.status === 'all' ? 'all' : filters.status,
                categoryId: filters.category === 'all' ? null : filters.category,
                limit: 20,
                page: currentPage,
                orderBy: 'createdAt',
                orderDirection: 'desc',
                includeStats: true
            };

            const result = await listBlogPosts(options);
            
            if (result && result.success) {
                const posts = Array.isArray(result.posts) ? result.posts : [];
                // Fetch each unique author once rather than once per row.
                const authorIds = [...new Set(posts.map(post => post.authorUid).filter(Boolean))];
                const authorEntries = await Promise.all(authorIds.map(async uid => [uid, await getUserData(uid)]));
                const authors = new Map(authorEntries);
                const enrichedPosts = posts.map(post => {
                    const authorData = authors.get(post.authorUid);
                    return {
                        ...post,
                        authorName: authorData
                            ? `${authorData.firstname || ''} ${authorData.lastname || ''}`.trim() || 'Unknown'
                            : 'Unknown'
                    };
                });
                
                if (requestId !== loadRequestRef.current) return;
                setPosts(enrichedPosts);
                if (result.pagination) {
                    setPagination(result.pagination);
                }
                if (result.stats) {
                    setStats(result.stats);
                }
            }
        } catch (error) {
            console.error('Error loading blog posts:', error);
            if (requestId === loadRequestRef.current) showNotification('Failed to load blog posts', 'error');
        } finally {
            if (requestId === loadRequestRef.current) setLoading(false);
        }
    };

    const loadCategories = async () => {
        try {
            const categoriesData = await listBlogCategories();
            setCategories(categoriesData);
        } catch (error) {
            console.error('Error loading categories:', error);
            showNotification(error.message || 'Failed to load blog categories', 'error');
        }
    };

    const showNotification = (message, type = 'success') => {
        setNotification({ message, type });
        setTimeout(() => setNotification(null), 5000);
    };

    const handleStatusUpdate = async (postId, newStatus, expectedRevision, confirmed = false) => {
        if (!confirmed) {
            const publishing = newStatus === 'approved';
            setConfirmation({
                title: publishing ? 'Publish post now?' : 'Return post for revision?',
                message: publishing ? 'This post will immediately become public and indexable.' : 'This post will become private and return to the author for revision.',
                onConfirm: () => handleStatusUpdate(postId, newStatus, expectedRevision, true),
            });
            return;
        }
        setConfirmation(null);
        setProcessing(true);
        
        try {
            const result = await updateBlogPost(postId, { status: newStatus }, null, expectedRevision);
            
            if (result.success) {
                showNotification(
                    `Post ${newStatus === 'approved' ? 'approved' : 'rejected'} successfully!`
                );
                await loadData(); // Refresh the list
            } else {
                showNotification(result.error || 'Failed to update post status', 'error');
            }
        } catch (error) {
            console.error('Error updating post status:', error);
            showNotification('Failed to update post status', 'error');
        } finally {
            setProcessing(false);
        }
    };

    const handleSchedulePost = post => {
        const localDefault = new Date(Date.now() + 3600000);
        localDefault.setMinutes(localDefault.getMinutes() - localDefault.getTimezoneOffset());
        setScheduleValue(localDefault.toISOString().slice(0, 16));
        setSchedulePost(post);
    };

    const confirmSchedulePost = async event => {
        event.preventDefault();
        const scheduledAt = new Date(scheduleValue);
        if (!Number.isFinite(scheduledAt.getTime()) || scheduledAt <= new Date()) {
            showNotification('Choose a valid future publication time.', 'error');
            return;
        }
        setProcessing(true);
        try {
            const result = await updateBlogPost(schedulePost.id, { status: 'scheduled', scheduledAt }, null, schedulePost.revision);
            if (!result.success) throw new Error(result.error);
            showNotification('Post scheduled successfully.');
            setSchedulePost(null);
            await loadData();
        } catch (error) {
            showNotification(error.message || 'Unable to schedule post.', 'error');
            await loadData();
        } finally {
            setProcessing(false);
        }
    };

    const handlePublishDue = async () => {
        setProcessing(true);
        try {
            const { response, data: result } = await fetchAdminWithReauth('/api/admin/blog/publish-due', { method: 'POST' });
            if (!response.ok || !result.success) throw new Error(result.error || 'Scheduler failed');
            showNotification(`${result.published} scheduled post(s) published.`);
            await loadData();
        } catch (error) {
            showNotification(error.message || 'Unable to publish scheduled posts.', 'error');
        } finally {
            setProcessing(false);
        }
    };

    const handleBulkAction = async (action, confirmed = false) => {
        if (selectedPosts.length === 0) {
            showNotification('Please select posts to perform bulk action', 'error');
            return;
        }
        const selectedRecords = selectedPosts.map(postId => posts.find(item => item.id === postId));
        if (selectedRecords.some(post => !post)) {
            showNotification('One or more selected posts are stale. Refresh and select them again.', 'error');
            await loadData();
            return;
        }
        if (['approve', 'reject'].includes(action) && selectedRecords.some(post => post.status !== 'pending')) {
            showNotification(`Only pending posts can be bulk ${action}d. No changes were made.`, 'error');
            return;
        }
        if (!confirmed) {
            setConfirmation({ title: `Confirm ${action}`, message: `Are you sure you want to ${action} ${selectedPosts.length} post(s)?`, onConfirm: () => handleBulkAction(action, true) });
            return;
        }
        setConfirmation(null);
        setProcessing(true);
        
        try {
            const promises = selectedPosts.map(postId => {
                const post = posts.find(item => item.id === postId);
                if (!post) return Promise.resolve({ success: false, error: 'Post is no longer in the current result set.' });
                if (action === 'approve') return updateBlogPost(postId, { status: 'approved' }, null, post.revision);
                if (action === 'reject') return updateBlogPost(postId, { status: 'rejected' }, null, post.revision);
                if (action === 'delete') return deleteBlogPost(postId, null, post.revision);
                return Promise.resolve({ success: false, error: 'Unsupported bulk action.' });
            });

            const results = await Promise.all(promises);
            const failures = results.filter(result => !result?.success);
            if (failures.length) throw new Error(`${failures.length} post(s) changed or failed. The list will be refreshed.`);
            showNotification(`Successfully ${action}d ${selectedPosts.length} post(s)!`);
            setSelectedPosts([]);
            await loadData();
        } catch (error) {
            console.error('Error performing bulk action:', error);
            showNotification(error.message || 'Failed to perform bulk action', 'error');
            await loadData();
        } finally {
            setProcessing(false);
        }
    };
    
    const handleDeletePost = async (postId, postTitle, expectedRevision, confirmed = false) => {
        if (!confirmed) {
            setConfirmation({ title: 'Delete post?', message: `Delete “${postTitle}”? This action cannot be undone.`, onConfirm: () => handleDeletePost(postId, postTitle, expectedRevision, true) });
            return;
        }
        setConfirmation(null);
        setProcessing(true);
        
        try {
            const result = await deleteBlogPost(postId, null, expectedRevision);
            
            if (result.success) {
                showNotification('Post deleted successfully!');
                await loadData(); // Refresh the list
            } else {
                showNotification(result.error || 'Failed to delete post', 'error');
            }
        } catch (error) {
            console.error('Error deleting post:', error);
            showNotification('Failed to delete post', 'error');
        } finally {
            setProcessing(false);
        }
    };
    
    const handlePreviewPost = (post) => {
        setPreviewPost(post);
        setIsPreviewOpen(true);
    };
    
    const closePreview = () => {
        setIsPreviewOpen(false);
        setPreviewPost(null);
    };

    const handleSelectAll = () => {
        if (selectedPosts.length === posts.length) {
            setSelectedPosts([]);
        } else {
            setSelectedPosts(posts.map(post => post.id));
        }
    };

    const togglePostSelection = (postId) => {
        setSelectedPosts(prev => 
            prev.includes(postId) 
                ? prev.filter(id => id !== postId)
                : [...prev, postId]
        );
    };

    const toggleRowExpansion = (postId) => {
        setExpandedRows(prev => {
            const newSet = new Set(prev);
            if (newSet.has(postId)) {
                newSet.delete(postId);
            } else {
                newSet.add(postId);
            }
            return newSet;
        });
    };

    const getStatusBadge = (status) => {
        const badges = {
            draft: { color: 'bg-slate-100 text-slate-800', text: 'Draft' },
            pending: { color: 'bg-yellow-100 text-yellow-800', text: 'Pending' },
            approved: { color: 'bg-green-100 text-green-800', text: 'Approved' },
            rejected: { color: 'bg-red-100 text-red-800', text: 'Rejected' },
            scheduled: { color: 'bg-purple-100 text-purple-800', text: 'Scheduled' }
        };
        
        const badge = badges[status] || badges.pending;
        
        return (
            <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${badge.color}`}>
                {badge.text}
            </span>
        );
    };

    const getCategoryName = (categoryId) => {
        const category = categories.find(c => c.id === categoryId);
        return category ? category.name : 'Unknown';
    };

    const formatDate = (date) => {
        if (!date) return 'Unknown';
        const postDate = date instanceof Date ? date : new Date(date);
        return postDate.toLocaleDateString('en-US', {
            year: 'numeric',
            month: 'short',
            day: 'numeric',
            hour: '2-digit',
            minute: '2-digit'
        });
    };

    const truncateContent = (content, limit = 150) => {
        if (!content) return '';
        if (content.length <= limit) return content;
        return content.substring(0, limit) + '...';
    };

    const filteredPosts = posts.filter(post => {
        if (filters.search && !post.title.toLowerCase().includes(filters.search.toLowerCase())) {
            return false;
        }
        if (filters.author && !post.authorName.toLowerCase().includes(filters.author.toLowerCase())) {
            return false;
        }
        return true;
    });

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-bold text-gray-900">Blog Management</h1>
                    <p className="text-gray-600">Review and manage blog posts</p>
                </div>
                
                <div className="flex gap-3">
                    <button
                        onClick={loadData}
                        disabled={loading}
                        className="inline-flex items-center px-4 py-2 border border-gray-300 rounded-md text-gray-700 bg-white hover:bg-gray-50 disabled:opacity-50"
                    >
                        <FiRefreshCw className={`w-4 h-4 mr-2 ${loading ? 'animate-spin' : ''}`} />
                        Refresh
                    </button>
                    <Link
                        to="/blog-editor?admin=1"
                        state={{ fromAdmin: true }}
                        className="inline-flex items-center px-4 py-2 border border-transparent rounded-md shadow-sm text-white bg-blue-600 hover:bg-blue-700 text-sm font-medium transition-colors"
                    >
                        <FiEdit3 className="w-4 h-4 mr-2" />
                        Write New Blog Post
                    </Link>
                </div>
            </div>

            {/* Notification */}
            {notification && (
                <div role={notification.type === 'success' ? 'status' : 'alert'} aria-live="polite" className={`p-4 rounded-lg ${
                    notification.type === 'success' ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-red-50 text-red-700 border border-red-200'
                }`}>
                    <div className="flex items-center">
                        {notification.type === 'success' ? 
                            <FiCheck className="w-5 h-5 mr-2" /> : 
                            <FiX className="w-5 h-5 mr-2" />
                        }
                        {notification.message}
                    </div>
                </div>
            )}

            {/* Stats */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                {Object.entries(stats).map(([key, value]) => (
                    <div key={key} className="bg-white p-6 rounded-lg border border-gray-200">
                        <div className="text-2xl font-bold text-gray-900">{value}</div>
                        <div className="text-sm text-gray-600 capitalize">{key} Posts</div>
                    </div>
                ))}
            </div>

            {/* Filters */}
            <div className="bg-white p-6 rounded-lg border border-gray-200 space-y-4">
                <div className="flex items-center gap-4">
                    <FiFilter className="w-5 h-5 text-gray-400" />
                    <span className="font-medium text-gray-700">Filters</span>
                </div>
                
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    <div>
                        <label htmlFor="blog-status-filter" className="block text-sm font-medium text-gray-700 mb-1">Status</label>
                        <select
                            id="blog-status-filter"
                            value={filters.status}
                            onChange={(e) => setFilters(prev => ({ ...prev, status: e.target.value }))}
                            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                        >
                            <option value="all">All Status</option>
                            <option value="draft">Draft</option>
                            <option value="pending">Pending</option>
                            <option value="approved">Approved</option>
                            <option value="scheduled">Scheduled</option>
                            <option value="rejected">Rejected</option>
                        </select>
                    </div>

                    <div>
                        <label htmlFor="blog-category-filter" className="block text-sm font-medium text-gray-700 mb-1">Category</label>
                        <select
                            id="blog-category-filter"
                            value={filters.category}
                            onChange={(e) => setFilters(prev => ({ ...prev, category: e.target.value }))}
                            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                        >
                            <option value="all">All Categories</option>
                            {categories.map(category => (
                                <option key={category.id} value={category.id}>
                                    {category.name}
                                </option>
                            ))}
                        </select>
                    </div>

                    <div>
                        <label htmlFor="blog-search-filter" className="block text-sm font-medium text-gray-700 mb-1">Filter titles on this page</label>
                        <div className="relative">
                            <FiSearch className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
                            <input
                                id="blog-search-filter"
                                type="text"
                                placeholder="Filter visible titles..."
                                value={filters.search}
                                onChange={(e) => setFilters(prev => ({ ...prev, search: e.target.value }))}
                                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                            />
                        </div>
                    </div>

                    <div>
                        <label htmlFor="blog-author-filter" className="block text-sm font-medium text-gray-700 mb-1">Filter authors on this page</label>
                        <input
                            id="blog-author-filter"
                            type="text"
                            placeholder="Filter visible authors..."
                            value={filters.author}
                            onChange={(e) => setFilters(prev => ({ ...prev, author: e.target.value }))}
                            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                        />
                    </div>
                </div>
            </div>

            <div className="flex justify-end">
                <button type="button" onClick={handlePublishDue} disabled={processing} className="rounded-md border border-purple-300 bg-purple-50 px-3 py-2 text-sm font-medium text-purple-800 disabled:opacity-50">Publish due scheduled posts</button>
            </div>

            {/* Bulk Actions */}
            {selectedPosts.length > 0 && (
                <div className="bg-blue-50 p-4 rounded-lg border border-blue-200">
                    <div className="flex items-center justify-between">
                        <div className="text-sm text-blue-700">
                            {selectedPosts.length} post(s) selected
                        </div>
                        
                        <div className="flex items-center space-x-2">
                            <button
                                onClick={() => handleBulkAction('approve')}
                                disabled={processing}
                                className="px-3 py-1 bg-green-600 text-white rounded text-sm hover:bg-green-700 disabled:opacity-50"
                            >
                                Approve
                            </button>
                            <button
                                onClick={() => handleBulkAction('reject')}
                                disabled={processing}
                                className="px-3 py-1 bg-red-600 text-white rounded text-sm hover:bg-red-700 disabled:opacity-50"
                            >
                                Reject
                            </button>
                            <button
                                onClick={() => handleBulkAction('delete')}
                                disabled={processing}
                                className="px-3 py-1 bg-gray-600 text-white rounded text-sm hover:bg-gray-700 disabled:opacity-50"
                            >
                                Delete
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Posts Table */}
            <div className="bg-white rounded-lg border border-gray-200 overflow-hidden">
                {loading ? (
                    <div className="flex items-center justify-center py-12">
                        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
                    </div>
                ) : filteredPosts.length === 0 ? (
                    <div className="text-center py-12">
                        <FiAlertCircle className="w-12 h-12 mx-auto text-gray-400 mb-4" />
                        <p className="text-gray-600">No posts found</p>
                    </div>
                ) : (
                    <>
                        <table className="min-w-full divide-y divide-gray-200">
                            <thead className="bg-gray-50">
                                <tr>
                                    <th className="w-12 px-4 py-4 text-left">
                                        <input
                                            type="checkbox"
                                            checked={selectedPosts.length === filteredPosts.length}
                                            onChange={handleSelectAll}
                                            className="h-4 w-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
                                        />
                                    </th>
                                    <th className="w-2/5 px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        Post Details
                                    </th>
                                    <th className="w-32 px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        Author
                                    </th>
                                    <th className="w-28 px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        Category
                                    </th>
                                    <th className="w-24 px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        Status
                                    </th>
                                    <th className="w-32 px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        Date
